window.STEPS=Object.assign(window.STEPS||{},{"tb-비상공수1-p036-1":{"길":"먼저 식을 A, B, C 로 줄인 뒤 차수별로 계수를 모은다","단계":[{"제목":"A, B, C 로 먼저 식 줄이기","고비":true,"힌트":"$A-2(A-B)$ 의 괄호를 풀면 $A$, $B$ 로 어떻게 쓸까?","식":["$A-2(A-B)+5C=A-2A+2B+5C$","$=-A+2B+5C$"],"설명":"분배법칙으로 괄호를 풀고 $A$ 끼리 모은다. 다항식을 넣기 전에 줄여 두면 계산할 항이 크게 줄어든다.","확인":null,"스킬":"A1"},{"제목":"차수별로 계수를 모아 정리하기","힌트":"$-A+2B+5C$ 에 세 다항식을 넣고 $x^{3},\\ x^{2},\\ x$, 상수항의 계수를 각각 모으면?","식":["$x^{3}$: $-2+2=0$","$x^{2}$: $-1-6-5=-12$","$x$: $4+2+5=11$, 상수항: $5-6-50=-51$"],"설명":"$-A$, $2B$, $5C$ 를 차수가 같은 항끼리 모은다. $x^{3}$ 항은 $-2x^{3}$ 과 $2x^{3}$ 이 서로 없어져 이차식이 된다.","확인":null,"스킬":"A1"}]},"tb-비상공수1-p036-2-1":{"길":"b-c 를 한 덩어리로 묶어 합차 공식으로 전개한다","단계":[{"제목":"b-c 를 한 덩어리로 묶기","고비":true,"힌트":"$a-b+c$ 와 $a+b-c$ 에서 $b,\\ c$ 가 들어 있는 부분을 각각 묶으면?","식":["$a-b+c=a-(b-c)$","$a+b-c=a+(b-c)$","$\\{a-(b-c)\\}\\{a+(b-c)\\}$"],"설명":"두 식에서 $b,\\ c$ 의 부호가 서로 반대라 $b-c$ 로 묶으면 $(a-X)(a+X)$ 꼴이 된다.","확인":null,"스킬":"A2"},{"제목":"합차 공식으로 전개하기","힌트":"$(a-X)(a+X)=a^{2}-X^{2}$ 에서 $X=b-c$ 로 놓고 $(b-c)^{2}$ 까지 전개하면?","식":["$a^{2}-(b-c)^{2}$","$=a^{2}-(b^{2}-2bc+c^{2})$","$=a^{2}-b^{2}+2bc-c^{2}$"],"설명":"$(b-c)^{2}$ 앞의 빼기 부호는 괄호 안 모든 항에 걸리므로 $2bc$ 의 부호가 바뀐다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p036-2-2":{"길":"합차 짝끼리 먼저 곱해 x² 에 대한 식으로 만든다","단계":[{"제목":"합차 짝끼리 묶어 곱하기","고비":true,"힌트":"$(x-1)(x+1)$ 과 $(x-2)(x+2)$ 를 각각 곱하면?","식":["$(x-1)(x+1)=x^{2}-1$","$(x-2)(x+2)=x^{2}-4$"],"설명":"네 인수를 차례로 곱하지 않고 $(a-b)(a+b)=a^{2}-b^{2}$ 이 되는 짝으로 묶으면 전개가 간단해진다.","확인":null,"스킬":"A2"},{"제목":"x² 에 대한 식으로 전개하기","힌트":"$x^{2}$ 을 한 문자로 보고 $(x^{2}-1)(x^{2}-4)$ 를 전개하면?","식":["$(x^{2}-1)(x^{2}-4)=x^{4}-4x^{2}-x^{2}+4$","$=x^{4}-5x^{2}+4$"],"설명":"$x^{2}=X$ 로 보면 $(X-1)(X-4)=X^{2}-5X+4$ 이고, 다시 $X=x^{2}$ 을 되돌린다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p036-2-3":{"길":"세 항의 제곱 공식에 부호까지 넣어 전개한다","단계":[{"제목":"세 항 제곱 공식에 대응시키기","고비":true,"힌트":"$(a+b+c)^{2}$ 에서 $a,\\ b,\\ c$ 에 해당하는 항은 무엇일까?","식":["$a=x^{2},\\ b=x,\\ c=-1$","$(a+b+c)^{2}=a^{2}+b^{2}+c^{2}+2ab+2bc+2ca$"],"설명":"$-1$ 은 부호까지 $c$ 에 넣어야 한다. 그래야 $2bc$, $2ca$ 의 부호가 저절로 맞는다.","확인":null,"스킬":"A2"},{"제목":"각 항을 계산해 합치기","힌트":"제곱 세 항의 합과 두 배 곱 세 항의 합을 각각 구하면?","식":["$a^{2}+b^{2}+c^{2}=x^{4}+x^{2}+1$","$2ab+2bc+2ca=2x^{3}-2x-2x^{2}$","$x^{4}+2x^{3}-x^{2}-2x+1$"],"설명":"$2bc=2\\times x\\times(-1)=-2x$, $2ca=2\\times(-1)\\times x^{2}=-2x^{2}$ 이다. $x^{2}$ 항은 $x^{2}$ 과 $-2x^{2}$ 을 합쳐 $-x^{2}$ 이 된다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p036-2-4":{"길":"곱셈 공식 짝을 맞춰 세제곱의 합과 차를 만든 뒤 곱한다","단계":[{"제목":"곱셈 공식 짝끼리 묶기","고비":true,"힌트":"$a+b$ 와 $a-b$ 는 각각 어느 이차식과 짝지으면 세제곱의 합·차가 될까?","식":["$(a+b)(a^{2}-ab+b^{2})=a^{3}+b^{3}$","$(a-b)(a^{2}+ab+b^{2})=a^{3}-b^{3}$"],"설명":"곱셈은 순서를 바꿔도 되므로 네 인수를 공식이 되는 짝으로 다시 묶는다. 가운데 항의 부호가 반대인 이차식이 짝이다.","확인":null,"스킬":"A2"},{"제목":"합차 공식으로 마무리하기","힌트":"$(a^{3}+b^{3})(a^{3}-b^{3})$ 을 합차 공식으로 전개하면?","식":["$(a^{3}+b^{3})(a^{3}-b^{3})=(a^{3})^{2}-(b^{3})^{2}$","$=a^{6}-b^{6}$"],"설명":"$a^{3}$ 과 $b^{3}$ 을 각각 한 덩어리로 보면 $(A+B)(A-B)=A^{2}-B^{2}$ 꼴이다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p036-3":{"길":"세제곱 전개에서 부호가 다른 항만 두 배로 남는 것을 이용한다","단계":[{"제목":"두 세제곱을 각각 전개하기","고비":true,"힌트":"$(2x+3y)^{3}$ 을 $(a+b)^{3}$ 공식으로 전개하고, $(2x-3y)^{3}$ 에서 부호는 어떻게 달라질까?","식":["$(2x+3y)^{3}=8x^{3}+36x^{2}y+54xy^{2}+27y^{3}$","$(2x-3y)^{3}=8x^{3}-36x^{2}y+54xy^{2}-27y^{3}$"],"설명":"$3y$ 가 홀수 번 곱해진 항만 $-3y$ 에서 부호가 바뀐다. $x^{3}$ 항과 $xy^{2}$ 항은 두 식에서 부호가 같다.","확인":null,"스킬":"A2"},{"제목":"빼서 남는 항 정리하기","힌트":"첫째 식에서 둘째 식을 빼면 부호가 같은 항과 다른 항은 각각 어떻게 될까?","식":["$8x^{3},\\ 54xy^{2}$ 항은 서로 없어진다","$2(36x^{2}y+27y^{3})=72x^{2}y+54y^{3}$"],"설명":"부호가 같은 항은 빼면 $0$ 이 되고, 부호가 다른 항은 같은 값이 두 번 남아 $2$ 배가 된다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p036-4":{"길":"두 식을 전개한 뒤 차수의 합이 3 인 항끼리 곱해 더한다","단계":[{"제목":"두 식을 각각 전개하기","힌트":"$(2x-1)^{3}$ 과 $(x+3)^{2}$ 을 곱셈 공식으로 전개하면?","식":["$(2x-1)^{3}=8x^{3}-12x^{2}+6x-1$","$(x+3)^{2}=x^{2}+6x+9$"],"설명":"각각 $(a-b)^{3}$, $(a+b)^{2}$ 공식으로 전개한다. 전체를 한 번에 곱해 전개하지 않아도 된다.","확인":null,"스킬":"A2"},{"제목":"차수의 합이 3 인 항의 짝 찾기","고비":true,"힌트":"곱해서 $x^{3}$ 이 되려면 앞 식과 뒤 식에서 어떤 차수의 항을 짝지어야 할까?","식":["$8x^{3}\\times9$","$-12x^{2}\\times6x$","$6x\\times x^{2}$"],"설명":"앞 식의 차수와 뒤 식의 차수를 더해 $3$ 이 되는 (앞 식 차수, 뒤 식 차수) 짝은 $(3,0),\\ (2,1),\\ (1,2)$ 이다. 앞 식의 상수항 $-1$ 은 뒤 식에 $x^{3}$ 항이 없어 짝이 없다.","확인":null,"스킬":"A2"},{"제목":"계수를 곱해 더하기","힌트":"세 짝의 계수를 각각 곱해 더하면?","식":["$8\\times9+(-12)\\times6+6\\times1$","$=72-72+6=6$"],"설명":"각 짝에서 $x$ 의 차수는 이미 $3$ 이므로 계수만 곱해서 더하면 된다.","확인":"6","스킬":"A2"}]},"tb-비상공수1-p036-5-1":{"길":"x, y 를 직접 세제곱하지 않고 합과 곱으로 바꿔 공식에 넣는다","단계":[{"제목":"x+y 와 xy 의 값 구하기","힌트":"$x+y$ 와 $xy$ 를 각각 계산하면?","식":["$x+y=(1+\\sqrt{3})+(1-\\sqrt{3})=2$","$xy=(1+\\sqrt{3})(1-\\sqrt{3})=1-3=-2$"],"설명":"$x+y$ 는 근호 항이 서로 없어지고, $xy$ 는 합차 공식 $(a+b)(a-b)=a^{2}-b^{2}$ 으로 계산한다.","확인":null,"스킬":"A2"},{"제목":"세제곱의 합 공식에 값 넣기","고비":true,"힌트":"$x^{3}+y^{3}$ 을 $x+y$ 와 $xy$ 로만 나타내면?","식":["$x^{3}+y^{3}=(x+y)^{3}-3xy(x+y)$","$=2^{3}-3\\times(-2)\\times2$","$=8+12=20$"],"설명":"$(x+y)^{3}=x^{3}+y^{3}+3xy(x+y)$ 이므로 $3xy(x+y)$ 를 옮겨 $x^{3}+y^{3}$ 을 구한다. $xy=-2$ 라서 빼는 항이 더하는 값이 된다.","확인":"20","스킬":"A2"}]},"tb-비상공수1-p036-5-2":{"길":"x-y 와 xy 로 바꿔 세제곱의 차 공식에 값을 넣는다","단계":[{"제목":"x-y 와 xy 의 값 구하기","힌트":"$x-y$ 와 $xy$ 를 각각 계산하면?","식":["$x-y=(1+\\sqrt{3})-(1-\\sqrt{3})=2\\sqrt{3}$","$xy=(1+\\sqrt{3})(1-\\sqrt{3})=-2$"],"설명":"$x-y$ 는 상수 $1$ 이 없어지고 근호 항이 두 배로 남는다. $xy$ 는 합차 공식으로 구한다.","확인":null,"스킬":"A2"},{"제목":"x³-y³ 을 x-y 와 xy 로 나타내기","고비":true,"힌트":"$(x-y)^{3}$ 을 전개해 $x^{3}-y^{3}$ 에 대한 식으로 옮기면?","식":["$(x-y)^{3}=x^{3}-y^{3}-3xy(x-y)$","$x^{3}-y^{3}=(x-y)^{3}+3xy(x-y)$"],"설명":"$(x-y)^{3}=x^{3}-3x^{2}y+3xy^{2}-y^{3}$ 에서 가운데 두 항은 $-3xy(x-y)$ 로 묶인다. 이 항을 우변으로 옮기면 가운데 부호가 플러스가 된다.","확인":null,"스킬":"A2"},{"제목":"값을 넣어 계산하기","힌트":"$x-y=2\\sqrt{3}$, $xy=-2$ 를 넣어 계산하면?","식":["$(2\\sqrt{3})^{3}=24\\sqrt{3}$","$3\\times(-2)\\times2\\sqrt{3}=-12\\sqrt{3}$","$x^{3}-y^{3}=24\\sqrt{3}-12\\sqrt{3}=12\\sqrt{3}$"],"설명":"$(2\\sqrt{3})^{3}=8\\times3\\sqrt{3}$ 이다. $xy$ 가 음수라 두 번째 항은 음수가 되어 빼는 꼴이 된다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p036-6":{"길":"나눗셈을 등식으로 쓰고 나머지를 옮긴 뒤 몫으로 나눈다","단계":[{"제목":"나눗셈을 등식으로 쓰기","힌트":"나누어지는 식 = 나누는 식 × 몫 + 나머지 로 쓰면?","식":["$4x^{3}-x^{2}+3x-1=A(4x-9)+33x-28$"],"설명":"다항식을 $A$ 로 나눈 몫이 $4x-9$, 나머지가 $33x-28$ 이므로 위와 같은 등식이 성립한다.","확인":null,"스킬":"A4"},{"제목":"나머지를 옮겨 A 와 몫의 곱 정리하기","힌트":"나머지를 좌변으로 옮기면 $A(4x-9)$ 는 어떤 식일까?","식":["$A(4x-9)=4x^{3}-x^{2}+3x-1-(33x-28)$","$=4x^{3}-x^{2}-30x+27$"],"설명":"나머지 $33x-28$ 을 빼면 $A$ 와 몫의 곱만 남는다. 괄호 앞의 빼기 부호가 $-28$ 을 $+28$ 로 바꾼다.","확인":null,"스킬":"A4"},{"제목":"몫으로 나누어 A 구하기","고비":true,"힌트":"$4x^{3}-x^{2}-30x+27$ 을 $4x-9$ 로 나누면?","식":["$4x^{3}-x^{2}-30x+27=(4x-9)(x^{2}+2x-3)$","$A=x^{2}+2x-3$"],"설명":"최고차항부터 차례로 몫을 세우면 $x^{2},\\ 2x,\\ -3$ 이 나오고 나머지는 $0$ 이다. 곱해서 되돌려 확인할 수 있다.","확인":null,"스킬":"A4"}]},"tb-비상공수1-p036-8":{"길":"x-1/2 로 조립제법을 한 뒤 몫을 2 로 나눠 2x-1 의 몫으로 바꾼다","단계":[{"제목":"조립제법의 기준값과 계수 정하기","힌트":"$2x-1=0$ 이 되는 $x$ 의 값이 조립제법의 기준이다. 그 값은?","식":["$2x-1=0$ 에서 $x=\\frac{1}{2}$","$4x^{3}-7x+1$ 의 계수: $4,\\ 0,\\ -7,\\ 1$"],"설명":"조립제법은 일차식이 $0$ 이 되는 값으로 한다. $x^{2}$ 항이 없으므로 그 자리의 계수를 $0$ 으로 채워 쓴다.","확인":"1/2","스킬":"A4"},{"제목":"조립제법으로 아래 줄 계산하기","힌트":"$4,\\ 0,\\ -7,\\ 1$ 을 $\\frac{1}{2}$ 로 조립제법하면 맨 끝의 수는?","식":["아래 줄: $4,\\ 2,\\ -6,\\ -2$","$4x^{3}-7x+1=\\left(x-\\frac{1}{2}\\right)(4x^{2}+2x-6)-2$"],"설명":"맨 앞의 $4$ 를 내리고 $\\frac{1}{2}$ 을 곱해 다음 계수에 더하기를 반복한다. 맨 끝의 수가 나머지이다.","확인":"-2","스킬":"A4"},{"제목":"몫을 2x-1 에 맞춰 바꾸기","고비":true,"힌트":"$x-\\frac{1}{2}$ 를 $2x-1$ 로 바꾸려면 몫 $4x^{2}+2x-6$ 은 어떻게 달라질까?","식":["$\\left(x-\\frac{1}{2}\\right)(4x^{2}+2x-6)=(2x-1)(2x^{2}+x-3)$","몫 $2x^{2}+x-3$, 나머지 $-2$"],"설명":"$x-\\frac{1}{2}=\\frac{1}{2}(2x-1)$ 이므로 $4x^{2}+2x-6$ 의 절반이 $2x-1$ 로 나눈 몫이 된다. 나머지는 곱하는 값과 무관해 그대로 $-2$ 이다.","확인":null,"스킬":"A4"}]},"tb-비상공수1-p037-1":{"길":"우변을 전개해 같은 차수끼리 계수를 비교한다","단계":[{"제목":"우변을 차수별로 전개하기","힌트":"$(x+b)(x^{2}+cx-12)$ 를 $x$ 의 차수별로 정리하면?","식":["$(x+b)(x^{2}+cx-12)=x^{3}+(b+c)x^{2}+(bc-12)x-12b$"],"설명":"각 항을 곱해 $x^{2}$ 항 $(b+c)x^{2}$, $x$ 항 $(bc-12)x$, 상수항 $-12b$ 로 모은다.","확인":null,"스킬":"A3"},{"제목":"상수항을 비교해 b 구하기","고비":true,"힌트":"양변의 상수항이 같다는 식에서 $b$ 는?","식":["$-24=-12b$","$b=2$"],"설명":"항등식이므로 양변의 같은 차수끼리 계수가 같다. 상수항 비교가 한 문자만 남아 가장 먼저 풀린다.","확인":"2","스킬":"A3"},{"제목":"나머지 차수의 계수를 비교해 c, a 구하기","힌트":"좌변에 $x$ 항이 없다는 점으로 $c$ 를, $x^{2}$ 의 계수 비교로 $a$ 를 구하면?","식":["$x$ 의 계수: $0=bc-12$ 에서 $2c=12$, $c=6$","$x^{2}$ 의 계수: $a=b+c=8$"],"설명":"좌변 $x^{3}+ax^{2}-24$ 에는 $x$ 항이 없으므로 $x$ 의 계수는 $0$ 이다. $b=2$ 를 넣어 $c$ 를 구하고, $x^{2}$ 의 계수에서 $a$ 를 정한다.","확인":null,"스킬":"A3"}]},"tb-비상공수1-p037-2":{"길":"괄호가 0 이 되는 x=0, 1, 2 를 넣어 문자를 하나씩 구한다","단계":[{"제목":"x=0 을 넣어 a 구하기","고비":true,"힌트":"$x=0$ 을 넣으면 우변에서 어떤 항들이 사라질까?","식":["$x=0$: $4=a\\times(-1)$","$a=-4$"],"설명":"항등식은 모든 $x$ 에서 성립하므로 $x=0$ 을 넣어도 된다. $bx(x-1)$ 과 $cx(x-2)$ 가 $0$ 이 되어 $a$ 만 남는다.","확인":"-4","스킬":"A3"},{"제목":"x=1 을 넣어 c 구하기","힌트":"$x=1$ 을 넣으면 우변에서 남는 항은?","식":["$x=1$: $8=c\\times1\\times(-1)$","$c=-8$"],"설명":"$x=1$ 이면 $a(x-1)$ 과 $bx(x-1)$ 이 $0$ 이 되어 $c$ 항만 남는다. 좌변은 $1+3+4=8$ 이다.","확인":"-8","스킬":"A3"},{"제목":"x=2 를 넣어 b 구하기","힌트":"$x=2$ 를 넣고 구한 $a$ 를 대입하면 $b$ 는?","식":["$x=2$: $14=a+2b$","$14=-4+2b$, 즉 $b=9$"],"설명":"$x=2$ 이면 $cx(x-2)$ 가 $0$ 이 되어 $a$ 와 $b$ 만 남는다. 좌변은 $4+6+4=14$ 이고 $a(2-1)+2b(2-1)=a+2b$ 이다.","확인":null,"스킬":"A3"}]},"tb-비상공수1-p037-3":{"길":"나머지정리로 P(-1)=2 를 세워 a 를 구한다","단계":[{"제목":"나머지정리로 P(-1) 식 세우기","고비":true,"힌트":"$x+1$ 로 나눈 나머지는 $P(x)$ 에 어떤 값을 넣은 것과 같을까?","식":["$x+1=0$ 이 되는 $x=-1$ 을 넣는다","$P(-1)=-1+a-13+9=a-5$"],"설명":"일차식 $x-\\alpha$ 로 나눈 나머지는 $P(\\alpha)$ 이다. $x+1=x-(-1)$ 이므로 $x=-1$ 을 넣는다.","확인":null,"스킬":"A4"},{"제목":"나머지 조건으로 a 구하기","힌트":"$P(-1)=2$ 에서 $a$ 는?","식":["$a-5=2$","$a=7$"],"설명":"나머지가 $2$ 이므로 $P(-1)=2$ 이다. 이 일차방정식을 푼다.","확인":"7","스킬":"A4"}]},"tb-비상공수1-p037-4":{"길":"두 나머지를 P(2), P(-2) 로 쓰고 같다고 놓는다","단계":[{"제목":"두 나머지를 a 로 나타내기","고비":true,"힌트":"$x-2$ 로 나눈 나머지와 $x+2$ 로 나눈 나머지는 각각 $P(x)$ 에 무엇을 넣은 값일까?","식":["$P(2)=8-8+2a+3=2a+3$","$P(-2)=-8-8-2a+3=-2a-13$"],"설명":"나머지정리에서 $x-2$ 로 나눈 나머지는 $P(2)$, $x+2$ 로 나눈 나머지는 $P(-2)$ 이다. $-2$ 를 넣을 때 부호에 주의한다.","확인":null,"스킬":"A4"},{"제목":"두 나머지가 같다는 식 풀기","힌트":"$P(2)=P(-2)$ 로 놓고 $a$ 를 구하면?","식":["$2a+3=-2a-13$","$4a=-16$","$a=-4$"],"설명":"두 나머지가 같으므로 $P(2)=P(-2)$ 이다. $a$ 항을 한쪽으로 모으고 상수항을 이항한다.","확인":"-4","스킬":"A4"}]},"tb-비상공수1-p037-5":{"길":"나머지를 ax+b 로 두고 두 일차식의 근을 넣어 a, b 를 구한다","단계":[{"제목":"나머지를 ax+b 로 놓고 등식 쓰기","힌트":"이차식으로 나눈 나머지는 몇 차 이하의 식일까?","식":["$P(x)=(x+3)(x-1)Q(x)+ax+b$"],"설명":"나누는 식이 이차식이므로 나머지는 일차 이하의 식이다. 몫을 $Q(x)$, 나머지를 $ax+b$ 로 놓는다.","확인":null,"스킬":"A4"},{"제목":"두 값을 넣어 a, b 의 연립식 세우기","고비":true,"힌트":"$x=-3$, $x=1$ 을 넣으면 $Q(x)$ 가 들어 있는 항은 어떻게 될까?","식":["$P(-3)=-3a+b=1$","$P(1)=a+b=-7$"],"설명":"$x=-3$ 이나 $x=1$ 이면 $(x+3)(x-1)=0$ 이라 몫 항이 사라진다. 나머지정리에서 $P(-3)=1$, $P(1)=-7$ 이다.","확인":null,"스킬":"A4"},{"제목":"연립해 a, b 를 구하고 나머지 쓰기","힌트":"두 식을 변끼리 빼서 $a$ 를 먼저 구하면?","식":["두 식을 빼면 $-4a=8$, $a=-2$","$b=-7-a=-5$","나머지: $-2x-5$"],"설명":"$(-3a+b)-(a+b)=1-(-7)$ 이므로 $b$ 가 사라져 $a$ 가 나온다. 구한 $a$ 를 $a+b=-7$ 에 넣어 $b$ 를 구한다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p037-6":{"길":"나누어떨어지면 나머지가 0 이므로 P(1)=0, P(-1)=0 으로 연립한다","단계":[{"제목":"인수정리로 두 식 세우기","고비":true,"힌트":"$x-1$, $x+1$ 로 나누어떨어질 때 $P(1)$, $P(-1)$ 의 값은?","식":["$P(1)=2+a+b+1=a+b+3=0$","$P(-1)=-2+a-b+1=a-b-1=0$"],"설명":"나누어떨어지면 나머지가 $0$ 이므로 $P(1)=0$, $P(-1)=0$ 이다. $-1$ 을 넣을 때 $b$ 항의 부호가 바뀐다.","확인":null,"스킬":"A4"},{"제목":"연립해 a, b 구하기","힌트":"두 식을 변끼리 더하면 어느 문자가 사라질까?","식":["두 식을 더하면 $2a+2=0$, $a=-1$","$b=-3-a=-2$"],"설명":"$a+b=-3$, $a-b=1$ 이므로 더하면 $b$ 가 사라진다. 구한 $a$ 를 $a+b=-3$ 에 넣어 $b$ 를 구한다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p037-7":{"길":"나누는 이차식을 인수분해해 두 근을 P 에 넣고 a, b 를 구한다","단계":[{"제목":"나누는 이차식 인수분해하기","힌트":"$x^{2}-2x-3$ 을 두 일차식의 곱으로 나타내면?","식":["$x^{2}-2x-3=(x+1)(x-3)$"],"설명":"곱이 $-3$ 이고 합이 $-2$ 인 두 수는 $1$ 과 $-3$ 이다. 나누어떨어지면 $x+1$, $x-3$ 으로도 각각 나누어떨어진다.","확인":null,"스킬":"A4"},{"제목":"P(-1)=0, P(3)=0 으로 연립식 세우기","고비":true,"힌트":"두 일차식으로 나누어떨어지므로 $x=-1$, $x=3$ 을 넣은 값은?","식":["$P(-1)=-1-3-a+b=-a+b-4=0$","$P(3)=27-27+3a+b=3a+b=0$"],"설명":"나머지가 $0$ 이므로 $P(-1)=0$, $P(3)=0$ 이다. $x^{3}-3x^{2}$ 은 $x=3$ 에서 $0$ 이 되어 식이 짧아진다.","확인":null,"스킬":"A4"},{"제목":"연립해 a+b 구하기","힌트":"첫째 식에서 $b$ 를 $a$ 로 나타내 둘째 식에 넣으면 $a$ 는?","식":["$b=a+4$ 를 $3a+b=0$ 에 넣으면 $4a+4=0$, $a=-1$","$b=3$","$a+b=2$"],"설명":"한 문자를 다른 문자로 나타내 대입하면 일차방정식이 된다. 구한 $a$, $b$ 를 더한다.","확인":"2","스킬":"A10"}]},"tb-비상공수1-p038-1-1":{"길":"125b³ 을 (5b)³ 으로 보고 세제곱의 합 공식에 넣는다","단계":[{"제목":"125b³ 을 세제곱으로 나타내기","고비":true,"힌트":"$125b^{3}$ 은 어떤 식의 세제곱일까?","식":["$125b^{3}=(5b)^{3}$","$a^{3}+125b^{3}=a^{3}+(5b)^{3}$"],"설명":"$125=5^{3}$ 이므로 $125b^{3}=(5b)^{3}$ 이다. 두 항이 모두 세제곱이면 세제곱의 합 공식을 쓸 수 있다.","확인":null,"스킬":"A2"},{"제목":"세제곱의 합 공식 적용하기","힌트":"$A^{3}+B^{3}=(A+B)(A^{2}-AB+B^{2})$ 에 $A=a,\\ B=5b$ 를 넣으면?","식":["$(a+5b)\\{a^{2}-a\\times5b+(5b)^{2}\\}$","$=(a+5b)(a^{2}-5ab+25b^{2})$"],"설명":"가운데 항은 $AB=a\\times5b=5ab$ 이고 마지막 항은 $B^{2}=(5b)^{2}=25b^{2}$ 이다. 괄호 안의 가운데 부호는 마이너스이다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p038-1-2":{"길":"첫 항과 끝 항에서 a 와 2 를 읽어 (a-2)³ 으로 묶는다","단계":[{"제목":"첫 항과 끝 항에서 a, 2 읽기","고비":true,"힌트":"$a^{3}$ 과 $8$ 은 각각 무엇의 세제곱일까? 가운데 두 항도 같은 꼴로 쓰면?","식":["$a^{3}=a^{3},\\ 8=2^{3}$","$a^{3}-3\\cdot a^{2}\\cdot2+3\\cdot a\\cdot2^{2}-2^{3}$"],"설명":"$-6a^{2}=-3\\cdot a^{2}\\cdot2$ 이고 $12a=3\\cdot a\\cdot2^{2}$ 이다. 가운데 두 항이 $(a-2)^{3}$ 의 전개와 정확히 맞는지 확인한다.","확인":null,"스킬":"A2"},{"제목":"완전세제곱 공식으로 묶기","힌트":"$(a-b)^{3}=a^{3}-3a^{2}b+3ab^{2}-b^{3}$ 에서 $b=2$ 로 놓으면?","식":["$a^{3}-6a^{2}+12a-8=(a-2)^{3}$"],"설명":"부호가 번갈아 나타나는 꼴이므로 $(a-b)^{3}$ 공식에 $b=2$ 를 넣은 것이다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p038-1-3":{"길":"첫 항과 끝 항에서 3x 와 2y 를 읽어 (3x+2y)³ 으로 묶는다","단계":[{"제목":"첫 항과 끝 항에서 3x, 2y 읽기","고비":true,"힌트":"$27x^{3}$ 과 $8y^{3}$ 은 각각 어떤 식의 세제곱일까?","식":["$27x^{3}=(3x)^{3}$","$8y^{3}=(2y)^{3}$"],"설명":"$27=3^{3}$, $8=2^{3}$ 이므로 $A=3x$, $B=2y$ 로 놓고 $(A+B)^{3}$ 꼴인지 확인한다.","확인":null,"스킬":"A2"},{"제목":"가운데 두 항을 확인해 묶기","힌트":"$3(3x)^{2}(2y)$ 와 $3(3x)(2y)^{2}$ 을 계산해 가운데 두 항과 맞는지 보면?","식":["$3(3x)^{2}(2y)=54x^{2}y$","$3(3x)(2y)^{2}=36xy^{2}$","$27x^{3}+54x^{2}y+36xy^{2}+8y^{3}=(3x+2y)^{3}$"],"설명":"$(A+B)^{3}=A^{3}+3A^{2}B+3AB^{2}+B^{3}$ 의 가운데 두 항이 주어진 식과 같으므로 한 덩어리로 묶인다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p038-1-4":{"길":"제곱 세 항을 읽고 곱 항의 부호를 맞춰 완전제곱식으로 묶는다","단계":[{"제목":"제곱 항에서 세 항 읽기","힌트":"$4a^{2},\\ b^{2},\\ 9c^{2}$ 은 각각 무엇의 제곱일까?","식":["$4a^{2}=(2a)^{2}$","$b^{2}=(\\pm b)^{2}$","$9c^{2}=(3c)^{2}$"],"설명":"제곱 항으로 세 항의 크기가 정해진다. 각 항의 부호는 곱 항 $-4ab,\\ -6bc,\\ 12ca$ 의 부호로 정한다.","확인":null,"스킬":"A2"},{"제목":"곱 항의 부호로 세 항의 부호 정하기","고비":true,"힌트":"$ab,\\ bc$ 항은 음수이고 $ca$ 항은 양수이다. 어느 항에 마이너스를 붙이면 세 곱 항이 모두 맞을까?","식":["$2(2a)(-b)=-4ab$","$2(-b)(3c)=-6bc$","$2(3c)(2a)=12ca$"],"설명":"$b$ 만 음수로 두면 $b$ 가 들어간 두 곱 항이 음수가 되고 $2a$ 와 $3c$ 의 곱은 양수로 남는다. 세 곱 항이 모두 주어진 식과 같다.","확인":null,"스킬":"A2"},{"제목":"세 항의 제곱 꼴로 묶기","힌트":"$(A+B+C)^{2}$ 공식에 $A=2a,\\ B=-b,\\ C=3c$ 를 넣어 쓰면?","식":["$(2a)^{2}+(-b)^{2}+(3c)^{2}+2(2a)(-b)+2(-b)(3c)+2(3c)(2a)$","$=(2a-b+3c)^{2}$"],"설명":"제곱 세 항과 두 배 곱 세 항이 모두 맞으므로 $(2a-b+3c)^{2}$ 으로 묶인다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p038-2":{"길":"x² 을 X 로 치환해 완전제곱으로 만들고 a, b 를 읽는다","단계":[{"제목":"x² 을 X 로 치환해 인수분해하기","고비":true,"힌트":"$x^{2}=X$ 로 놓으면 $X^{2}-8X+16$ 은 어떤 완전제곱식일까?","식":["$X^{2}-8X+16=(X-4)^{2}$","$x^{4}-8x^{2}+16=(x^{2}-4)^{2}$"],"설명":"$x^{4}=(x^{2})^{2}$ 이므로 $x^{2}$ 을 한 문자로 보면 이차식이 된다. $16=4^{2}$, $8=2\\times4$ 라서 완전제곱식이다.","확인":null,"스킬":"A1"},{"제목":"x²-4 를 다시 인수분해해 a-b 구하기","힌트":"$x^{2}-4$ 를 인수분해해 $(x+a)^{2}(x-b)^{2}$ 와 비교하면 $a-b$ 는?","식":["$(x^{2}-4)^{2}=\\{(x+2)(x-2)\\}^{2}=(x+2)^{2}(x-2)^{2}$","$a=2,\\ b=2$","$a-b=0$"],"설명":"$x^{2}-4$ 는 합차 공식으로 한 번 더 인수분해된다. $a>0$, $b>0$ 이므로 $x+2$ 와 $x+a$, $x-2$ 와 $x-b$ 를 각각 짝지을 수 있다.","확인":"0","스킬":"A1"}]},"tb-비상공수1-p038-3":{"길":"x²-2x 를 X 로 치환해 X(X-11) 까지 인수분해한 뒤 되돌린다","단계":[{"제목":"x²-2x 를 X 로 치환해 식 바꾸기","고비":true,"힌트":"$x^{2}-2x$ 가 되풀이된다. 이를 $X$ 로 놓고 식을 다시 쓰면?","식":["$X=x^{2}-2x$ 라 하면 $x^{2}-2x-3=X-3,\\ x^{2}-2x-8=X-8$","$(X-3)(X-8)-24$"],"설명":"두 이차식의 $x^{2}-2x$ 부분이 같아 한 문자로 묶을 수 있다. $X$ 에 대한 이차식이 되어 전개가 간단해진다.","확인":null,"스킬":"A1"},{"제목":"X 에 대한 식 인수분해하기","힌트":"$(X-3)(X-8)-24$ 를 전개하면 상수항은 어떻게 될까?","식":["$(X-3)(X-8)-24=X^{2}-11X+24-24$","$=X(X-11)$"],"설명":"상수항 $24$ 와 $-24$ 가 서로 없어져 $X$ 로 묶인다.","확인":null,"스킬":"A1"},{"제목":"X 를 되돌려 인수 고르기","힌트":"$X=x^{2}-2x$ 를 되돌리고 $x^{2}-2x$ 도 인수분해하면 보기 중 인수는?","식":["$X(X-11)=(x^{2}-2x)(x^{2}-2x-11)$","$=x(x-2)(x^{2}-2x-11)$","인수: ㄱ, ㄷ, ㄹ, ㅂ"],"설명":"$x^{2}-2x=x(x-2)$ 이므로 $x$, $x-2$, $x^{2}-2x$ 가 모두 인수이다. ㄴ $x+2$ 와 ㅁ $x^{2}+2x-11$ 은 곱에 나타나지 않는다.","확인":null,"스킬":"A1"}]},"tb-비상공수1-p038-4":{"길":"475 를 x 로 놓고 분자를 인수분해해 분모와 약분한다","단계":[{"제목":"475 를 x 로 놓고 식 바꾸기","고비":true,"힌트":"$475=x$ 로 놓으면 $474$ 는 $x$ 로 어떻게 쓰고, 분모는 $x$ 의 어떤 식일까?","식":["$474=x-1$","$\\dfrac{475^{3}+1}{474\\times475+1}=\\dfrac{x^{3}+1}{(x-1)x+1}$","$(x-1)x+1=x^{2}-x+1$"],"설명":"큰 수를 문자로 놓으면 분자는 세제곱의 합, 분모는 이차식이 된다. $474$ 는 $475-1$ 이라 $x-1$ 이다.","확인":null,"스킬":"A1"},{"제목":"인수분해로 약분해 값 구하기","힌트":"$x^{3}+1$ 을 세제곱의 합 공식으로 인수분해하면 분모와 어떤 관계일까?","식":["$x^{3}+1=(x+1)(x^{2}-x+1)$","$\\dfrac{(x+1)(x^{2}-x+1)}{x^{2}-x+1}=x+1$","$x+1=475+1=476$"],"설명":"분자의 인수 $x^{2}-x+1$ 이 분모와 같아 약분된다. 마지막에 $x=475$ 를 되돌려 넣는다.","확인":"476","스킬":"A1"}]},"tb-비상공수1-p038-6":{"길":"P(±1) 로 인수를 찾고 조립제법으로 내려 인수분해한다","단계":[{"제목":"P 의 값이 0 이 되는 수 찾기","고비":true,"힌트":"상수항 $-2$ 의 약수 $\\pm1,\\ \\pm2$ 중 $P(x)=x^{3}-3x-2$ 에 넣어 $0$ 이 되는 수를 찾으면?","식":["$P(1)=1-3-2=-4\\ne0$","$P(-1)=-1+3-2=0$"],"설명":"정수 계수 다항식의 정수 근은 상수항의 약수 중에 있다. $P(-1)=0$ 이므로 인수정리에 따라 $x+1$ 이 인수이다.","확인":null,"스킬":"A4"},{"제목":"조립제법으로 몫 구하기","힌트":"$1,\\ 0,\\ -3,\\ -2$ 를 $-1$ 로 조립제법하면 몫의 계수는?","식":["아래 줄: $1,\\ -1,\\ -2,\\ 0$","$x^{3}-3x-2=(x+1)(x^{2}-x-2)$"],"설명":"$x^{2}$ 항이 없어 계수 자리에 $0$ 을 넣는다. 나머지가 $0$ 이면 몫이 이차식 $x^{2}-x-2$ 이다.","확인":null,"스킬":"A4"},{"제목":"몫을 인수분해해 a+b 구하기","힌트":"$x^{2}-x-2$ 를 인수분해해 $(x+a)^{2}(x+b)$ 와 비교하면?","식":["$x^{2}-x-2=(x+1)(x-2)$","$x^{3}-3x-2=(x+1)^{2}(x-2)$","$a=1,\\ b=-2$, $a+b=-1$"],"설명":"$x+1$ 이 두 번 나타나므로 $(x+1)^{2}$ 가 $(x+a)^{2}$ 에 해당하고 남은 $x-2$ 가 $x+b$ 이다.","확인":"-1","스킬":"A4"}]},"tb-비상공수1-p038-7":{"길":"상수항의 약수를 대입해 인수를 찾고 조립제법을 두 번 한다","단계":[{"제목":"대입해 인수 두 개 찾기","고비":true,"힌트":"상수항 $12$ 의 약수 중 $P(x)$ 에 넣어 $0$ 이 되는 수를 찾으면?","식":["$P(1)=1+2-7-8+12=0$","$P(2)=16+16-28-16+12=0$","$x-1,\\ x-2$ 가 인수"],"설명":"$P(\\alpha)=0$ 이면 $x-\\alpha$ 가 인수이다. 작은 약수부터 차례로 넣어 본다.","확인":null,"스킬":"A4"},{"제목":"조립제법을 두 번 해 몫 구하기","힌트":"$x-1$ 로 조립제법한 몫을 다시 $x-2$ 로 조립제법하면 마지막 몫은?","식":["$1$ 로: $1,\\ 3,\\ -4,\\ -12,\\ 0$","$2$ 로: $1,\\ 5,\\ 6,\\ 0$","$P(x)=(x-1)(x-2)(x^{2}+5x+6)$"],"설명":"첫 조립제법의 몫 $x^{3}+3x^{2}-4x-12$ 에서 $x=2$ 가 다시 근이므로 한 번 더 내린다.","확인":null,"스킬":"A4"},{"제목":"이차식을 인수분해해 마무리하기","힌트":"$x^{2}+5x+6$ 을 두 일차식의 곱으로 나타내면?","식":["$x^{2}+5x+6=(x+2)(x+3)$","$P(x)=(x-1)(x-2)(x+2)(x+3)$"],"설명":"곱이 $6$ 이고 합이 $5$ 인 두 수는 $2$ 와 $3$ 이다.","확인":null,"스킬":"A4"}]},"tb-비상공수1-p039-1-1":{"길":"실수부분과 허수부분을 각각 같다고 놓아 연립방정식으로 푼다","단계":[{"제목":"실수부분·허수부분 각각 같게 놓기","고비":true,"힌트":"두 복소수가 같으면 어느 부분끼리 같을까?","식":["$x+2y=-1$","$6=2y$"],"설명":"복소수가 서로 같으면 실수부분끼리, 허수부분끼리 각각 같다. 우변의 허수부분은 $2y$ 이므로 $6=2y$ 이다.","확인":null,"스킬":"A10"},{"제목":"y 의 값 구하기","힌트":"허수부분의 식에서 $y$ 는 얼마일까?","식":["$2y=6$","$y=3$"],"설명":"허수부분의 식에는 $y$ 만 들어 있어 바로 $y$ 가 정해진다.","확인":"3","스킬":"A10"},{"제목":"x 의 값 구하기","힌트":"구한 $y$ 를 실수부분의 식에 넣으면 $x$ 는?","식":["$x+2\\times3=-1$","$x=-7$"],"설명":"$y=3$ 을 $x+2y=-1$ 에 대입하면 $x+6=-1$ 이므로 $x=-7$ 이다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p039-1-2":{"길":"좌변을 실수부분과 허수부분으로 묶은 뒤 각각 같다고 놓아 연립한다","단계":[{"제목":"실수·허수부분으로 묶어 연립식 세우기","고비":true,"힌트":"좌변을 $i$ 가 없는 부분과 $i$ 가 붙은 부분으로 묶으면?","식":["$(3x+2y)+(-4x+y)i=4-9i$","$3x+2y=4$","$-4x+y=-9$"],"설명":"$x$, $y$ 가 실수이므로 좌변의 실수부분은 $3x+2y$, 허수부분은 $-4x+y$ 이다. 양변의 실수부분끼리, 허수부분끼리 같게 놓는다.","확인":null,"스킬":"A10"},{"제목":"y 를 소거해 x 구하기","힌트":"둘째 식을 $y$ 에 대해 정리해 첫째 식에 넣으면 $x$ 는?","식":["$y=4x-9$","$3x+2(4x-9)=4$","$11x=22$"],"설명":"둘째 식에서 $y=4x-9$ 이다. 이를 첫째 식에 대입하면 $y$ 가 사라지고 $x$ 에 대한 일차방정식이 된다.","확인":"2","스킬":"A10"},{"제목":"y 의 값 구하기","힌트":"구한 $x$ 를 $y=4x-9$ 에 넣으면 $y$ 는?","식":["$y=4\\times2-9=-1$"],"설명":"$x=2$ 를 대입해 $y$ 를 구하면 $x=2$, $y=-1$ 이다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p039-2-1":{"길":"복소수의 덧셈은 실수부분끼리, 허수부분끼리 더한다","단계":[{"제목":"실수부분끼리, 허수부분끼리 모으기","고비":true,"힌트":"실수부분끼리와 허수부분끼리 따로 더하면?","식":["$(5+5)+(2i-2i)$"],"설명":"복소수의 덧셈은 실수부분은 실수부분끼리, 허수부분은 허수부분끼리 더한다. 허수부분은 $2i$ 와 $-2i$ 이다.","확인":null,"스킬":"A5"},{"제목":"값 구하기","힌트":"허수부분이 사라지면 남는 값은?","식":["$10+0i=10$"],"설명":"$2i-2i=0$ 이므로 허수부분은 없어지고 실수 $10$ 만 남는다. 켤레복소수끼리의 합은 항상 실수이다.","확인":"10","스킬":"A5"}]},"tb-비상공수1-p039-2-2":{"길":"뺄셈도 실수부분끼리, 허수부분끼리 따로 계산한다","단계":[{"제목":"실수부분끼리 빼기","힌트":"실수부분끼리 빼면 얼마일까?","식":["$6-2=4$"],"설명":"복소수의 뺄셈도 실수부분은 실수부분끼리 계산한다.","확인":"4","스킬":"A5"},{"제목":"허수부분끼리 빼기","고비":true,"힌트":"허수부분은 $3i$ 에서 $7i$ 를 빼면?","식":["$3i-7i=-4i$","$4-4i$"],"설명":"괄호 앞의 빼기는 허수부분 $7i$ 에도 적용되므로 $3i-7i=-4i$ 이다. 실수부분과 합치면 $4-4i$ 이다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p039-2-3":{"길":"합차 꼴로 전개한 뒤 i²을 -1로 바꾼다","단계":[{"제목":"합차 꼴로 전개하기","힌트":"$(a+b)(a-b)=a^{2}-b^{2}$ 을 쓰면 전개한 식은?","식":["$(4+2i)(4-2i)=4^{2}-(2i)^{2}=16-4i^{2}$"],"설명":"두 복소수는 서로 켤레이므로 합차 꼴이다. $(2i)^{2}=4i^{2}$ 이다.","확인":null,"스킬":"A5"},{"제목":"i² 을 -1 로 바꾸어 계산하기","고비":true,"힌트":"$i^{2}=-1$ 을 넣으면 값은?","식":["$16-4\\times(-1)=16+4=20$"],"설명":"$i^{2}=-1$ 이므로 $-4i^{2}=+4$ 가 된다. 빼기가 더하기로 바뀌는 부분에서 부호 실수가 잦다.","확인":"20","스킬":"A5"}]},"tb-비상공수1-p039-2-4":{"길":"분배법칙으로 전개한 뒤 i²을 -1로 바꿔 실수부분과 허수부분을 모은다","단계":[{"제목":"분배법칙으로 전개하기","힌트":"$(2i+7)(3i-1)$ 의 네 항 곱을 모두 쓰면?","식":["$(2i+7)(3i-1)=6i^{2}-2i+21i-7$"],"설명":"$2i\\times3i=6i^{2}$, $2i\\times(-1)=-2i$, $7\\times3i=21i$, $7\\times(-1)=-7$ 이다.","확인":null,"스킬":"A5"},{"제목":"i² 을 바꿔 실수부분 구하기","고비":true,"힌트":"$i^{2}=-1$ 로 바꾸면 실수인 항을 모두 더한 값은?","식":["$6i^{2}=-6$","$-6-7=-13$"],"설명":"$i^{2}$ 이 들어 있는 항은 실수가 된다. $6i^{2}=-6$ 이므로 실수부분은 $-6-7$ 이다.","확인":"-13","스킬":"A5"},{"제목":"허수부분 정리하기","힌트":"$i$ 가 붙은 항을 더하면?","식":["$-2i+21i=19i$","$-13+19i$"],"설명":"허수부분끼리 더하면 $19i$ 이므로 실수부분과 합쳐 $-13+19i$ 이다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p039-2-5":{"길":"분모의 켤레복소수를 분모·분자에 곱해 분모를 실수로 만든다","단계":[{"제목":"분모의 켤레복소수 곱하기","힌트":"분모를 실수로 만들려면 분모·분자에 무엇을 곱할까?","식":["$\\frac{4-5i}{1+i}=\\frac{(4-5i)(1-i)}{(1+i)(1-i)}$"],"설명":"분모 $1+i$ 의 켤레복소수는 $1-i$ 이다. 분모와 분자에 같은 수를 곱하므로 값은 변하지 않는다.","확인":null,"스킬":"A5"},{"제목":"분모 계산하기","힌트":"$(1+i)(1-i)$ 의 값은?","식":["$(1+i)(1-i)=1-i^{2}=1+1=2$"],"설명":"합차 꼴이라 $1-i^{2}$ 이고 $i^{2}=-1$ 이므로 분모는 실수 $2$ 가 된다.","확인":"2","스킬":"A5"},{"제목":"분자 전개 후 정리하기","고비":true,"힌트":"$(4-5i)(1-i)$ 를 전개해 $i^{2}$ 을 바꾸면?","식":["$(4-5i)(1-i)=4-4i-5i+5i^{2}=-1-9i$","$\\frac{-1-9i}{2}=-\\frac{1}{2}-\\frac{9}{2}i$"],"설명":"$5i^{2}=-5$ 이므로 실수부분은 $4-5=-1$, 허수부분은 $-9i$ 이다. 이를 분모 $2$ 로 나눈다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p039-2-6":{"길":"각 분수의 분모를 실수로 만들어 (1±i)² 꼴로 계산한다","단계":[{"제목":"각 분수의 분모 실수화하기","힌트":"각 분수의 분모·분자에 분모의 켤레복소수를 곱하면?","식":["$\\frac{1+i}{1-i}=\\frac{(1+i)^{2}}{(1-i)(1+i)}=\\frac{(1+i)^{2}}{2}$","$\\frac{1-i}{1+i}=\\frac{(1-i)^{2}}{(1+i)(1-i)}=\\frac{(1-i)^{2}}{2}$"],"설명":"$(1-i)(1+i)=1-i^{2}=2$ 이므로 두 분수 모두 분모가 $2$ 이고 분자는 제곱 꼴이 된다.","확인":null,"스킬":"A5"},{"제목":"분자의 제곱 계산하기","고비":true,"힌트":"$(1+i)^{2}$ 과 $(1-i)^{2}$ 을 전개하면?","식":["$(1+i)^{2}=1+2i+i^{2}=2i$","$(1-i)^{2}=1-2i+i^{2}=-2i$"],"설명":"$i^{2}=-1$ 이므로 $1$ 과 $i^{2}$ 이 서로 지워져 허수부분만 남는다. 두 값은 부호만 다르다.","확인":null,"스킬":"A5"},{"제목":"두 분수 더하기","힌트":"$\\frac{2i}{2}$ 와 $\\frac{-2i}{2}$ 를 더하면?","식":["$\\frac{2i}{2}+\\frac{-2i}{2}=i-i=0$"],"설명":"분모가 같은 두 분수의 합이므로 분자끼리 더하면 $2i-2i=0$ 이다.","확인":"0","스킬":"A5"}]},"tb-비상공수1-p039-3":{"길":"연속한 네 거듭제곱의 합이 0임을 이용해 남는 항만 계산한다","단계":[{"제목":"연속한 네 거듭제곱의 합 구하기","힌트":"$1+i+i^{2}+i^{3}$ 의 값은?","식":["$i^{2}=-1$, $i^{3}=-i$","$1+i+i^{2}+i^{3}=1+i-1-i=0$"],"설명":"$i^{2}=-1$, $i^{3}=i^{2}\\times i=-i$ 이다. 연속한 네 거듭제곱은 더하면 항상 $0$ 이 된다.","확인":"0","스킬":"A5"},{"제목":"항의 개수 세기","힌트":"$i^{0}$ 부터 $i^{2026}$ 까지 항은 모두 몇 개일까?","식":["$1=i^{0}$ 이므로 항은 $i^{0},\\ i^{1},\\ \\cdots,\\ i^{2026}$"],"설명":"첫 항 $1$ 이 $i^{0}$ 이므로 지수 $0$ 부터 $2026$ 까지 센다. $2026+1$ 개이다.","확인":"2027","스킬":"A5"},{"제목":"네 개씩 묶고 남는 항 수 구하기","고비":true,"힌트":"$2027$ 을 $4$ 로 나눈 나머지가 남는 항의 개수이다. 몇 개일까?","식":["$2027=4\\times506+3$","$506$ 묶음의 합은 $0$ 이고 남는 항은 $i^{2024}+i^{2025}+i^{2026}$"],"설명":"앞의 $2024$ 개는 $506$ 묶음이 되어 합이 $0$ 이다. 마지막 $3$ 개 $i^{2024}$, $i^{2025}$, $i^{2026}$ 만 남는다.","확인":"3","스킬":"P1"},{"제목":"남은 세 항 계산하기","힌트":"$i^{2024}$ 는 얼마이고 남은 세 항의 합은?","식":["$i^{2024}=(i^{4})^{506}=1$","$i^{2024}+i^{2025}+i^{2026}=1\\times(1+i+i^{2})=1+i-1=i$"],"설명":"$i^{4}=1$ 이므로 $i^{2024}=1$ 이다. 남은 항은 $i^{2024}(1+i+i^{2})$ 로 묶여 $1+i-1=i$ 이다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p039-4":{"길":"켤레복소수를 구해 비를 정리하고 분모를 실수로 만든다","단계":[{"제목":"켤레복소수와 비 정리하기","힌트":"$\\overline{z}$ 를 구해 $\\frac{\\overline{z}}{z}$ 에 넣으면 $\\sqrt{2}$ 는 어떻게 될까?","식":["$\\overline{z}=\\frac{1+i}{\\sqrt{2}}$","$\\frac{\\overline{z}}{z}=\\frac{(1+i)/\\sqrt{2}}{(1-i)/\\sqrt{2}}=\\frac{1+i}{1-i}$"],"설명":"켤레복소수는 허수부분의 부호만 바꾼다. 분모와 분자에 $\\frac{1}{\\sqrt{2}}$ 이 똑같이 있어 약분된다.","확인":null,"스킬":"A5"},{"제목":"분모 실수화하기","고비":true,"힌트":"분모 $1-i$ 의 켤레복소수 $1+i$ 를 곱하면 분모는?","식":["$\\frac{1+i}{1-i}=\\frac{(1+i)^{2}}{(1-i)(1+i)}$","$(1-i)(1+i)=1-i^{2}=2$"],"설명":"분모와 분자에 $1+i$ 를 곱한다. 분모는 합차 꼴이고 $i^{2}=-1$ 이므로 실수가 된다.","확인":"2","스킬":"A5"},{"제목":"분자 계산하기","힌트":"$(1+i)^{2}$ 을 전개해 분모로 나누면?","식":["$(1+i)^{2}=1+2i+i^{2}=2i$","$\\frac{2i}{2}=i$"],"설명":"$1+i^{2}=0$ 이라 $2i$ 만 남는다. 분모 $2$ 로 나누면 $i$ 이다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p039-5":{"길":"우변의 켤레를 구하고 좌변을 통분해 실수·허수부분을 비교한다","단계":[{"제목":"우변의 켤레와 좌변의 통분","고비":true,"힌트":"우변은 켤레복소수로 바꾸고, 좌변은 분모를 실수로 만들어 하나로 모으면?","식":["$\\overline{6-7i}=6+7i$","$\\frac{x}{1+i}+\\frac{y}{1-i}=\\frac{x(1-i)+y(1+i)}{(1+i)(1-i)}=\\frac{x+y}{2}+\\frac{-x+y}{2}i$"],"설명":"켤레복소수는 허수부분의 부호만 바뀐다. 좌변은 통분하면 분모가 $(1+i)(1-i)=2$ 이고 분자는 $x-xi+y+yi$ 이므로 $(x+y)+(-x+y)i$ 이다.","확인":null,"스킬":"A5"},{"제목":"연립방정식 세우기","힌트":"양변의 실수부분끼리, 허수부분끼리 같게 놓으면?","식":["$\\frac{x+y}{2}=6$, $\\frac{-x+y}{2}=7$","$x+y=12$, $-x+y=14$"],"설명":"$x$, $y$ 가 실수이므로 실수부분과 허수부분이 각각 같아야 한다. 양변에 $2$ 를 곱해 분모를 없앤다.","확인":null,"스킬":"A10"},{"제목":"y 의 값 구하기","힌트":"두 식을 변끼리 더하면 $y$ 는?","식":["$(x+y)+(-x+y)=12+14$","$2y=26$"],"설명":"두 식의 $x$ 항은 부호가 반대라 더하면 사라진다. 남은 식에서 $y$ 가 정해진다.","확인":"13","스킬":"A10"},{"제목":"x 의 값 구하기","힌트":"구한 $y$ 를 $x+y=12$ 에 넣으면 $x$ 는?","식":["$x=12-13=-1$"],"설명":"$y=13$ 을 대입하면 $x=-1$ 이므로 $x=-1$, $y=13$ 이다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p039-6-1":{"길":"음수의 제곱근을 √a i 꼴로 바꾼 뒤 같은 꼴끼리 계산한다","단계":[{"제목":"음수의 제곱근을 허수단위로 꺼내기","고비":true,"힌트":"$\\sqrt{-a}=\\sqrt{a}\\,i$ 로 각 항을 바꾸면?","식":["$\\sqrt{-50}=5\\sqrt{2}i$, $\\sqrt{-18}=3\\sqrt{2}i$, $\\sqrt{-8}=2\\sqrt{2}i$"],"설명":"$a>0$ 일 때 $\\sqrt{-a}=\\sqrt{a}\\,i$ 이다. $50=5^{2}\\times2$, $18=3^{2}\\times2$, $8=2^{2}\\times2$ 로 근호 밖으로 꺼낸다.","확인":null,"스킬":"A5"},{"제목":"√2 i 의 계수 계산하기","힌트":"세 항 모두 $\\sqrt{2}i$ 꼴이면 계수끼리 계산한 결과는?","식":["$2\\times5\\sqrt{2}i-3\\sqrt{2}i+2\\sqrt{2}i$","$(10-3+2)\\sqrt{2}i=9\\sqrt{2}i$"],"설명":"$\\sqrt{2}i$ 를 문자처럼 보고 동류항으로 묶는다. 첫 항에는 앞의 $2$ 를 곱한다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p039-6-2":{"길":"근호 안의 음수를 합치지 말고 i를 먼저 꺼낸 뒤 곱한다","단계":[{"제목":"허수단위 먼저 꺼내기","고비":true,"힌트":"$\\sqrt{-3}$ 과 $\\sqrt{-48}$ 을 각각 $i$ 가 붙은 꼴로 바꾸면?","식":["$\\sqrt{-3}=\\sqrt{3}i$, $\\sqrt{-48}=4\\sqrt{3}i$"],"설명":"둘 다 음수의 제곱근이므로 $\\sqrt{-a}\\sqrt{-b}=\\sqrt{ab}$ 로 합칠 수 없다. 각각 $\\sqrt{a}\\,i$ 로 바꾼 뒤 곱해야 한다.","확인":null,"스킬":"A5"},{"제목":"곱하고 i² 바꾸기","힌트":"$\\sqrt{3}i\\times4\\sqrt{3}i$ 의 값은?","식":["$\\sqrt{3}i\\times4\\sqrt{3}i=12i^{2}$","$12\\times(-1)=-12$"],"설명":"$\\sqrt{3}\\times4\\sqrt{3}=12$ 이고 $i\\times i=i^{2}=-1$ 이다.","확인":"-12","스킬":"A5"}]},"tb-비상공수1-p040-1-1":{"길":"판별식 D=b²-4ac 를 계산해 부호로 근의 종류를 정한다","단계":[{"제목":"판별식 계산하기","고비":true,"힌트":"$a=-1$, $b=5$, $c=-1$ 일 때 $D=b^{2}-4ac$ 는?","식":["$D=5^{2}-4\\times(-1)\\times(-1)$","$D=25-4=21$"],"설명":"$a$ 가 음수여도 공식은 그대로 쓴다. $-4ac$ 에서 $a$, $c$ 가 모두 음수이므로 $4ac=4$ 이다.","확인":"21","스킬":"G2"},{"제목":"부호로 근 판별하기","힌트":"$D$ 의 부호로 알 수 있는 근의 종류는?","식":["$D=21>0$ 이므로 서로 다른 두 실근"],"설명":"$D>0$ 이면 서로 다른 두 실근, $D=0$ 이면 중근, $D<0$ 이면 서로 다른 두 허근이다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p040-1-2":{"길":"x의 계수가 짝수이므로 D/4 를 계산해 부호로 근의 종류를 정한다","단계":[{"제목":"D/4 계산하기","고비":true,"힌트":"$b'=-2$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 는?","식":["$\\frac{D}{4}=(-2)^{2}-3\\times2$","$\\frac{D}{4}=4-6=-2$"],"설명":"$x$ 의 계수 $-4$ 가 짝수이므로 $b=2b'$ 로 놓고 $\\frac{D}{4}=b'^{2}-ac$ 를 쓰면 계산이 가볍다.","확인":"-2","스킬":"G2"},{"제목":"부호로 근 판별하기","힌트":"$\\frac{D}{4}$ 의 부호로 알 수 있는 근의 종류는?","식":["$\\frac{D}{4}=-2<0$ 이므로 서로 다른 두 허근"],"설명":"$\\frac{D}{4}$ 는 $D$ 와 부호가 같다. 음수이므로 실근이 없고 서로 다른 두 허근이다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p040-1-3":{"길":"D/4 가 0인지 확인해 중근임을 정한다","단계":[{"제목":"D/4 계산하기","고비":true,"힌트":"$b'=6$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 는?","식":["$\\frac{D}{4}=6^{2}-9\\times4$","$\\frac{D}{4}=36-36=0$"],"설명":"$x$ 의 계수 $12$ 가 짝수이므로 $b'=6$ 으로 두고 $\\frac{D}{4}$ 를 계산한다.","확인":"0","스킬":"G2"},{"제목":"부호로 근 판별하기","힌트":"$\\frac{D}{4}=0$ 이면 근의 종류는?","식":["$\\frac{D}{4}=0$ 이므로 중근","$9x^{2}+12x+4=(3x+2)^{2}$"],"설명":"$D=0$ 이면 중근이다. 좌변이 완전제곱식 $(3x+2)^{2}$ 이 되는 것으로도 확인된다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p040-2-1":{"길":"서로 다른 두 실근이면 D>0 이므로 부등식을 세워 푼다","단계":[{"제목":"판별식 D>0 세우기","고비":true,"힌트":"서로 다른 두 실근을 가질 때 $D$ 의 조건과 $D$ 의 식은?","식":["서로 다른 두 실근이면 $D>0$","$D=3^{2}-4\\times2\\times a=9-8a>0$"],"설명":"서로 다른 두 실근을 가지려면 $D>0$ 이어야 하고 등호는 들어가지 않는다. $a=2$, $b=3$, $c=a$ 를 $D=b^{2}-4ac$ 에 넣는다.","확인":null,"스킬":"G2"},{"제목":"부등식 풀어 범위 구하기","힌트":"$9-8a>0$ 을 풀면 $a$ 의 범위는?","식":["$-8a>-9$","$a<\\frac{9}{8}$"],"설명":"양변을 음수 $-8$ 로 나누면 부등호 방향이 바뀐다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p040-2-2":{"길":"D/4 를 괄호로 묶어 계산한 뒤 D/4>0 을 푼다","단계":[{"제목":"D/4 계산하기","고비":true,"힌트":"$b'=-3$, $c=2a+5$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 는?","식":["$\\frac{D}{4}=(-3)^{2}-(2a+5)$","$\\frac{D}{4}=9-2a-5=4-2a$"],"설명":"상수항 $2a+5$ 전체를 괄호로 묶어 빼야 한다. 괄호를 풀 때 $5$ 에도 마이너스가 적용된다.","확인":null,"스킬":"G2"},{"제목":"부등식 풀어 범위 구하기","힌트":"서로 다른 두 실근이면 $\\frac{D}{4}>0$ 이다. $a$ 의 범위는?","식":["$4-2a>0$","$a<2$"],"설명":"$-2a>-4$ 에서 음수로 나누면 부등호 방향이 바뀐다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p040-3":{"길":"실근 조건 D/4≥0 을 풀어 m의 범위를 구한 뒤 정수 최댓값을 찾는다","단계":[{"제목":"D/4 계산하기","힌트":"$b'=-(m-5)$ 이므로 $\\frac{D}{4}=b'^{2}-ac$ 를 전개하면?","식":["$\\frac{D}{4}=\\{-(m-5)\\}^{2}-m^{2}=(m-5)^{2}-m^{2}$","$\\frac{D}{4}=m^{2}-10m+25-m^{2}=-10m+25$"],"설명":"$x$ 의 계수가 $-2(m-5)$ 이므로 $b'=-(m-5)$ 이고 제곱하면 $(m-5)^{2}$ 이다. $m^{2}$ 항이 서로 지워진다.","확인":null,"스킬":"G2"},{"제목":"실근 조건 D/4≥0 풀기","고비":true,"힌트":"실근을 가질 조건을 풀 때 $m$ 의 경계값은?","식":["실근을 가지면 $\\frac{D}{4}\\ge0$","$-10m+25\\ge0$","$m\\le\\frac{5}{2}$"],"설명":"실근을 갖는다에는 중근도 포함되므로 등호를 넣는다. $-10m\\ge-25$ 에서 음수로 나누어 부등호 방향이 바뀐다.","확인":"5/2","스킬":"G2"},{"제목":"정수 m 의 최댓값 찾기","힌트":"$m\\le\\frac{5}{2}$ 를 만족시키는 가장 큰 정수는?","식":["$m\\le2.5$ 이므로 정수 $m$ 의 최댓값은 $2$"],"설명":"$2.5$ 이하의 정수 중 가장 큰 수는 $2$ 이다.","확인":"2","스킬":"G2"}]},"tb-비상공수1-p040-4-1":{"길":"중근이면 D=0 이므로 a에 대한 일차방정식을 세워 푼다","단계":[{"제목":"D=0 세우기","고비":true,"힌트":"$c=-a$ 일 때 $D=b^{2}-4ac$ 를 쓰고 $D=0$ 으로 놓으면?","식":["$D=5^{2}-4\\times3\\times(-a)=25+12a$","$25+12a=0$"],"설명":"상수항이 $-a$ 이므로 $-4ac=-4\\times3\\times(-a)=+12a$ 이다. 중근이면 $D=0$ 이다.","확인":null,"스킬":"G2"},{"제목":"a 의 값 구하기","힌트":"$25+12a=0$ 에서 $a$ 는?","식":["$12a=-25$","$a=-\\frac{25}{12}$"],"설명":"$25$ 를 이항해 $12$ 로 나눈다.","확인":"-25/12","스킬":"G2"}]},"tb-비상공수1-p040-4-2":{"길":"중근이면 D/4=0 이므로 a에 대한 이차방정식을 인수분해해 푼다","단계":[{"제목":"D/4=0 세우기","고비":true,"힌트":"$b'=a$, $c=7a-6$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 를 정리해 $0$ 으로 놓으면?","식":["$\\frac{D}{4}=a^{2}-(7a-6)=a^{2}-7a+6$","$a^{2}-7a+6=0$"],"설명":"상수항 $7a-6$ 전체를 괄호로 묶어 빼야 한다. 중근이면 $\\frac{D}{4}=0$ 이고 이것이 $a$ 에 대한 이차방정식이 된다.","확인":null,"스킬":"G2"},{"제목":"인수분해해 a 구하기","힌트":"합이 $-7$, 곱이 $6$ 인 두 수를 이용해 인수분해하면?","식":["$(a-1)(a-6)=0$","$a=1$ 또는 $a=6$"],"설명":"곱이 $6$ 이고 합이 $-7$ 인 두 수는 $-1$, $-6$ 이므로 $(a-1)(a-6)=0$ 이다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p040-5":{"길":"D/4=0 으로 m을 구하고 원래 방정식에 넣어 중근 a를 구한다","단계":[{"제목":"D/4=0 으로 m 구하기","힌트":"$\\frac{D}{4}=0$ 을 완전제곱식으로 만들면 $m$ 은?","식":["$\\frac{D}{4}=(-3m)^{2}-(6m-1)=9m^{2}-6m+1$","$(3m-1)^{2}=0$ 에서 $m=\\frac{1}{3}$"],"설명":"중근이면 $\\frac{D}{4}=0$ 이다. $9m^{2}-6m+1$ 은 $(3m-1)^{2}$ 이므로 $m$ 의 값이 하나로 정해진다.","확인":"1/3","스킬":"G2"},{"제목":"m 을 넣어 중근 a 구하기","고비":true,"힌트":"$m=\\frac{1}{3}$ 을 원래 방정식에 넣으면 중근 $a$ 는?","식":["$x^{2}-2x+1=0$","$(x-1)^{2}=0$ 에서 $a=1$"],"설명":"$-6m=-2$, $6m-1=1$ 이므로 방정식은 $x^{2}-2x+1=0$ 이다. 이 식의 근이 중근 $a$ 이다.","확인":"1","스킬":"G2"},{"제목":"a+m 구하기","힌트":"구한 $a$ 와 $m$ 을 더하면?","식":["$a+m=1+\\frac{1}{3}=\\frac{4}{3}$"],"설명":"$a=1$, $m=\\frac{1}{3}$ 을 더한다.","확인":"4/3","스킬":"G2"}]},"tb-비상공수1-p040-6-1":{"길":"서로 다른 두 허근이면 D<0 이므로 부등식을 세워 푼다","단계":[{"제목":"판별식 D 계산하기","고비":true,"힌트":"$a=4$, $b=7$, $c=-a$ 일 때 $D=b^{2}-4ac$ 는?","식":["$D=7^{2}-4\\times4\\times(-a)=49+16a$"],"설명":"상수항이 $-a$ 이므로 $-4ac=-4\\times4\\times(-a)=+16a$ 이다.","확인":null,"스킬":"G2"},{"제목":"D<0 풀어 범위 구하기","힌트":"서로 다른 두 허근이면 $D<0$ 이다. $a$ 의 범위는?","식":["$49+16a<0$","$16a<-49$","$a<-\\frac{49}{16}$"],"설명":"$D<0$ 이면 서로 다른 두 허근이다. $49$ 를 이항한 뒤 양수 $16$ 으로 나누므로 부등호 방향은 그대로이다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p040-6-2":{"길":"D/4 를 계산할 때 부호를 바꿔 쓴 뒤 D/4<0 을 푼다","단계":[{"제목":"D/4 계산하기","고비":true,"힌트":"$b'=-2$, $c=-4a-2$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 는?","식":["$\\frac{D}{4}=(-2)^{2}-(-4a-2)$","$\\frac{D}{4}=4+4a+2=4a+6$"],"설명":"$-(-4a-2)$ 는 괄호 안의 부호가 모두 바뀌어 $+4a+2$ 가 된다.","확인":null,"스킬":"G2"},{"제목":"D/4<0 풀어 범위 구하기","힌트":"서로 다른 두 허근이면 $\\frac{D}{4}<0$ 이다. $a$ 의 범위는?","식":["$4a+6<0$","$a<-\\frac{3}{2}$"],"설명":"$4a<-6$ 에서 양수 $4$ 로 나누므로 부등호 방향은 그대로이다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p041-1-1":{"길":"근과 계수의 관계로 합은 -b/a, 곱은 c/a 로 구한다","단계":[{"제목":"두 근의 합 구하기","고비":true,"힌트":"합은 $-\\frac{b}{a}$ 이다. 이 방정식에서는?","식":["$-\\frac{b}{a}=-\\frac{4}{1}=-4$"],"설명":"$a=1$, $b=4$ 이다. 합의 공식에는 마이너스가 붙어 부호가 바뀐다.","확인":"-4","스킬":"A2"},{"제목":"두 근의 곱 구하기","힌트":"곱은 $\\frac{c}{a}$ 이다. 이 방정식에서는?","식":["$\\frac{c}{a}=\\frac{2}{1}=2$"],"설명":"$c=2$, $a=1$ 이므로 곱은 $2$ 이다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p041-1-2":{"길":"x²의 계수 2로 나누는 것을 잊지 않고 합과 곱을 구한다","단계":[{"제목":"두 근의 합 구하기","고비":true,"힌트":"합은 $-\\frac{b}{a}$ 이다. 이 방정식에서는?","식":["$-\\frac{b}{a}=-\\frac{-3}{2}=\\frac{3}{2}$"],"설명":"$a=2$, $b=-3$ 이다. $b$ 가 음수이므로 합은 양수가 된다.","확인":"3/2","스킬":"A2"},{"제목":"두 근의 곱 구하기","힌트":"곱은 $\\frac{c}{a}$ 이다. 이 방정식에서는?","식":["$\\frac{c}{a}=\\frac{5}{2}$"],"설명":"$c=5$ 를 $x^{2}$ 의 계수 $a=2$ 로 나눈다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p041-1-3":{"길":"계수에 무리수가 있어도 합 -b/a, 곱 c/a 공식은 같다","단계":[{"제목":"두 근의 합 구하기","고비":true,"힌트":"$a=1$, $b=4\\sqrt{3}$ 일 때 $-\\frac{b}{a}$ 는?","식":["$-\\frac{b}{a}=-\\frac{4\\sqrt{3}}{1}=-4\\sqrt{3}$"],"설명":"계수가 무리수여도 공식은 같다. $a=1$ 이므로 합은 $b$ 의 부호만 바꾼 값이다.","확인":null,"스킬":"A2"},{"제목":"두 근의 곱 구하기","힌트":"$a=1$, $c=-6$ 일 때 $\\frac{c}{a}$ 는?","식":["$\\frac{c}{a}=\\frac{-6}{1}=-6$"],"설명":"곱은 상수항을 $x^{2}$ 의 계수로 나눈 값이다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p041-2":{"길":"근과 계수의 관계로 합과 곱을 구해 곱셈공식 꼴로 바꾼다","단계":[{"제목":"두 근의 합과 곱 구하기","힌트":"근과 계수의 관계로 $\\alpha+\\beta$ 와 $\\alpha\\beta$ 는?","식":["$\\alpha+\\beta=-\\frac{-5}{1}=5$, $\\alpha\\beta=\\frac{1}{1}=1$"],"설명":"$x^{2}-5x+1=0$ 에서 $a=1$, $b=-5$, $c=1$ 이므로 합은 $-\\frac{b}{a}$, 곱은 $\\frac{c}{a}$ 이다.","확인":null,"스킬":"A2"},{"제목":"합과 곱의 식으로 바꾸기","고비":true,"힌트":"$\\alpha^{2}+\\beta^{2}=(\\alpha+\\beta)^{2}-2\\alpha\\beta$ 를 이용하면 주어진 식은?","식":["$\\alpha^{2}+3\\alpha\\beta+\\beta^{2}=(\\alpha^{2}+\\beta^{2})+3\\alpha\\beta$","$=(\\alpha+\\beta)^{2}-2\\alpha\\beta+3\\alpha\\beta=(\\alpha+\\beta)^{2}+\\alpha\\beta$"],"설명":"$-2\\alpha\\beta$ 와 $3\\alpha\\beta$ 가 합쳐져 $+\\alpha\\beta$ 만 남는다. 이렇게 해야 합과 곱의 값만으로 계산된다.","확인":null,"스킬":"A2"},{"제목":"값 계산하기","힌트":"$\\alpha+\\beta$ 와 $\\alpha\\beta$ 의 값을 넣으면?","식":["$(\\alpha+\\beta)^{2}+\\alpha\\beta=5^{2}+1=26$"],"설명":"$\\alpha+\\beta=5$, $\\alpha\\beta=1$ 을 대입한다.","확인":"26","스킬":"A2"}]},"tb-비상공수1-p041-3":{"길":"역수의 합을 (α+β)/αβ 로 바꿔 두 방정식의 계수를 연결한다","단계":[{"제목":"두 방정식의 합과 곱 쓰기","힌트":"각 방정식에서 근의 합과 곱을 근과 계수의 관계로 쓰면?","식":["$\\alpha+\\beta=-a$, $\\alpha\\beta=6$","$\\frac{1}{\\alpha}+\\frac{1}{\\beta}=\\frac{4}{12}=\\frac{1}{3}$, $\\frac{1}{\\alpha\\beta}=\\frac{b}{12}$"],"설명":"첫째 식의 두 근은 $\\alpha$, $\\beta$ 이고 둘째 식의 두 근은 $\\frac{1}{\\alpha}$, $\\frac{1}{\\beta}$ 이다. 둘째 식은 합이 $\\frac{4}{12}$, 곱이 $\\frac{b}{12}$ 이다.","확인":null,"스킬":"A2"},{"제목":"a 의 값 구하기","고비":true,"힌트":"$\\frac{1}{\\alpha}+\\frac{1}{\\beta}$ 를 통분해 $\\alpha+\\beta$ 와 $\\alpha\\beta$ 로 나타내면?","식":["$\\frac{1}{\\alpha}+\\frac{1}{\\beta}=\\frac{\\alpha+\\beta}{\\alpha\\beta}=\\frac{-a}{6}$","$\\frac{-a}{6}=\\frac{1}{3}$","$a=-2$"],"설명":"통분하면 $\\frac{\\alpha+\\beta}{\\alpha\\beta}$ 가 되어 첫째 식의 합과 곱이 둘째 식의 합과 이어진다.","확인":"-2","스킬":"A2"},{"제목":"b 를 구하고 a+b 구하기","힌트":"둘째 식의 곱으로 $b$ 를 구해 $a$ 와 더하면?","식":["$\\frac{1}{6}=\\frac{b}{12}$ 에서 $b=2$","$a+b=-2+2=0$"],"설명":"$\\frac{1}{\\alpha\\beta}=\\frac{1}{6}$ 이므로 $\\frac{b}{12}=\\frac{1}{6}$ 에서 $b=2$ 이다.","확인":"0","스킬":"A2"}]},"tb-비상공수1-p041-4-1":{"길":"두 근의 합과 곱을 구해 x²-(합)x+(곱)=0 에 넣는다","단계":[{"제목":"두 근의 합과 곱 구하기","힌트":"두 근 $-4$, $5$ 의 합과 곱은?","식":["합: $-4+5=1$","곱: $(-4)\\times5=-20$"],"설명":"두 수를 더한 값이 합, 곱한 값이 곱이다. 음수 $-4$ 를 곱할 때 부호에 주의한다.","확인":null,"스킬":"A2"},{"제목":"이차방정식 세우기","고비":true,"힌트":"합을 $S$, 곱을 $P$ 라 하면 $x^{2}-Sx+P=0$ 에 넣은 식은?","식":["$x^{2}-1\\times x+(-20)=0$","$x^{2}-x-20=0$"],"설명":"$x^{2}$ 의 계수가 $1$ 이고 두 근의 합이 $S$, 곱이 $P$ 인 이차방정식은 $x^{2}-Sx+P=0$ 이다. 합 앞에 마이너스가 붙는다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p041-4-2":{"길":"두 근의 합과 곱을 구해 x²-(합)x+(곱)=0 에 넣는다","단계":[{"제목":"두 근의 합 구하기","힌트":"두 근 $\\sqrt{3}+1$, $\\sqrt{3}-1$ 을 더하면?","식":["$(\\sqrt{3}+1)+(\\sqrt{3}-1)=2\\sqrt{3}$"],"설명":"$+1$ 과 $-1$ 이 서로 지워져 $\\sqrt{3}$ 의 두 배만 남는다.","확인":null,"스킬":"A2"},{"제목":"두 근의 곱 구하기","고비":true,"힌트":"합차 꼴 $(a+b)(a-b)$ 를 이용해 두 근의 곱은?","식":["$(\\sqrt{3}+1)(\\sqrt{3}-1)=(\\sqrt{3})^{2}-1^{2}=3-1=2$"],"설명":"두 근이 $\\sqrt{3}$ 에 $\\pm1$ 을 더한 꼴이라 곱은 $a^{2}-b^{2}$ 로 계산된다.","확인":"2","스킬":"A2"},{"제목":"이차방정식 세우기","힌트":"합을 $S$, 곱을 $P$ 라 하면 $x^{2}-Sx+P=0$ 에 넣은 식은?","식":["$x^{2}-2\\sqrt{3}\\,x+2=0$"],"설명":"$x^{2}$ 의 계수가 $1$ 이므로 $x^{2}-Sx+P=0$ 이다. 합 $2\\sqrt{3}$ 앞에 마이너스가 붙는다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p041-4-3":{"길":"켤레복소수인 두 근의 합과 곱을 구해 x²-(합)x+(곱)=0 에 넣는다","단계":[{"제목":"두 근의 합 구하기","힌트":"두 근 $1+2i$, $1-2i$ 를 더하면?","식":["$(1+2i)+(1-2i)=2$"],"설명":"허수부분 $2i$ 와 $-2i$ 가 서로 지워져 실수만 남는다.","확인":null,"스킬":"A2"},{"제목":"두 근의 곱 구하기","고비":true,"힌트":"$(a+b)(a-b)$ 꼴에서 $i^{2}=-1$ 을 쓰면 두 근의 곱은?","식":["$(1+2i)(1-2i)=1-4i^{2}=1+4=5$"],"설명":"$(2i)^{2}=4i^{2}=-4$ 이므로 $-4i^{2}=+4$ 이다. 켤레복소수의 곱은 실수가 된다.","확인":"5","스킬":"A5"},{"제목":"이차방정식 세우기","힌트":"합을 $S$, 곱을 $P$ 라 하면 $x^{2}-Sx+P=0$ 에 넣은 식은?","식":["$x^{2}-2x+5=0$"],"설명":"$x^{2}$ 의 계수가 $1$ 이므로 $x^{2}-Sx+P=0$ 에 합 $2$, 곱 $5$ 를 넣는다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p041-5":{"길":"합과 곱을 근으로 갖는 이차방정식을 세워 근의 공식으로 푼다","단계":[{"제목":"두 수를 근으로 하는 이차방정식 세우기","고비":true,"힌트":"합이 $6$, 곱이 $-2$ 인 두 수는 어떤 이차방정식의 근일까?","식":["$x^{2}-6x+(-2)=0$","$x^{2}-6x-2=0$"],"설명":"합이 $S$, 곱이 $P$ 인 두 수는 $x^{2}-Sx+P=0$ 의 두 근이다. 이 방정식을 풀면 두 수가 나온다.","확인":null,"스킬":"A2"},{"제목":"D/4 계산하기","힌트":"$b'=-3$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 는?","식":["$\\frac{D}{4}=(-3)^{2}-1\\times(-2)=9+2=11$"],"설명":"$c=-2$ 이므로 $-ac=+2$ 가 되어 더해진다.","확인":"11","스킬":"G2"},{"제목":"두 근 구하기","힌트":"$x=-b'\\pm\\sqrt{\\frac{D}{4}}$ 를 쓰면 두 근은?","식":["$x=3\\pm\\sqrt{11}$"],"설명":"$x$ 의 계수가 짝수일 때 근은 $x=\\frac{-b'\\pm\\sqrt{b'^{2}-ac}}{a}$ 이다. $a=1$, $b'=-3$ 이므로 $3\\pm\\sqrt{11}$ 이다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p041-6-1":{"길":"이차식=0 의 근을 구해 (x-근)(x-근) 꼴로 인수분해한다","단계":[{"제목":"D/4 계산하기","힌트":"$b'=-2$, $a=1$, $c=6$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 는?","식":["$\\frac{D}{4}=(-2)^{2}-1\\times6=-2$"],"설명":"$x^{2}-4x+6=0$ 의 $\\frac{D}{4}$ 가 음수이므로 실근이 없고 복소수 범위에서만 인수분해된다.","확인":"-2","스킬":"G2"},{"제목":"방정식의 근 구하기","힌트":"$x=-b'\\pm\\sqrt{\\frac{D}{4}}$ 에서 근은?","식":["$x=2\\pm\\sqrt{-2}=2\\pm\\sqrt{2}i$"],"설명":"$\\sqrt{-2}=\\sqrt{2}i$ 이다. 두 근은 서로 켤레복소수이다.","확인":null,"스킬":"A5"},{"제목":"인수분해 꼴로 쓰기","고비":true,"힌트":"두 근을 $\\alpha$, $\\beta$ 라 하면 $a(x-\\alpha)(x-\\beta)$ 꼴이다. 쓰면?","식":["$x^{2}-4x+6=(x-(2+\\sqrt{2}i))(x-(2-\\sqrt{2}i))$","$=(x-2-\\sqrt{2}i)(x-2+\\sqrt{2}i)$"],"설명":"이차방정식 $ax^{2}+bx+c=0$ 의 두 근이 $\\alpha$, $\\beta$ 이면 $ax^{2}+bx+c=a(x-\\alpha)(x-\\beta)$ 이다. 여기서는 $a=1$ 이다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p041-6-2":{"길":"=0 의 근을 구한 뒤 x²의 계수 3을 앞에 붙여 인수분해한다","단계":[{"제목":"D/4 계산하기","힌트":"$b'=-1$, $a=3$, $c=2$ 일 때 $\\frac{D}{4}=b'^{2}-ac$ 는?","식":["$\\frac{D}{4}=(-1)^{2}-3\\times2=-5$"],"설명":"$x$ 의 계수 $-2$ 가 짝수이므로 $b'=-1$ 로 두고 계산한다. 음수이므로 근이 허수이다.","확인":"-5","스킬":"G2"},{"제목":"방정식의 근 구하기","힌트":"$x=\\frac{-b'\\pm\\sqrt{\\frac{D}{4}}}{a}$ 에서 근은?","식":["$x=\\frac{1\\pm\\sqrt{-5}}{3}=\\frac{1\\pm\\sqrt{5}i}{3}$"],"설명":"분모는 $a=3$ 이다. $\\sqrt{-5}=\\sqrt{5}i$ 이다.","확인":null,"스킬":"A5"},{"제목":"x² 의 계수를 붙여 인수분해하기","고비":true,"힌트":"$a(x-\\alpha)(x-\\beta)$ 에서 앞에 붙는 $a$ 는 얼마일까?","식":["$3x^{2}-2x+2=3\\left(x-\\frac{1+\\sqrt{5}i}{3}\\right)\\left(x-\\frac{1-\\sqrt{5}i}{3}\\right)$","$=3\\left(x-\\frac{1}{3}-\\frac{\\sqrt{5}}{3}i\\right)\\left(x-\\frac{1}{3}+\\frac{\\sqrt{5}}{3}i\\right)$"],"설명":"$x^{2}$ 의 계수가 $3$ 이므로 $3$ 을 빼먹으면 원래 식과 달라진다. 괄호 안의 분수를 $\\frac{1}{3}$ 과 $\\frac{\\sqrt{5}}{3}i$ 로 나누어 쓴다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p042-1":{"길":"x축과 한 점에서 만나면 D/4=0 이므로 k의 값을 구해 곱한다","단계":[{"제목":"D/4=0 세우기","고비":true,"힌트":"한 점에서 만나면 이차방정식이 중근을 갖는다. $\\frac{D}{4}$ 를 $k$ 로 나타내면?","식":["$x^{2}-4kx+8=0$ 이 중근을 가지므로 $\\frac{D}{4}=0$","$\\frac{D}{4}=(-2k)^{2}-1\\times8=4k^{2}-8$"],"설명":"그래프가 $x$축과 한 점에서 만난다는 것은 $y=0$ 인 방정식이 중근을 갖는다는 뜻이므로 $\\frac{D}{4}=0$ 이다.","확인":null,"스킬":"G2"},{"제목":"k 의 값 구하기","힌트":"$4k^{2}-8=0$ 에서 $k$ 는?","식":["$k^{2}=2$","$k=\\pm\\sqrt{2}$"],"설명":"$k^{2}=2$ 이므로 $k$ 는 $\\sqrt{2}$ 와 $-\\sqrt{2}$ 두 값이다.","확인":null,"스킬":"G2"},{"제목":"모든 k 값의 곱 구하기","힌트":"$\\sqrt{2}$ 와 $-\\sqrt{2}$ 를 곱하면?","식":["$\\sqrt{2}\\times(-\\sqrt{2})=-2$"],"설명":"두 값의 부호가 반대이므로 곱은 음수이다.","확인":"-2","스킬":"A2"}]},"tb-비상공수1-p042-2":{"길":"x축과 만난다는 것을 D≥0 으로 바꿔 m의 범위를 구한다","단계":[{"제목":"판별식 D 계산하기","힌트":"$a=-1$, $b=2m-3$, $c=-m^{2}+1$ 일 때 $D=b^{2}-4ac$ 를 전개하면?","식":["$D=(2m-3)^{2}-4\\times(-1)\\times(-m^{2}+1)$","$D=4m^{2}-12m+9-4m^{2}+4=-12m+13$"],"설명":"$-4\\times(-1)\\times(-m^{2}+1)=-4m^{2}+4$ 이다. $m^{2}$ 항이 서로 지워지므로 $D$ 는 $m$ 의 일차식이 된다.","확인":null,"스킬":"G2"},{"제목":"만나는 조건 D≥0 세우기","고비":true,"힌트":"그래프가 $x$축과 만나기만 하면 될 때 $D$ 의 조건은 등호를 넣을까?","식":["$x$축과 만나면 이차방정식이 실근을 가지므로 $D\\ge0$","$-12m+13\\ge0$"],"설명":"접하는 경우도 만나는 것이므로 $D=0$ 을 포함해 $D\\ge0$ 으로 놓는다.","확인":null,"스킬":"G2"},{"제목":"부등식 풀어 범위 구하기","힌트":"$-12m+13\\ge0$ 을 풀면 $m$ 의 범위는?","식":["$-12m\\ge-13$","$m\\le\\frac{13}{12}$"],"설명":"양변을 음수 $-12$ 로 나누므로 부등호 방향이 바뀐다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p042-3":{"길":"x축과의 교점의 x좌표를 이차방정식의 두 근으로 보고 근과 계수의 관계를 쓴다","단계":[{"제목":"두 근의 합과 곱 구하기","고비":true,"힌트":"교점의 $x$좌표가 방정식 $x^{2}+ax+b=0$ 의 두 근이다. 합과 곱은?","식":["합: $(1-\\sqrt{5})+(1+\\sqrt{5})=2$","곱: $(1-\\sqrt{5})(1+\\sqrt{5})=1-5=-4$"],"설명":"$x$축 위의 점은 $y=0$ 이므로 교점의 $x$좌표는 $x^{2}+ax+b=0$ 의 해이다. 곱은 합차 꼴로 $1^{2}-(\\sqrt{5})^{2}$ 이다.","확인":null,"스킬":"G1"},{"제목":"근과 계수의 관계로 a, b 구하기","힌트":"합이 $-a$, 곱이 $b$ 임을 이용하면 $a$, $b$ 는?","식":["$-a=2$ 에서 $a=-2$","$b=-4$"],"설명":"$x^{2}$ 의 계수가 $1$ 이므로 두 근의 합은 $-a$, 곱은 $b$ 이다. 합의 부호가 바뀌는 데 주의한다.","확인":null,"스킬":"A2"}]},"tb-비상공수1-p042-4-1":{"길":"두 식을 같다고 놓아 이차방정식을 만들고 D의 부호로 교점 개수를 센다","단계":[{"제목":"두 식을 같다고 놓아 정리하기","힌트":"교점의 $x$좌표는 두 식의 $y$ 가 같을 때이다. 한쪽으로 모으면?","식":["$x^{2}+2x-2=x-6$","$x^{2}+x+4=0$"],"설명":"교점에서는 $y$ 값이 같으므로 두 식을 등식으로 놓는다. 우변을 이항해 $=0$ 꼴로 정리한다.","확인":null,"스킬":"G1"},{"제목":"판별식 D 계산하기","고비":true,"힌트":"$x^{2}+x+4=0$ 에서 $D=b^{2}-4ac$ 는?","식":["$D=1^{2}-4\\times1\\times4=-15$"],"설명":"$a=1$, $b=1$, $c=4$ 를 대입한다.","확인":"-15","스킬":"G2"},{"제목":"D 의 부호와 교점 개수","힌트":"$D$ 가 음수이면 실근은 몇 개이고 교점은 몇 개일까?","식":["$D=-15<0$ 이므로 실근이 없다","교점은 $0$ 개"],"설명":"교점의 개수는 이차방정식의 서로 다른 실근의 개수와 같다. $D<0$ 이면 실근이 없다.","확인":"0","스킬":"G2"}]},"tb-비상공수1-p042-4-2":{"길":"두 식을 같다고 놓아 이차방정식을 만들고 D의 부호로 교점 개수를 센다","단계":[{"제목":"두 식을 같다고 놓아 정리하기","힌트":"두 식의 $y$ 가 같다고 놓고 $x^{2}$ 의 계수를 양수로 정리하면?","식":["$-x^{2}+4x+3=3x+1$","$x^{2}-x-2=0$"],"설명":"우변을 이항하면 $-x^{2}+x+2=0$ 이다. 양변에 $-1$ 을 곱하면 계산이 쉬워진다.","확인":null,"스킬":"G1"},{"제목":"판별식 D 계산하기","고비":true,"힌트":"$x^{2}-x-2=0$ 에서 $D=b^{2}-4ac$ 는?","식":["$D=(-1)^{2}-4\\times1\\times(-2)=1+8=9$"],"설명":"$c=-2$ 이므로 $-4ac=+8$ 이 더해진다.","확인":"9","스킬":"G2"},{"제목":"D 의 부호와 교점 개수","힌트":"$D$ 가 양수이면 실근은 몇 개이고 교점은 몇 개일까?","식":["$D=9>0$ 이므로 서로 다른 두 실근","교점은 $2$ 개"],"설명":"$D>0$ 이면 서로 다른 두 실근을 가지므로 교점도 $2$ 개이다.","확인":"2","스킬":"G2"}]},"tb-비상공수1-p042-4-3":{"길":"두 식을 연립한 이차방정식의 판별식 부호로 교점의 개수를 정한다","단계":[{"제목":"두 식을 연립해 이차방정식으로 정리","힌트":"교점에서는 $y$ 값이 같으므로 두 식의 우변을 같다고 놓으면?","식":["$2x^{2}+2x-2=-2x-4$","$2x^{2}+4x+2=0$"],"설명":"교점의 $x$ 좌표는 두 식을 동시에 만족하므로 $y$ 를 같게 놓은 방정식의 해이다. 우변을 이항해 $ax^{2}+bx+c=0$ 꼴로 정리한다.","확인":null,"스킬":"G1"},{"제목":"판별식 값 구하기","고비":true,"힌트":"$\\frac{D}{4}=\\left(\\frac{b}{2}\\right)^{2}-ac$ 에 계수를 넣으면?","식":["$\\frac{D}{4}=2^{2}-2\\times2$","$=0$"],"설명":"$b=4$ 이므로 $\\frac{b}{2}=2$ 이고 $a=2,\\ c=2$ 이다. 계산하면 판별식의 값은 $0$ 이다.","확인":"0","스킬":"G2"},{"제목":"판별식 부호로 교점의 개수 정하기","힌트":"$D=0$ 이면 이 이차방정식의 서로 다른 실근은 몇 개일까?","식":["$2(x+1)^{2}=0$","$x=-1$"],"설명":"판별식이 $0$ 이면 중근 하나뿐이므로 그래프와 직선은 한 점에서 만난다. 따라서 교점은 $1$개이다.","확인":"1","스킬":"G2"}]},"tb-비상공수1-p042-5":{"길":"만나지 않을 조건 D<0 을 k 로 풀고 그 안의 자연수만 고른다","단계":[{"제목":"두 식을 연립해 이차방정식으로 정리","힌트":"두 식의 우변을 같다고 놓고 한쪽으로 모으면?","식":["$x^{2}+6=2x+k$","$x^{2}-2x+6-k=0$"],"설명":"그래프와 직선이 만나지 않는다는 것은 이 방정식이 실근을 갖지 않는다는 뜻이다. 우변을 이항해 $ax^{2}+bx+c=0$ 꼴로 정리한다.","확인":null,"스킬":"G1"},{"제목":"판별식을 $k$ 로 나타내기","고비":true,"힌트":"$\\frac{D}{4}=\\left(\\frac{b}{2}\\right)^{2}-ac$ 에 $b=-2,\\ c=6-k$ 를 넣으면?","식":["$\\frac{D}{4}=(-1)^{2}-(6-k)$","$=k-5$"],"설명":"$\\frac{b}{2}=-1$ 이므로 제곱하면 $1$ 이다. 만나지 않으려면 실근이 없어야 하므로 $\\frac{D}{4}<0$ 이어야 한다.","확인":null,"스킬":"G2"},{"제목":"$k$ 의 범위에서 자연수 고르기","힌트":"$k-5<0$ 을 만족하는 자연수는 어디까지일까?","식":["$k-5<0$","$k<5$","$k=1,\\ 2,\\ 3,\\ 4$"],"설명":"$k<5$ 를 만족하는 자연수는 $1$ 부터 $4$ 까지이다. $5$ 는 $D=0$ 이 되어 접하므로 포함하지 않는다.","확인":null,"스킬":"G2"}]},"tb-비상공수1-p042-6":{"길":"접선을 y=2x+a 로 두고 연립한 방정식이 중근을 갖게 a 를 정한다","단계":[{"제목":"기울기가 주어진 직선을 놓고 연립하기","힌트":"기울기가 $2$ 인 직선에서 아직 모르는 것은 무엇일까?","식":["$y=2x+a$","$x^{2}+3x=2x+a$","$x^{2}+x-a=0$"],"설명":"기울기가 $2$ 이므로 직선은 $y=2x+a$ 로 쓴다. 이차함수와 연립해 우변을 이항하면 $x$ 에 대한 이차방정식이 된다.","확인":null,"스킬":"G2"},{"제목":"접할 조건으로 $a$ 구하기","고비":true,"힌트":"접하면 이 이차방정식의 판별식 $D$ 는 얼마여야 할까?","식":["$D=1^{2}-4\\times1\\times(-a)=1+4a$","$1+4a=0$","$a=-\\frac{1}{4}$"],"설명":"직선이 그래프에 접하면 연립한 방정식이 중근을 가지므로 $D=0$ 이다. $1+4a=0$ 에서 $a$ 의 값이 정해진다.","확인":"-1/4","스킬":"G2"},{"제목":"직선의 방정식 쓰기","힌트":"구한 $a$ 를 $y=2x+a$ 에 넣으면?","식":["$y=2x-\\frac{1}{4}$"],"설명":"기울기 $2$ 와 $y$ 절편 $-\\frac{1}{4}$ 을 합쳐 직선의 방정식을 쓴다.","확인":null,"스킬":"G3"}]},"tb-비상공수1-p043-1-1":{"길":"완전제곱 꼴로 꼭짓점을 찾고 범위 안인지 보아 최솟값·최댓값을 가른다","단계":[{"제목":"완전제곱 꼴로 꼭짓점 구하기","힌트":"$x^{2}+6x$ 를 $(x+p)^{2}$ 꼴로 만들면 꼭짓점의 $x$ 좌표는?","식":["$y=x^{2}+6x+2=(x+3)^{2}-7$","꼭짓점 $(-3,\\ -7)$"],"설명":"$x^{2}+6x$ 에 $9$ 를 더해 완전제곱식을 만들고 상수항을 맞춘다. 꼭짓점의 $x$ 좌표는 $(x+3)^{2}$ 에서 읽는다.","확인":"-3","스킬":"A6"},{"제목":"꼭짓점이 범위 안일 때 최솟값 구하기","고비":true,"힌트":"꼭짓점의 $x$ 좌표가 $-4\\le x\\le0$ 안에 있을까? 있다면 아래로 볼록한 함수의 최솟값은?","식":["$-4\\le-3\\le0$","$x=-3$ 일 때 $y=-7$"],"설명":"꼭짓점이 범위 안에 있고 그래프가 아래로 볼록하므로 꼭짓점에서 최솟값을 가진다.","확인":"-7","스킬":"G7"},{"제목":"양 끝값을 비교해 최댓값 구하기","힌트":"$x=-4$ 와 $x=0$ 에서의 $y$ 값은 각각 얼마일까?","식":["$x=-4$ 일 때 $y=16-24+2=-6$","$x=0$ 일 때 $y=2$"],"설명":"꼭짓점이 범위 안이면 최댓값은 두 끝값 중 큰 쪽에서 나온다. $-6<2$ 이므로 최댓값은 $2$ 이다.","확인":"2","스킬":"G7"}]},"tb-비상공수1-p043-1-2":{"길":"꼭짓점이 범위 밖이므로 그래프의 증감을 보고 양 끝값을 비교한다","단계":[{"제목":"완전제곱 꼴로 꼭짓점 구하기","힌트":"$-x^{2}+3x$ 에서 $-1$ 을 묶어 완전제곱으로 만들면 꼭짓점의 $x$ 좌표는?","식":["$y=-\\left(x-\\frac{3}{2}\\right)^{2}+\\frac{49}{4}$"],"설명":"$-x^{2}+3x=-\\left(x-\\frac{3}{2}\\right)^{2}+\\frac{9}{4}$ 이고 상수항 $10$ 을 더하면 $\\frac{49}{4}$ 이다. 꼭짓점의 $x$ 좌표는 $\\frac{3}{2}$ 이다.","확인":"3/2","스킬":"A6"},{"제목":"꼭짓점이 범위 밖일 때 증감 판단하기","고비":true,"힌트":"꼭짓점이 $2\\le x\\le6$ 의 왼쪽 밖이면 이 범위에서 그래프는 올라갈까 내려갈까?","식":["$\\frac{3}{2}<2$","$2\\le x\\le6$ 에서 $y$ 는 감소"],"설명":"위로 볼록하고 꼭짓점이 범위의 왼쪽 바깥에 있으므로 범위 안에서 그래프는 계속 내려간다. 따라서 최댓값은 왼쪽 끝, 최솟값은 오른쪽 끝에서 나온다.","확인":null,"스킬":"G7"},{"제목":"왼쪽 끝에서 최댓값 구하기","힌트":"범위의 왼쪽 끝 값을 $y=-x^{2}+3x+10$ 에 넣으면?","식":["$y=-4+6+10=12$"],"설명":"그래프가 내려가므로 왼쪽 끝의 함숫값이 최댓값이다.","확인":"12","스킬":"G7"},{"제목":"오른쪽 끝에서 최솟값 구하기","힌트":"범위의 오른쪽 끝 값을 $y=-x^{2}+3x+10$ 에 넣으면?","식":["$y=-36+18+10=-8$"],"설명":"그래프가 내려가므로 오른쪽 끝의 함숫값이 최솟값이다.","확인":"-8","스킬":"G7"}]},"tb-비상공수1-p043-2":{"길":"꼭짓점이 범위 밖이면 가까운 끝에서 최솟값이 나오므로 그 값을 -1 로 놓는다","단계":[{"제목":"완전제곱 꼴로 꼭짓점 구하기","힌트":"$x^{2}-4x$ 를 $(x-p)^{2}$ 꼴로 만들면 꼭짓점의 $x$ 좌표는?","식":["$y=x^{2}-4x+a=(x-2)^{2}+a-4$","꼭짓점의 $x$ 좌표는 $2$"],"설명":"$x^{2}-4x$ 에 $4$ 를 더해 완전제곱식을 만들고 상수항을 맞춘다. 꼭짓점의 $x$ 좌표는 $(x-2)^{2}$ 에서 읽는다.","확인":null,"스킬":"A6"},{"제목":"범위와 비교해 최솟값 구하기","고비":true,"힌트":"꼭짓점의 $x$ 좌표가 $-1\\le x\\le1$ 의 안에 있을까? 밖이라면 어느 끝이 꼭짓점에 가까울까?","식":["$2>1$","$x=1$ 일 때 $y=1-4+a=a-3$"],"설명":"꼭짓점이 범위의 오른쪽 바깥에 있고 그래프가 아래로 볼록하므로 범위 안에서 그래프는 계속 내려간다. 따라서 오른쪽 끝 $x=1$ 에서 최솟값을 가진다.","확인":null,"스킬":"G7"},{"제목":"최솟값 조건으로 $a$ 구하기","힌트":"최솟값 $a-3$ 이 $-1$ 과 같다고 놓으면?","식":["$a-3=-1$","$a=2$"],"설명":"구한 최솟값이 문제의 조건과 같아야 하므로 방정식을 세워 $a$ 를 구한다.","확인":"2","스킬":"G7"}]},"tb-비상공수1-p043-3":{"길":"위로 볼록이므로 꼭짓점에서 최대, 꼭짓점에서 먼 끝에서 최소를 잡아 뺀다","단계":[{"제목":"완전제곱 꼴로 꼭짓점 구하기","힌트":"$-2x^{2}-4x$ 에서 $-2$ 를 묶어 완전제곱으로 만들면 꼭짓점의 $x$ 좌표는?","식":["$y=-2(x^{2}+2x)+a=-2(x+1)^{2}+a+2$"],"설명":"$-2$ 로 묶은 괄호 안에 $1$ 을 더하고 빼서 완전제곱식을 만든다. 꼭짓점은 $(-1,\\ a+2)$ 이다.","확인":"-1","스킬":"A6"},{"제목":"꼭짓점이 범위 안일 때 최댓값 구하기","힌트":"꼭짓점의 $x$ 좌표가 $-2\\le x\\le2$ 안에 있을까? 위로 볼록한 함수의 최댓값은?","식":["$-2\\le-1\\le2$","$x=-1$ 일 때 최댓값 $a+2$"],"설명":"꼭짓점이 범위 안에 있고 그래프가 위로 볼록하므로 꼭짓점에서 최댓값을 가진다.","확인":null,"스킬":"G7"},{"제목":"꼭짓점에서 먼 끝에서 최솟값 구하기","고비":true,"힌트":"꼭짓점 $x=-1$ 에서 $x=-2$ 와 $x=2$ 중 어느 쪽이 더 멀까?","식":["$|-2-(-1)|=1,\\ |2-(-1)|=3$","$x=2$ 일 때 $y=-18+a+2=a-16$"],"설명":"위로 볼록한 함수는 꼭짓점에서 멀수록 값이 작아진다. 꼭짓점에서 더 먼 끝 $x=2$ 에서 최솟값을 가진다.","확인":null,"스킬":"G7"},{"제목":"최댓값과 최솟값의 차 구하기","힌트":"$(a+2)-(a-16)$ 을 계산하면?","식":["$(a+2)-(a-16)=18$"],"설명":"$a$ 가 서로 없어지므로 차는 실수 $a$ 의 값과 관계없이 일정하다.","확인":"18","스킬":"G7"}]},"tb-비상공수1-p043-4":{"길":"최댓값 조건으로 a² 의 값만 구하고 먼 끝에서 최솟값을 계산한다","단계":[{"제목":"완전제곱 꼴로 고치기","힌트":"$-x^{2}+6x$ 에서 $-1$ 을 묶어 완전제곱으로 만들면?","식":["$f(x)=-(x^{2}-6x)-a^{2}+8$","$=-(x-3)^{2}-a^{2}+17$"],"설명":"$x^{2}-6x$ 에 $9$ 를 더해 완전제곱식을 만들면 바깥에서 $9$ 를 보정해 상수항이 $-a^{2}+17$ 이 된다. 꼭짓점의 $x$ 좌표는 $3$ 이다.","확인":null,"스킬":"A6"},{"제목":"최댓값 조건으로 $a^{2}$ 구하기","고비":true,"힌트":"꼭짓점 $x=3$ 이 범위 안이면 최댓값은 어디서 나올까? 그 값이 $2$ 이므로 식을 세우면?","식":["$0\\le3\\le4$","$f(3)=-a^{2}+17=2$","$a^{2}=15$"],"설명":"꼭짓점이 범위 안에 있고 위로 볼록하므로 꼭짓점에서 최댓값을 가진다. $a$ 자체는 필요 없고 $a^{2}$ 의 값만 구하면 된다.","확인":"15","스킬":"G7"},{"제목":"먼 끝에서 최솟값 구하기","힌트":"꼭짓점 $x=3$ 에서 $x=0$ 과 $x=4$ 중 어느 쪽이 더 멀까? 그 끝값은?","식":["$|0-3|=3>|4-3|=1$","$f(0)=-a^{2}+8=-15+8=-7$"],"설명":"위로 볼록한 함수는 꼭짓점에서 먼 끝 $x=0$ 에서 최솟값을 가진다. 여기에 $a^{2}=15$ 를 넣는다.","확인":"-7","스킬":"G7"}]},"tb-비상공수1-p043-5":{"길":"1초 이내를 범위로 쓰고 꼭짓점의 위치를 보아 최대·최소를 가른다","단계":[{"제목":"범위 정하고 완전제곱 꼴로 고치기","힌트":"1초 이내는 $t$ 의 범위로 어떻게 쓸까? $-5t^{2}+4t$ 를 완전제곱으로 만들면 꼭짓점의 $t$ 좌표는?","식":["$0\\le t\\le1$","$h(t)=-5\\left(t-\\frac{2}{5}\\right)^{2}+\\frac{14}{5}$"],"설명":"점프한 순간부터 $1$초 이내이므로 $0\\le t\\le1$ 이다. $-5$ 로 묶어 완전제곱식을 만들면 꼭짓점의 $t$ 좌표는 $\\frac{2}{5}$ 이다.","확인":"2/5","스킬":"C7"},{"제목":"꼭짓점이 범위 안일 때 최댓값 구하기","고비":true,"힌트":"꼭짓점의 $t$ 좌표가 $0\\le t\\le1$ 안에 있을까? 위로 볼록한 함수의 최댓값은?","식":["$0\\le\\frac{2}{5}\\le1$","$t=\\frac{2}{5}$ 일 때 $h=\\frac{14}{5}$"],"설명":"꼭짓점이 범위 안에 있고 그래프가 위로 볼록하므로 꼭짓점에서 최댓값을 가진다.","확인":"14/5","스킬":"G7"},{"제목":"먼 끝에서 최솟값 구하기","힌트":"꼭짓점 $t=\\frac{2}{5}$ 에서 $t=0$ 과 $t=1$ 중 어느 쪽이 더 멀까? 그 끝값은?","식":["$\\left|0-\\frac{2}{5}\\right|=\\frac{2}{5}<\\left|1-\\frac{2}{5}\\right|=\\frac{3}{5}$","$h(1)=-5+4+2=1$"],"설명":"위로 볼록한 함수는 꼭짓점에서 먼 끝 $t=1$ 에서 최솟값을 가진다.","확인":"1","스킬":"G7"}]},"tb-비상공수1-p043-6":{"길":"가로를 x 로 두고 세로를 x 로 나타낸 넓이를 완전제곱 꼴로 바꾼다","단계":[{"제목":"둘레 조건으로 세로를 $x$ 로 나타내기","힌트":"둘레가 $24\\,\\mathrm{cm}$ 이면 가로와 세로의 합은 얼마일까?","식":["$2(x+y)=24$","가로 $+$ 세로 $=12$","세로 $=12-x$"],"설명":"직사각형의 둘레는 (가로 + 세로)의 $2$배이다. 가로를 $x$ 로 두면 세로는 $12-x$ 이고 둘 다 양수이므로 $0<x<12$ 이다.","확인":"12","스킬":"C7"},{"제목":"넓이를 완전제곱 꼴로 나타내기","고비":true,"힌트":"넓이 $S=x(12-x)$ 를 $-(x-p)^{2}+q$ 꼴로 바꾸면?","식":["$S=x(12-x)=-x^{2}+12x$","$=-(x-6)^{2}+36$"],"설명":"$-x^{2}+12x=-(x^{2}-12x)$ 에서 $x^{2}-12x$ 에 $36$ 을 더해 완전제곱식을 만들고 바깥에서 보정한다.","확인":null,"스킬":"A6"},{"제목":"넓이가 최대일 때 가로와 세로 구하기","힌트":"꼭짓점의 $x$ 좌표가 $0<x<12$ 안에 있을까? 그때 세로는?","식":["$0<6<12$","$x=6$ 일 때 $S$ 가 최대","세로 $=12-6=6$"],"설명":"꼭짓점이 범위 안에 있으므로 $x=6$ 에서 넓이가 최대이다. 이때 세로도 같은 값이 되어 정사각형이 된다.","확인":"6","스킬":"G7"}]},"tb-비상공수1-p044-1-1":{"길":"상수항의 약수를 넣어 근을 찾고 조립제법으로 이차식까지 내린다","단계":[{"제목":"인수정리로 근 하나 찾기","고비":true,"힌트":"$P(x)=x^{3}-x^{2}+2$ 에서 상수항 $2$ 의 약수 $\\pm1,\\ \\pm2$ 중 $P(x)=0$ 이 되는 값은?","식":["$P(-1)=-1-1+2=0$"],"설명":"정수 근은 상수항의 약수 중에 있다. $x=-1$ 을 넣으면 $0$ 이 되므로 $x+1$ 이 인수이다.","확인":"-1","스킬":"A4"},{"제목":"조립제법으로 인수분해하기","힌트":"$x^{3}-x^{2}+2$ 를 $x+1$ 로 나눈 몫은?","식":["$x^{3}-x^{2}+2=(x+1)(x^{2}-2x+2)$"],"설명":"조립제법으로 나누면 몫이 $x^{2}-2x+2$ 이고 나머지는 $0$ 이다.","확인":null,"스킬":"A4"},{"제목":"이차방정식의 근 구하기","힌트":"$x^{2}-2x+2=0$ 에 근의 공식을 쓰면?","식":["$x=1\\pm\\sqrt{1-2}=1\\pm i$","$x=-1$ 또는 $x=1\\pm i$"],"설명":"$\\frac{D}{4}=1-2=-1<0$ 이므로 허근이 나온다. 앞에서 구한 $x=-1$ 과 합쳐 세 근을 쓴다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p044-1-2":{"길":"근 두 개를 찾아 조립제법을 두 번 하고 남은 이차식을 푼다","단계":[{"제목":"인수정리로 근 두 개 찾기","고비":true,"힌트":"$P(x)=x^{4}-3x^{3}+3x^{2}+x-6$ 에서 상수항 $-6$ 의 약수 중 $P(x)=0$ 이 되는 값은?","식":["$P(-1)=1+3+3-1-6=0$","$P(2)=16-24+12+2-6=0$"],"설명":"정수 근은 상수항의 약수 중에 있다. $x=-1$ 과 $x=2$ 를 넣으면 모두 $0$ 이 되므로 $x+1$ 과 $x-2$ 가 인수이다.","확인":null,"스킬":"A4"},{"제목":"조립제법을 두 번 해 이차식까지 내리기","힌트":"$x+1$ 로 나눈 몫을 다시 $x-2$ 로 나누면 몫은?","식":["$P(x)=(x+1)(x^{3}-4x^{2}+7x-6)$","$P(x)=(x+1)(x-2)(x^{2}-2x+3)$"],"설명":"$x+1$ 로 나눈 몫 $x^{3}-4x^{2}+7x-6$ 을 $x-2$ 로 다시 나누면 몫이 $x^{2}-2x+3$ 이고 나머지는 $0$ 이다.","확인":null,"스킬":"A4"},{"제목":"남은 이차방정식의 근 구하기","힌트":"$x^{2}-2x+3=0$ 에 근의 공식을 쓰면?","식":["$x=1\\pm\\sqrt{1-3}=1\\pm\\sqrt{2}i$","$x=-1$ 또는 $x=2$ 또는 $x=1\\pm\\sqrt{2}i$"],"설명":"$\\frac{D}{4}=1-3=-2<0$ 이므로 허근이 나온다. 앞에서 구한 두 근과 합쳐 네 근을 쓴다.","확인":null,"스킬":"A5"}]},"tb-비상공수1-p044-1-3":{"길":"근 두 개를 찾고 x=2 로 두 번 나누어떨어지는지 확인해 인수분해한다","단계":[{"제목":"인수정리로 근 두 개 찾기","힌트":"$P(x)=x^{4}-9x^{2}+4x+12$ 에서 상수항 $12$ 의 약수 중 $P(x)=0$ 이 되는 값은?","식":["$P(-1)=1-9-4+12=0$","$P(2)=16-36+8+12=0$"],"설명":"정수 근은 상수항의 약수 중에 있다. $x=-1$ 과 $x=2$ 를 넣으면 모두 $0$ 이 되므로 $x+1$ 과 $x-2$ 가 인수이다.","확인":null,"스킬":"A4"},{"제목":"조립제법으로 $x-2$ 를 한 번 더 꺼내기","고비":true,"힌트":"$x+1$ 과 $x-2$ 로 차례로 나눈 몫에 다시 $x=2$ 를 넣으면 $0$ 이 될까?","식":["$P(x)=(x+1)(x-2)(x^{2}+x-6)$","$x^{2}+x-6=(x-2)(x+3)$"],"설명":"$x+1$ 로 나눈 몫 $x^{3}-x^{2}-8x+12$ 를 $x-2$ 로 나누면 몫이 $x^{2}+x-6$ 이다. 이 몫이 $x=2$ 에서도 $0$ 이 되므로 $x-2$ 가 한 번 더 인수이다.","확인":null,"스킬":"A4"},{"제목":"인수분해한 꼴에서 근 읽기","힌트":"$(x+1)(x-2)^{2}(x+3)=0$ 의 근은?","식":["$P(x)=(x+1)(x-2)^{2}(x+3)=0$","$x=-1,\\ -3$ 과 $x=2$ (중근)"],"설명":"$(x-2)^{2}$ 이 들어 있으므로 $x=2$ 는 중근이다. 나머지 두 인수에서 $x=-1$, $x=-3$ 이 나온다.","확인":null,"스킬":"A4"}]},"tb-비상공수1-p044-2":{"길":"실근으로 삼차식을 인수분해하고 이차 인수의 두 근의 곱을 구한다","단계":[{"제목":"인수정리로 실근 찾기","고비":true,"힌트":"$P(x)=x^{3}+4x^{2}+6x+4$ 에서 상수항 $4$ 의 약수 중 $P(x)=0$ 이 되는 값은?","식":["$P(-2)=-8+16-12+4=0$"],"설명":"정수 근은 상수항의 약수 중에 있다. $x=-2$ 를 넣으면 $0$ 이 되므로 $x+2$ 가 인수이다.","확인":"-2","스킬":"A4"},{"제목":"조립제법으로 이차 인수 얻기","힌트":"$x^{3}+4x^{2}+6x+4$ 를 $x+2$ 로 나눈 몫은?","식":["$x^{3}+4x^{2}+6x+4=(x+2)(x^{2}+2x+2)$"],"설명":"조립제법으로 나누면 몫이 $x^{2}+2x+2$ 이고 나머지는 $0$ 이다. 실근은 $x=-2$ 하나이므로 두 허근은 이 이차식의 근이다.","확인":null,"스킬":"A4"},{"제목":"두 허근의 곱 구하기","힌트":"$x^{2}+2x+2=0$ 의 두 근의 곱은 근과 계수의 관계로 얼마일까?","식":["$\\frac{D}{4}=1-2=-1<0$","$\\alpha\\beta=\\frac{2}{1}=2$"],"설명":"판별식이 음수이므로 이 이차식의 두 근은 허근이다. 두 근의 곱은 $\\frac{c}{a}$ 이다.","확인":"2","스킬":"A2"}]},"tb-비상공수1-p044-3":{"길":"근을 대입해 a 를 구한 뒤 삼차식을 인수분해해 나머지 근을 찾는다","단계":[{"제목":"근의 제곱과 세제곱 구하기","고비":true,"힌트":"$(1+\\sqrt{2}i)^{2}$ 을 전개하고 $i^{2}=-1$ 을 쓰면? 세제곱은 그 결과에 한 번 더 곱하면?","식":["$(1+\\sqrt{2}i)^{2}=-1+2\\sqrt{2}i$","$(1+\\sqrt{2}i)^{3}=-5+\\sqrt{2}i$"],"설명":"$(1+\\sqrt{2}i)^{2}=1+2\\sqrt{2}i+2i^{2}=-1+2\\sqrt{2}i$ 이다. 여기에 $1+\\sqrt{2}i$ 를 곱하면 세제곱이 $-5+\\sqrt{2}i$ 가 된다.","확인":null,"스킬":"A5"},{"제목":"근을 대입해 $a$ 구하기","힌트":"실수부와 허수부를 따로 모아 $0$ 이 되게 하면?","식":["$(-5+\\sqrt{2}i)-3(-1+2\\sqrt{2}i)+5(1+\\sqrt{2}i)+a=0$","$(a+3)+0\\cdot i=0$","$a=-3$"],"설명":"허수부는 $\\sqrt{2}-6\\sqrt{2}+5\\sqrt{2}=0$ 이고 실수부는 $-5+3+5+a=a+3$ 이다. 복소수가 $0$ 이려면 실수부가 $0$ 이어야 한다.","확인":"-3","스킬":"A5"},{"제목":"인수분해로 나머지 근 구하기","힌트":"$a=-3$ 일 때 $x^{3}-3x^{2}+5x-3$ 에 $x=1$ 을 넣으면?","식":["$x^{3}-3x^{2}+5x-3=(x-1)(x^{2}-2x+3)$","$x=1$ 또는 $x=1\\pm\\sqrt{2}i$"],"설명":"$x=1$ 을 넣으면 $0$ 이므로 $x-1$ 이 인수이고, 몫 $x^{2}-2x+3$ 의 근은 $1\\pm\\sqrt{2}i$ 이다. 주어진 근 $1+\\sqrt{2}i$ 를 뺀 나머지는 $1$ 과 $1-\\sqrt{2}i$ 이다.","확인":null,"스킬":"A4"}]},"tb-비상공수1-p044-4":{"길":"x²+2x 를 X 로 치환해 인수분해하고 허근이 나오는 이차식의 합과 곱을 쓴다","단계":[{"제목":"공통부분을 $X$ 로 치환해 풀기","힌트":"$x^{2}+2x=X$ 로 놓으면 방정식이 $X$ 에 대한 어떤 식이 될까?","식":["$X^{2}+5X+4=0$","$(X+1)(X+4)=0$","$X=-1$ 또는 $X=-4$"],"설명":"$x^{2}+2x$ 가 두 번 나오므로 $X$ 로 바꾸면 이차방정식이 된다. 인수분해해 $X$ 의 값을 구한다.","확인":null,"스킬":"A1"},{"제목":"허근이 나오는 이차방정식 고르기","고비":true,"힌트":"$X=-1$, $X=-4$ 를 $x^{2}+2x=X$ 에 되돌리면 어느 쪽의 판별식이 음수일까?","식":["$x^{2}+2x+1=(x+1)^{2}=0$","$x^{2}+2x+4=0,\\ \\frac{D}{4}=1-4=-3<0$"],"설명":"$X=-1$ 이면 $x=-1$ 이 중근이라 실근이다. $X=-4$ 일 때만 $\\frac{D}{4}<0$ 이므로 두 허근 $\\alpha$, $\\beta$ 는 $x^{2}+2x+4=0$ 의 근이다.","확인":"-3","스킬":"A1"},{"제목":"합과 곱으로 값 구하기","힌트":"$\\frac{1}{\\alpha}+\\frac{1}{\\beta}$ 을 통분하면 $\\alpha+\\beta$ 와 $\\alpha\\beta$ 로 어떻게 쓸까?","식":["$\\alpha+\\beta=-2,\\ \\alpha\\beta=4$","$\\frac{1}{\\alpha}+\\frac{1}{\\beta}=\\frac{\\alpha+\\beta}{\\alpha\\beta}=-\\frac{1}{2}$"],"설명":"근과 계수의 관계에서 두 근의 합은 $-2$, 곱은 $4$ 이다. 통분하면 합을 곱으로 나눈 꼴이 된다.","확인":"-1/2","스킬":"A2"}]},"tb-비상공수1-p044-5":{"길":"새 직육면체의 부피 식을 세워 삼차방정식을 풀고 높이가 양수인 근만 남긴다","단계":[{"제목":"모서리를 $x$ 로 두고 부피 식 세우기","힌트":"처음 모서리를 $x$ 라 하면 새 직육면체의 가로·세로·높이는 각각 얼마일까?","식":["$(x+2)(x+3)(x-1)=\\frac{5}{2}x^{3}$"],"설명":"가로는 $x+2$, 세로는 $x+3$, 높이는 $x-1$ 이다. 높이가 양수여야 하므로 $x>1$ 이고, 새 부피가 처음 부피 $x^{3}$ 의 $\\frac{5}{2}$ 배이다.","확인":null,"스킬":"C7"},{"제목":"삼차방정식으로 정리하기","힌트":"좌변을 전개하고 양변에 $2$ 를 곱해 한쪽으로 모으면?","식":["$x^{3}+4x^{2}+x-6=\\frac{5}{2}x^{3}$","$3x^{3}-8x^{2}-2x+12=0$"],"설명":"$(x+2)(x+3)(x-1)=x^{3}+4x^{2}+x-6$ 이다. 양변에 $2$ 를 곱한 뒤 우변을 이항해 정리한다.","확인":null,"스킬":"C7"},{"제목":"정수 근을 찾아 인수분해하기","고비":true,"힌트":"$f(x)=3x^{3}-8x^{2}-2x+12$ 에 작은 정수를 넣어 $f(x)=0$ 이 되는 값은?","식":["$f(2)=24-32-4+12=0$","$f(x)=(x-2)(3x^{2}-2x-6)$"],"설명":"$x=2$ 를 넣으면 $0$ 이므로 $x-2$ 가 인수이다. 조립제법으로 나누면 몫이 $3x^{2}-2x-6$ 이다.","확인":"2","스킬":"A4"},{"제목":"이차방정식의 근에서 조건에 맞는 값 고르기","힌트":"$3x^{2}-2x-6=0$ 의 근 중 $x>1$ 인 것은?","식":["$x=\\frac{1\\pm\\sqrt{19}}{3}$","$x=2$ 또는 $x=\\frac{1+\\sqrt{19}}{3}$"],"설명":"$\\frac{1-\\sqrt{19}}{3}$ 은 음수이므로 모서리의 길이가 될 수 없다. $\\frac{1+\\sqrt{19}}{3}$ 은 $1$ 보다 크므로 $x=2$ 와 함께 답이 된다.","확인":null,"스킬":"A4"}]},"tb-비상공수1-p044-6-1":{"길":"ω³=1 과 ω²+ω+1=0 을 얻어 전개한 식에 넣는다","단계":[{"제목":"$\\omega$ 가 만족하는 두 식 얻기","힌트":"$x^{3}-1$ 을 인수분해하면 허근 $\\omega$ 는 어느 인수의 근일까?","식":["$x^{3}-1=(x-1)(x^{2}+x+1)$","$\\omega^{2}+\\omega+1=0,\\ \\omega^{3}=1$"],"설명":"허근은 $x-1=0$ 의 근이 아니므로 $x^{2}+x+1=0$ 의 근이다. 또 $\\omega$ 는 $x^{3}-1=0$ 의 근이므로 $\\omega^{3}=1$ 이다.","확인":null,"스킬":"A5"},{"제목":"곱을 전개해 묶기","고비":true,"힌트":"$(1+\\omega)(1+\\omega^{2})$ 를 전개한 뒤 $\\omega^{2}+\\omega+1$ 이 보이게 묶으면?","식":["$1+\\omega^{2}+\\omega+\\omega^{3}$","$=(\\omega^{2}+\\omega+1)+\\omega^{3}$"],"설명":"네 항 중 $1$, $\\omega$, $\\omega^{2}$ 을 묶으면 $\\omega^{2}+\\omega+1$ 이 된다. 남은 항은 $\\omega^{3}$ 이다.","확인":null,"스킬":"A5"},{"제목":"성질을 대입해 값 구하기","힌트":"$\\omega^{2}+\\omega+1$ 과 $\\omega^{3}$ 에 각각 알고 있는 값을 넣으면?","식":["$=0+1=1$"],"설명":"$\\omega^{2}+\\omega+1=0$ 이고 $\\omega^{3}=1$ 이므로 합은 $1$ 이다.","확인":"1","스킬":"A5"}]},"tb-비상공수1-p044-6-2":{"길":"ω+1 을 -ω² 으로 바꾸면 두 분수가 약분된다","단계":[{"제목":"$\\omega+1$ 을 $\\omega^{2}$ 으로 나타내기","힌트":"$\\omega^{2}+\\omega+1=0$ 에서 $\\omega+1$ 을 $\\omega^{2}$ 으로 쓰면?","식":["$\\omega^{2}+\\omega+1=0$","$\\omega+1=-\\omega^{2}$"],"설명":"허근 $\\omega$ 는 $x^{2}+x+1=0$ 의 근이다. $\\omega^{2}$ 을 이항하면 $\\omega+1=-\\omega^{2}$ 이다.","확인":null,"스킬":"A5"},{"제목":"$\\omega+1$ 자리에 $-\\omega^{2}$ 넣기","고비":true,"힌트":"분자와 분모의 $\\omega+1$ 을 모두 $-\\omega^{2}$ 으로 바꾸면 식은?","식":["$\\frac{-\\omega^{2}}{\\omega^{2}}+\\frac{\\omega^{2}}{-\\omega^{2}}$"],"설명":"$\\omega^{3}=1$ 이므로 $\\omega\\ne0$ 이고 분모 $\\omega^{2}$ 은 $0$ 이 아니다. 두 분수 모두 분자와 분모가 같은 꼴이 된다.","확인":null,"스킬":"A5"},{"제목":"약분해 값 구하기","힌트":"각 분수를 약분하면 얼마씩일까?","식":["$=-1+(-1)=-2$"],"설명":"첫째 분수는 $-1$, 둘째 분수도 $\\frac{\\omega^{2}}{-\\omega^{2}}=-1$ 이다. 합은 $-2$ 이다.","확인":"-2","스킬":"A5"}]},"tb-비상공수1-p045-1":{"길":"일차식을 y 에 대해 정리해 이차식에 대입하고 x 를 먼저 구한다","단계":[{"제목":"일차식을 $y$ 에 대해 정리해 대입하기","힌트":"$x-y=-2$ 에서 $y$ 를 $x$ 로 나타내어 둘째 식에 넣으면?","식":["$y=x+2$","$x^{2}-3x(x+2)+(x+2)^{2}=1$"],"설명":"일차식은 한 문자를 다른 문자로 나타내기 쉽다. $y$ 를 $x$ 로 나타내 이차식에 대입하면 $x$ 만 남는다.","확인":null,"스킬":"A10"},{"제목":"$x$ 에 대한 이차방정식 풀기","고비":true,"힌트":"대입한 식을 전개해 $x^{2}$ 항을 정리하면 어떤 이차방정식이 될까?","식":["$-x^{2}-2x+4=1$","$x^{2}+2x-3=0$","$(x+3)(x-1)=0$"],"설명":"$x^{2}-3x^{2}-6x+x^{2}+4x+4=-x^{2}-2x+4$ 이다. $1$ 을 이항하고 부호를 바꿔 인수분해한다.","확인":null,"스킬":"A10"},{"제목":"$y$ 를 구해 순서쌍 쓰기","힌트":"구한 $x$ 의 값을 $y=x+2$ 에 각각 넣으면?","식":["$x=-3$ 일 때 $y=-1$","$x=1$ 일 때 $y=3$"],"설명":"각 $x$ 에 대응하는 $y$ 를 구해 순서쌍으로 쓴다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p045-2":{"길":"일차식을 대입해 해를 모두 구한 뒤 정수 조건으로 하나를 고른다","단계":[{"제목":"대입해 이차방정식으로 정리하기","힌트":"$x+y=2$ 에서 $y$ 를 $x$ 로 나타내어 둘째 식에 넣으면?","식":["$y=2-x$","$2x^{2}+(2-x)^{2}=19$","$3x^{2}-4x-15=0$"],"설명":"$2x^{2}+4-4x+x^{2}=3x^{2}-4x+4$ 이고 $19$ 를 이항하면 $3x^{2}-4x-15=0$ 이다.","확인":null,"스킬":"A10"},{"제목":"이차방정식 풀기","고비":true,"힌트":"$3x^{2}-4x-15$ 를 인수분해하면?","식":["$(3x+5)(x-3)=0$","$x=-\\frac{5}{3}$ 또는 $x=3$"],"설명":"곱이 $-45$ 이고 합이 $-4$ 인 두 수 $-9$, $5$ 로 가운데 항을 쪼개 인수분해한다.","확인":null,"스킬":"A10"},{"제목":"정수 조건으로 해 고르기","힌트":"두 $x$ 값 중 정수인 것의 $y$ 값은 얼마일까?","식":["$x=-\\frac{5}{3}$ 은 정수가 아니므로 제외","$x=3$ 일 때 $y=2-3=-1$"],"설명":"정수 조건을 만족하는 해는 $x=3$ 뿐이고, 이때 $y=-1$ 이다.","확인":"-1","스킬":"A10"}]},"tb-비상공수1-p045-3":{"길":"대입해 해를 구한 뒤 x, y 가 모두 양수인 쌍만 남긴다","단계":[{"제목":"대입해 이차방정식으로 정리하기","힌트":"$x+y=3$ 에서 $y$ 를 $x$ 로 나타내어 둘째 식에 넣으면?","식":["$y=3-x$","$x^{2}+x(3-x)-(3-x)^{2}=5$","$x^{2}-9x+14=0$"],"설명":"$x^{2}+3x-x^{2}-9+6x-x^{2}=-x^{2}+9x-9$ 이고 $5$ 를 이항해 부호를 바꾸면 $x^{2}-9x+14=0$ 이다.","확인":null,"스킬":"A10"},{"제목":"해를 구해 순서쌍 만들기","힌트":"$x^{2}-9x+14$ 를 인수분해하고 각 $x$ 의 $y$ 값을 구하면?","식":["$(x-2)(x-7)=0$","$(x,\\ y)=(2,\\ 1)$ 또는 $(7,\\ -4)$"],"설명":"곱이 $14$ 이고 합이 $-9$ 인 두 수 $-2$, $-7$ 로 인수분해한다. $y=3-x$ 에 각각 넣어 순서쌍을 만든다.","확인":null,"스킬":"A10"},{"제목":"양수 조건으로 해 고르기","고비":true,"힌트":"두 순서쌍에서 $x$, $y$ 가 모두 양수인 것은?","식":["$(7,\\ -4)$ 는 $y<0$ 이므로 제외","$x=2,\\ y=1$"],"설명":"$x$ 만 보고 고르지 않고 $y$ 의 부호도 확인해야 한다. 양수 조건을 만족하는 해는 $(2,\\ 1)$ 뿐이다.","확인":"2","스킬":"C2"},{"제목":"$|y-x|$ 의 값 구하기","힌트":"$x=2,\\ y=1$ 을 $|y-x|$ 에 넣으면?","식":["$|y-x|=|1-2|=1$"],"설명":"절댓값 안은 $-1$ 이고 그 절댓값은 $1$ 이다.","확인":"1","스킬":"A10"}]},"tb-비상공수1-p045-4":{"길":"0 이 되는 식을 인수분해해 y=2x, y=-3x 로 나누어 대입한다","단계":[{"제목":"우변이 $0$ 인 식을 인수분해하기","힌트":"$6x^{2}-xy-y^{2}$ 을 $x$, $y$ 의 일차식 두 개의 곱으로 나타내면?","식":["$6x^{2}-xy-y^{2}=(2x-y)(3x+y)=0$","$y=2x$ 또는 $y=-3x$"],"설명":"곱이 $0$ 이면 어느 한 인수가 $0$ 이다. 따라서 $y$ 를 $x$ 로 나타낸 두 경우로 나누어 둘째 식에 대입한다.","확인":null,"스킬":"A10"},{"제목":"$y=2x$ 일 때의 해 구하기","힌트":"$y=2x$ 를 $2x^{2}-3xy-y^{2}=-8$ 에 넣으면 $x^{2}$ 의 값은?","식":["$2x^{2}-6x^{2}-4x^{2}=-8$","$x^{2}=1$","$(x,\\ y)=(1,\\ 2),\\ (-1,\\ -2)$"],"설명":"$-8x^{2}=-8$ 이므로 $x^{2}=1$ 이다. $x=\\pm1$ 이고 $y=2x$ 이므로 $y=\\pm2$ 이다.","확인":"1","스킬":"A10"},{"제목":"$y=-3x$ 일 때의 해 구하기","고비":true,"힌트":"$y=-3x$ 를 둘째 식에 넣으면 $x^{2}$ 이 양수일까 음수일까?","식":["$2x^{2}+9x^{2}-9x^{2}=-8$","$x^{2}=-4$","$(x,\\ y)=(2i,\\ -6i),\\ (-2i,\\ 6i)$"],"설명":"$2x^{2}=-8$ 이므로 $x^{2}=-4$ 이고 $x=\\pm2i$ 로 허수이다. 문제에서 $x$, $y$ 가 실수라는 조건이 없으므로 이 해도 포함한다.","확인":null,"스킬":"A5"},{"제목":"$\\alpha+\\beta$ 의 값 모아 보기 판정하기","힌트":"네 해에서 $x+y$ 의 값을 각각 구하면 보기 중 나오지 않는 것은?","식":["$\\alpha+\\beta=3,\\ -3,\\ -4i,\\ 4i$","될 수 없는 것은 ㄱ, ㄹ"],"설명":"$(1,\\ 2)$ 에서 $3$, $(-1,\\ -2)$ 에서 $-3$, $(2i,\\ -6i)$ 에서 $-4i$, $(-2i,\\ 6i)$ 에서 $4i$ 이다. 보기 중 $-2i$ 와 $2i$ 는 나오지 않는다.","확인":null,"스킬":"C3"}]},"tb-비상공수1-p045-5":{"길":"우변이 0 인 식을 인수분해해 x 와 y 의 관계를 얻고 경우마다 합을 구해 비교한다","단계":[{"제목":"우변이 $0$ 인 식을 인수분해하기","힌트":"$2x^{2}-3xy-2y^{2}$ 을 일차식 두 개의 곱으로 나타내면?","식":["$2x^{2}-3xy-2y^{2}=(x-2y)(2x+y)=0$","$x=2y$ 또는 $y=-2x$"],"설명":"곱이 $0$ 이면 어느 한 인수가 $0$ 이다. 따라서 $x$ 와 $y$ 의 관계가 두 가지로 나뉜다.","확인":null,"스킬":"A10"},{"제목":"$x=2y$ 일 때의 $\\alpha+\\beta$ 구하기","힌트":"$x=2y$ 를 $xy+y^{2}=12$ 에 넣으면 $y^{2}$ 의 값은?","식":["$2y^{2}+y^{2}=12$","$y^{2}=4$","$\\alpha+\\beta=3y=\\pm6$"],"설명":"$3y^{2}=12$ 이므로 $y^{2}=4$ 이고 $y=\\pm2$ 이다. $x+y=3y$ 이므로 합은 $\\pm6$ 이다.","확인":"4","스킬":"A10"},{"제목":"$y=-2x$ 일 때의 $\\alpha+\\beta$ 구하기","고비":true,"힌트":"$y=-2x$ 를 $xy+y^{2}=12$ 에 넣으면 $x^{2}$ 의 값은? 이때 $x+y$ 는 $x$ 로 어떻게 쓸까?","식":["$x(-2x)+(-2x)^{2}=12$","$2x^{2}=12$","$\\alpha+\\beta=x+(-2x)=-x=\\mp\\sqrt{6}$"],"설명":"$-2x^{2}+4x^{2}=2x^{2}$ 이므로 $x^{2}=6$ 이고 $x=\\pm\\sqrt{6}$ 이다. 합은 $-x$ 이므로 $\\mp\\sqrt{6}$ 이다.","확인":null,"스킬":"A10"},{"제목":"최댓값 고르기","힌트":"가능한 $\\alpha+\\beta$ 의 값 중 가장 큰 것은?","식":["$\\alpha+\\beta=\\pm6,\\ \\pm\\sqrt{6}$","$6>\\sqrt{6}$ 이므로 최댓값은 $6$"],"설명":"$\\sqrt{6}$ 은 $3$ 보다 작으므로 $6$ 이 가장 크다.","확인":"6","스킬":"A10"}]},"tb-비상공수1-p045-6":{"길":"자리 수를 x, y 로 두고 두 조건을 연립해 자연수 해만 고른다","단계":[{"제목":"두 조건을 식으로 쓰기","힌트":"십의 자리를 $x$, 일의 자리를 $y$ 라 하면 두 자리 수는 어떻게 쓸까?","식":["$(10x+y)-2(x+y)=13$","$8x-y=13$","$x^{2}+y^{2}=13$"],"설명":"두 자리 수는 $10x+y$ 이고 각 자리 수의 합은 $x+y$ 이다. 조건 (가)를 정리하면 $8x-y=13$, 조건 (나)는 $x^{2}+y^{2}=13$ 이다.","확인":null,"스킬":"C7"},{"제목":"일차식을 대입해 $x$ 구하기","고비":true,"힌트":"$8x-y=13$ 에서 $y$ 를 $x$ 로 나타내어 $x^{2}+y^{2}=13$ 에 넣으면?","식":["$y=8x-13$","$x^{2}+(8x-13)^{2}=13$","$5x^{2}-16x+12=0$","$(5x-6)(x-2)=0$"],"설명":"$x^{2}+64x^{2}-208x+169=13$ 이므로 $65x^{2}-208x+156=0$ 이고 양변을 $13$ 으로 나누면 $5x^{2}-16x+12=0$ 이다.","확인":null,"스킬":"A10"},{"제목":"자연수 조건으로 해 고르고 수 구하기","힌트":"$x$ 의 두 값 중 자연수인 것으로 $y$ 와 두 자리 수를 구하면?","식":["$x=\\frac{6}{5}$ 은 자연수가 아니므로 제외","$x=2,\\ y=8\\times2-13=3$","$10\\times2+3=23$"],"설명":"자리 수는 자연수이므로 $x=2$ 이고 $y=3$ 이다. 두 자리 수는 $10x+y=23$ 이다.","확인":"23","스킬":"A10"}]},"tb-비상공수1-p046-1-1":{"길":"두 부등식을 각각 풀고 수직선에서 겹치는 부분만 남긴다","단계":[{"제목":"각 부등식 풀기","고비":true,"힌트":"$3x-6>0$ 과 $-5+x<-2$ 는 각각 $x$ 가 어떤 범위일 때 성립할까?","식":["$3x-6>0\\ \\Rightarrow\\ x>2$","$-5+x<-2\\ \\Rightarrow\\ x<3$"],"설명":"첫째 식은 $-6$ 을 이항해 $3$ 으로 나누고, 둘째 식은 $-5$ 를 이항한다. 계수가 양수이므로 부등호의 방향은 그대로이다.","확인":null,"스킬":"G6"},{"제목":"공통부분 구하기","힌트":"$x>2$ 와 $x<3$ 을 수직선에 그리면 겹치는 부분은?","식":["$2<x<3$"],"설명":"연립부등식의 해는 두 부등식을 동시에 만족하는 공통부분이다. $2$ 보다 크고 $3$ 보다 작은 구간이 겹친다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p046-1-2":{"길":"양변에 음수를 곱하면 부등호가 바뀐다는 점에 주의해 각각 풀고 겹침을 본다","단계":[{"제목":"첫 부등식 풀기","고비":true,"힌트":"$-3x$ 를 좌변으로 옮겨 정리하면 $x$ 의 계수는 양수일까 음수일까?","식":["$-4x\\ge5-3x$","$-x\\ge5$","$x\\le-5$"],"설명":"$-4x+3x\\ge5$ 에서 $-x\\ge5$ 가 된다. 양변에 $-1$ 을 곱하면 부등호의 방향이 바뀐다.","확인":"-5","스킬":"G6"},{"제목":"둘째 부등식 풀기","힌트":"$2x+7>1$ 에서 $7$ 을 이항하고 $2$ 로 나누면?","식":["$2x>-6$","$x>-3$"],"설명":"$7$ 을 이항하면 $2x>-6$ 이고 양수 $2$ 로 나누므로 부등호의 방향은 그대로이다.","확인":"-3","스킬":"G6"},{"제목":"수직선에서 겹침 확인하기","힌트":"$x\\le-5$ 와 $x>-3$ 을 수직선에 그리면 겹치는 부분이 있을까?","식":["$x\\le-5$ 와 $x>-3$ 은 겹치지 않는다"],"설명":"$-5$ 이하인 수는 모두 $-3$ 보다 작으므로 두 범위를 동시에 만족하는 수가 없다. 따라서 해가 없다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p046-2-1":{"길":"괄호를 풀어 각각 풀고 음수로 나눌 때 부등호를 뒤집은 뒤 공통부분을 찾는다","단계":[{"제목":"첫 부등식 풀기","고비":true,"힌트":"$3(1-x)>6$ 의 괄호를 풀고 $x$ 의 계수로 나눌 때 부등호는 어떻게 될까?","식":["$3-3x>6$","$-3x>3$","$x<-1$"],"설명":"$3$ 을 이항하면 $-3x>3$ 이다. 음수 $-3$ 으로 나누므로 부등호의 방향이 바뀐다.","확인":"-1","스킬":"G6"},{"제목":"둘째 부등식 풀기","힌트":"$-2(x-2)>4$ 의 괄호를 풀고 상수항을 이항하면?","식":["$-2x+4>4$","$-2x>0$","$x<0$"],"설명":"$4$ 를 이항하면 $-2x>0$ 이다. 음수 $-2$ 로 나누므로 부등호의 방향이 바뀐다.","확인":"0","스킬":"G6"},{"제목":"공통부분 구하기","힌트":"$x<-1$ 과 $x<0$ 을 수직선에 그리면 겹치는 부분은?","식":["$x<-1$"],"설명":"$-1$ 보다 작은 수는 모두 $0$ 보다도 작으므로 공통부분은 더 좁은 쪽인 $x<-1$ 이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p046-2-2":{"길":"괄호를 풀 때 상수항을 두 번 빼는 점에 주의해 각각 풀고 공통부분을 찾는다","단계":[{"제목":"첫 부등식 풀기","고비":true,"힌트":"$2\\left(x-\\frac{1}{2}\\right)$ 을 전개하면 상수항은 얼마이고, 뒤의 $-1$ 과 합하면?","식":["$2x-1-1>-4$","$2x>-2$","$x>-1$"],"설명":"$2\\times\\frac{1}{2}=1$ 이므로 괄호를 풀면 $2x-1$ 이고 바깥의 $-1$ 이 더해져 상수항이 $-2$ 가 된다.","확인":"-1","스킬":"G6"},{"제목":"둘째 부등식 풀기","힌트":"$x$ 항은 좌변으로, 상수항은 우변으로 모으면?","식":["$3x+x>7+1$","$4x>8$","$x>2$"],"설명":"$-x$ 를 좌변으로 옮기면 $+x$ 가 되고 $-1$ 을 우변으로 옮기면 $+1$ 이 된다. $4$ 로 나눠도 부등호의 방향은 그대로이다.","확인":"2","스킬":"G6"},{"제목":"공통부분 구하기","힌트":"$x>-1$ 과 $x>2$ 를 수직선에 그리면 겹치는 부분은?","식":["$x>2$"],"설명":"$2$ 보다 큰 수는 모두 $-1$ 보다도 크므로 공통부분은 더 좁은 쪽인 $x>2$ 이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p046-3":{"길":"a 가 없는 부등식이 아래 끝 b 를 정하고 a 가 있는 쪽이 위 끝 7 이 된다","단계":[{"제목":"각 부등식을 $x$ 에 대해 풀기","힌트":"$2x+a\\le9$ 와 $3x-9\\ge6$ 을 각각 $x\\le$ 또는 $x\\ge$ 꼴로 쓰면?","식":["$2x+a\\le9\\ \\Rightarrow\\ x\\le\\frac{9-a}{2}$","$3x-9\\ge6\\ \\Rightarrow\\ x\\ge5$"],"설명":"첫째 식은 $a$ 를 이항한 뒤 $2$ 로 나누고, 둘째 식은 $-9$ 를 이항한 뒤 $3$ 으로 나눈다.","확인":null,"스킬":"G6"},{"제목":"해의 모양과 비교해 $b$ 정하기","고비":true,"힌트":"해가 $b\\le x\\le7$ 이고 $b<7$ 이면 아래 끝은 어느 부등식에서 나올까?","식":["공통부분 $5\\le x\\le\\frac{9-a}{2}$","$b\\le x\\le7$ 과 비교하면 $b=5$"],"설명":"해의 아래 끝은 $a$ 가 없는 부등식 $x\\ge5$ 에서 정해진다. $b<7$ 이므로 $x\\ge5$ 가 아래 끝이 되어야 하고 위 끝은 $\\frac{9-a}{2}$ 이다.","확인":"5","스킬":"G6"},{"제목":"위 끝으로 $a$ 구하기","힌트":"$\\frac{9-a}{2}$ 가 해의 위 끝 $7$ 과 같다고 놓으면?","식":["$\\frac{9-a}{2}=7$","$9-a=14$","$a=-5$"],"설명":"공통부분의 위 끝 $\\frac{9-a}{2}$ 가 문제의 해에서 $7$ 이므로 방정식을 세워 $a$ 를 구한다.","확인":"-5","스킬":"G6"}]},"tb-비상공수1-p046-4":{"길":"아래 끝이 위 끝보다 작아야 겹친다는 조건을 a 의 부등식으로 쓴다","단계":[{"제목":"각 부등식을 $x$ 에 대해 풀기","힌트":"$x+3a\\ge2$ 와 $5x-2<3x-4$ 를 각각 $x$ 에 대해 풀면?","식":["$x\\ge2-3a$","$5x-2<3x-4\\ \\Rightarrow\\ 2x<-2\\ \\Rightarrow\\ x<-1$"],"설명":"첫째 식은 $3a$ 를 이항하고, 둘째 식은 $x$ 항을 좌변으로 모아 $2$ 로 나눈다. 둘째 식의 경계는 $-1$ 이다.","확인":"-1","스킬":"G6"},{"제목":"해를 가질 조건 세우기","고비":true,"힌트":"$x\\ge2-3a$ 와 $x<-1$ 이 겹치려면 $2-3a$ 와 $-1$ 의 크기는 어때야 할까? 같아도 될까?","식":["$2-3a<-1$"],"설명":"아래 끝이 위 끝보다 작아야 겹치는 구간이 생긴다. $2-3a=-1$ 이면 $x\\ge-1$ 이고 $x<-1$ 이어서 겹치지 않으므로 등호는 들어가지 않는다.","확인":null,"스킬":"G6"},{"제목":"$a$ 의 범위 구하기","힌트":"$2-3a<-1$ 을 $a$ 에 대해 풀 때 부등호의 방향은 어떻게 될까?","식":["$-3a<-3$","$a>1$"],"설명":"$2$ 를 이항하면 $-3a<-3$ 이다. 음수 $-3$ 으로 나누므로 부등호의 방향이 바뀐다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p046-5":{"길":"A≤B<C 를 두 부등식으로 나누어 풀고 범위 안의 정수를 더한다","단계":[{"제목":"두 부등식으로 나누어 풀기","힌트":"$-x+4\\le2x-2<-5x+26$ 을 두 개의 부등식으로 나누면 각각의 해는?","식":["$-x+4\\le2x-2\\ \\Rightarrow\\ x\\ge2$","$2x-2<-5x+26\\ \\Rightarrow\\ x<4$"],"설명":"$A\\le B<C$ 는 $A\\le B$ 와 $B<C$ 를 동시에 만족하는 연립부등식이다. 각각 풀어 공통부분을 구한다.","확인":null,"스킬":"G6"},{"제목":"범위 안의 정수 고르기","고비":true,"힌트":"$2\\le x<4$ 에서 $x=4$ 는 들어갈까? 정수를 모두 쓰면?","식":["$2\\le x<4$","$x=2,\\ 3$"],"설명":"$x=2$ 는 등호가 있어 포함하고 $x=4$ 는 등호가 없어 제외한다. 범위 안의 정수는 $2$ 와 $3$ 이다.","확인":null,"스킬":"G6"},{"제목":"정수의 합 구하기","힌트":"고른 정수를 모두 더하면?","식":["$2+3=5$"],"설명":"구한 정수를 더해 합을 구한다.","확인":"5","스킬":"G6"}]},"tb-비상공수1-p046-6":{"길":"'크지 않다' 와 '크거나 같다' 의 등호를 살려 두 조건을 부등식으로 쓴다","단계":[{"제목":"두 조건을 부등식으로 쓰기","고비":true,"힌트":"'$17$ 보다 크지 않다' 는 어떤 부등호로 쓸까?","식":["$4x-3\\le17$","$6+3x\\ge3$"],"설명":"'크지 않다' 는 작거나 같다는 뜻이므로 $\\le$ 를 쓴다. '크거나 같다' 는 $\\ge$ 이다.","확인":null,"스킬":"C7"},{"제목":"각각 풀어 공통부분 구하기","힌트":"두 부등식을 각각 풀어 수직선에 그리면 겹치는 부분은?","식":["$4x\\le20\\ \\Rightarrow\\ x\\le5$","$3x\\ge-3\\ \\Rightarrow\\ x\\ge-1$","$-1\\le x\\le5$"],"설명":"(가)는 $x\\le5$, (나)는 $x\\ge-1$ 이다. 두 범위의 공통부분이 구하는 범위이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p047-1-1":{"길":"|A|>3 은 A<-3 또는 A>3 으로 바깥쪽 두 갈래로 나누어 푼다","단계":[{"제목":"절댓값 부등식을 두 갈래로 나누기","고비":true,"힌트":"$|A|>3$ 은 $A$ 가 원점에서 $3$ 보다 멀다는 뜻이다. $A$ 의 범위를 둘로 쓰면?","식":["$x+4<-3$ 또는 $x+4>3$"],"설명":"절댓값은 원점에서의 거리이므로 $|A|>3$ 은 $A<-3$ 이거나 $A>3$ 이라는 뜻이다. $A$ 자리에 $x+4$ 를 넣는다.","확인":null,"스킬":"C2"},{"제목":"각각 풀기","힌트":"두 부등식에서 $4$ 를 이항하면?","식":["$x<-7$ 또는 $x>-1$"],"설명":"$x+4<-3$ 에서 $x<-7$ 이고, $x+4>3$ 에서 $x>-1$ 이다. 두 범위는 '또는' 으로 이어진다.","확인":null,"스킬":"C2"}]},"tb-비상공수1-p047-1-2":{"길":"|A|≤7 은 -7≤A≤7 인 한 덩어리 부등식으로 바꾸어 푼다","단계":[{"제목":"절댓값 부등식을 한 덩어리로 바꾸기","고비":true,"힌트":"$|A|\\le7$ 은 $A$ 가 원점에서 $7$ 이내라는 뜻이다. $A$ 의 범위를 쓰면?","식":["$-7\\le2x+3\\le7$"],"설명":"절댓값은 원점에서의 거리이므로 $|A|\\le7$ 은 $-7\\le A\\le7$ 이라는 뜻이다. $A$ 자리에 $2x+3$ 을 넣는다.","확인":null,"스킬":"C2"},{"제목":"각 변을 정리해 $x$ 의 범위 구하기","힌트":"세 변에서 $3$ 을 빼고 $2$ 로 나누면?","식":["$-10\\le2x\\le4$","$-5\\le x\\le2$"],"설명":"세 변에서 똑같이 $3$ 을 빼고 양수 $2$ 로 나누므로 부등호의 방향은 그대로이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p047-2":{"길":"절댓값 부등식의 해를 a 로 쓰고 주어진 해와 끝점을 맞춘다","단계":[{"제목":"절댓값 부등식의 해를 a 로 나타내기","힌트":"$|A|>5$ 는 $A$ 의 범위로 어떻게 바뀔까?","식":["$3x-a<-5$ 또는 $3x-a>5$","$x<\\frac{a-5}{3}$ 또는 $x>\\frac{a+5}{3}$"],"설명":"$|A|>k$ 이면 $A<-k$ 또는 $A>k$ 이다. 각 부등식을 $x$ 에 대해 풀어 해를 $a$ 로 나타낸다.","확인":null,"스킬":"C2"},{"제목":"오른쪽 끝점을 맞추어 a 구하기","고비":true,"힌트":"$x>\\frac{8}{3}$ 과 짝이 되는 끝점은 어느 쪽일까?","식":["$\\frac{a+5}{3}=\\frac{8}{3}$","$a=3$"],"설명":"해의 오른쪽 범위 $x>\\frac{8}{3}$ 은 $x>\\frac{a+5}{3}$ 와 같으므로 두 끝점이 같다. 이로부터 $a$ 가 정해진다.","확인":"3","스킬":"C2"},{"제목":"b 를 구해 ab 계산하기","힌트":"$b$ 는 왼쪽 끝점과 같다. $a=3$ 을 넣으면?","식":["$b=\\frac{a-5}{3}=\\frac{3-5}{3}=-\\frac{2}{3}$","$ab=3\\times\\left(-\\frac{2}{3}\\right)=-2$"],"설명":"왼쪽 범위 $x<b$ 는 $x<\\frac{a-5}{3}$ 와 같으므로 $b=\\frac{a-5}{3}$ 이다. 구한 $a$, $b$ 를 곱한다.","확인":"-2","스킬":"C2"}]},"tb-비상공수1-p047-3-1":{"길":"x 의 부호로 경우를 나누어 절댓값을 벗기고 해를 합친다","단계":[{"제목":"경계를 잡아 절댓값 벗기기","힌트":"$|x|$ 는 $x$ 의 부호에 따라 어떻게 달라질까?","식":["$x<0$ 일 때 $|x|=-x$","$x\\ge0$ 일 때 $|x|=x$"],"설명":"절댓값 안의 식이 $0$ 이 되는 $x=0$ 을 경계로 구간을 나눈다. 구간마다 기호를 벗긴 식으로 푼다.","확인":null,"스킬":"C2"},{"제목":"음수 구간에서 부등식 풀기","고비":true,"힌트":"$-x\\ge4+x$ 를 $x$ 에 대해 풀면?","식":["$-x\\ge4+x$","$-2x\\ge4$","$x\\le-2$"],"설명":"$x$ 항을 한쪽으로 모은 뒤 양변을 $-2$ 로 나누면 부등호 방향이 바뀐다. $x\\le-2$ 는 $x<0$ 을 만족하므로 이 구간의 해이다.","확인":null,"스킬":"C2"},{"제목":"0 이상인 구간 확인하고 정리하기","힌트":"$x\\ge0$ 일 때 $x\\ge4+x$ 는 성립할까?","식":["$x\\ge4+x$ 에서 $0\\ge4$ (거짓)","$x\\ge0$ 에서는 해가 없다","해는 $x\\le-2$"],"설명":"$x$ 가 소거되어 거짓인 식이 남으므로 이 구간에는 해가 없다. 따라서 전체 해는 음수 구간에서 구한 해와 같다.","확인":null,"스킬":"C2"}]},"tb-비상공수1-p047-3-2":{"길":"x+1 의 부호가 바뀌는 곳을 경계로 나누어 풀고 해를 합친다","단계":[{"제목":"경계를 잡아 구간 나누기","힌트":"$|x+1|$ 의 안이 $0$ 이 되는 $x$ 는?","식":["$x+1=0$ 에서 $x=-1$","$x<-1$ 일 때 $|x+1|=-(x+1)$","$x\\ge-1$ 일 때 $|x+1|=x+1$"],"설명":"절댓값 안의 식이 $0$ 이 되는 $x$ 를 경계로 나눈다. 구간마다 부호에 맞게 절댓값을 벗긴다.","확인":"-1","스킬":"C2"},{"제목":"경계보다 작은 구간 풀기","고비":true,"힌트":"$-(x+1)+x>-3$ 의 좌변을 정리하면?","식":["$-(x+1)+x=-1$","$-1>-3$ 은 참"],"설명":"$x$ 항이 소거되고 항상 참인 식이 남는다. 이때는 구간 안의 모든 $x$ 가 해이므로 $x<-1$ 전체가 해이다.","확인":null,"스킬":"C2"},{"제목":"경계 이상인 구간 풀고 합치기","힌트":"$(x+1)+x>-3$ 의 해와 $x\\ge-1$ 의 공통부분은?","식":["$2x+1>-3$ 에서 $x>-2$","$x\\ge-1$ 과의 공통부분은 $x\\ge-1$","두 구간을 합치면 모든 실수"],"설명":"$x>-2$ 는 $x\\ge-1$ 을 모두 포함하므로 이 구간 전체가 해이다. 앞 구간과 합치면 수 전체가 된다.","확인":null,"스킬":"C2"}]},"tb-비상공수1-p047-4":{"길":"2x-1 의 부호가 바뀌는 곳에서 나누어 풀고 두 해를 이어 붙인다","단계":[{"제목":"경계를 잡아 절댓값 벗기기","힌트":"$2x-1$ 이 $0$ 이 되는 $x$ 는?","식":["$2x-1=0$ 에서 $x=\\frac{1}{2}$","$x<\\frac{1}{2}$ 일 때 $|2x-1|=-2x+1$","$x\\ge\\frac{1}{2}$ 일 때 $|2x-1|=2x-1$"],"설명":"절댓값 안의 식이 $0$ 이 되는 $x$ 를 경계로 구간을 나눈다. 구간마다 부호에 맞게 절댓값을 벗긴다.","확인":"1/2","스킬":"C2"},{"제목":"경계보다 작은 구간 풀기","고비":true,"힌트":"$-2x+1-6\\le x$ 를 $x$ 에 대해 풀면?","식":["$-2x-5\\le x$ 에서 $x\\ge-\\frac{5}{3}$","구간과 합치면 $-\\frac{5}{3}\\le x<\\frac{1}{2}$"],"설명":"$-2x+1-6=-2x-5$ 이다. $-5\\le3x$ 의 양변을 $3$ 으로 나누어 $x\\ge-\\frac{5}{3}$ 를 얻고, 구간 $x<\\frac{1}{2}$ 과 겹치는 부분을 택한다.","확인":null,"스킬":"C2"},{"제목":"경계 이상인 구간 풀기","힌트":"$2x-1-6\\le x$ 를 $x$ 에 대해 풀면?","식":["$2x-7\\le x$ 에서 $x\\le7$","구간과 합치면 $\\frac{1}{2}\\le x\\le7$"],"설명":"$x$ 항을 한쪽으로 모으면 $x\\le7$ 이다. 구간 $x\\ge\\frac{1}{2}$ 과 겹치는 부분을 택한다.","확인":null,"스킬":"C2"},{"제목":"해를 이어 붙여 3(a+b) 계산하기","힌트":"두 구간의 해를 이으면 $a$, $b$ 는? 그 합의 $3$ 배는?","식":["$-\\frac{5}{3}\\le x\\le7$ 이므로 $a=-\\frac{5}{3},\\ b=7$","$3(a+b)=3\\times\\frac{16}{3}=16$"],"설명":"두 구간은 $x=\\frac{1}{2}$ 에서 이어지므로 전체 해는 하나의 구간이다. 양 끝값이 $a$, $b$ 이다.","확인":"16","스킬":"C2"}]},"tb-비상공수1-p047-5":{"길":"두 절댓값의 경계 두 곳으로 구간을 세 개로 나누어 푼다","단계":[{"제목":"경계를 잡아 구간 세 개로 나누기","힌트":"$x+2$ 와 $x-2$ 가 각각 $0$ 이 되는 $x$ 는?","식":["경계는 $x=-2,\\ 2$","$x<-2$, $-2\\le x<2$, $x\\ge2$ 의 세 구간"],"설명":"두 절댓값의 부호가 모두 정해지는 구간으로 나눈다. 경계 두 곳이 구간을 세 개로 만든다.","확인":null,"스킬":"C2"},{"제목":"가장 왼쪽 구간 풀기","고비":true,"힌트":"$x<-2$ 에서 $|x+2|$, $|x-2|$ 는 각각 어떻게 벗겨질까?","식":["$-(x+2)-(x-2)\\le6$","$-2x\\le6$ 에서 $x\\ge-3$","구간과 합치면 $-3\\le x<-2$"],"설명":"$x<-2$ 에서는 두 절댓값 안이 모두 음수이므로 둘 다 부호를 바꾼다. 양변을 $-2$ 로 나누면 부등호 방향이 바뀐다.","확인":null,"스킬":"C2"},{"제목":"가운데 구간 풀기","힌트":"$-2\\le x<2$ 에서 $|x+2|+|x-2|$ 를 정리하면?","식":["$(x+2)-(x-2)\\le6$","$4\\le6$ 은 참","이 구간 전체 $-2\\le x<2$ 가 해"],"설명":"$x$ 가 소거되고 참인 식이 남으므로 이 구간 전체가 해이다.","확인":null,"스킬":"C2"},{"제목":"오른쪽 구간 풀고 합치기","힌트":"$x\\ge2$ 에서 부등식의 해는? 세 구간의 해를 이으면?","식":["$(x+2)+(x-2)\\le6$ 에서 $x\\le3$","구간과 합치면 $2\\le x\\le3$","세 구간을 이으면 $-3\\le x\\le3$"],"설명":"두 절댓값 안이 모두 $0$ 이상이므로 그대로 벗긴다. 세 구간의 해는 경계에서 이어져 하나의 구간이 된다.","확인":null,"스킬":"C2"}]},"tb-비상공수1-p047-6":{"길":"두 절댓값의 경계로 구간을 나누어 풀고 해 안의 정수를 센다","단계":[{"제목":"경계를 잡아 구간 세 개로 나누기","힌트":"$2x-3$ 과 $x+1$ 이 각각 $0$ 이 되는 $x$ 는?","식":["$2x-3=0$ 에서 $x=\\frac{3}{2}$, $x+1=0$ 에서 $x=-1$","$x<-1$, $-1\\le x<\\frac{3}{2}$, $x\\ge\\frac{3}{2}$ 의 세 구간"],"설명":"경계 두 곳을 작은 수부터 놓고 세 구간으로 나눈다. 구간마다 두 절댓값의 부호가 정해진다.","확인":null,"스킬":"C2"},{"제목":"가장 왼쪽 구간 풀기","고비":true,"힌트":"$x<-1$ 에서 $-|x+1|$ 은 $x+1$ 의 부호를 바꾸면 어떻게 될까?","식":["$-(2x-3)+(x+1)<3$","$4-x<3$ 에서 $x>1$","$x<-1$ 과 겹치지 않으므로 해가 없다"],"설명":"$x<-1$ 에서는 $2x-3$ 과 $x+1$ 이 모두 음수이다. 빼는 항 $-|x+1|$ 은 괄호째 부호를 바꾸어 $+(x+1)$ 이 된다.","확인":null,"스킬":"C2"},{"제목":"가운데 구간 풀기","힌트":"$-1\\le x<\\frac{3}{2}$ 에서 $|2x-3|$ 과 $|x+1|$ 은 각각 어떻게 벗겨질까?","식":["$-(2x-3)-(x+1)<3$","$2-3x<3$ 에서 $x>-\\frac{1}{3}$","구간과 합치면 $-\\frac{1}{3}<x<\\frac{3}{2}$"],"설명":"이 구간에서 $2x-3$ 은 음수이고 $x+1$ 은 $0$ 이상이다. 양변을 $-3$ 으로 나눌 때 부등호 방향이 바뀐다.","확인":null,"스킬":"C2"},{"제목":"오른쪽 구간 풀기","힌트":"$x\\ge\\frac{3}{2}$ 에서 두 절댓값을 그대로 벗기면 해는?","식":["$(2x-3)-(x+1)<3$","$x-4<3$ 에서 $x<7$","구간과 합치면 $\\frac{3}{2}\\le x<7$"],"설명":"두 식이 모두 $0$ 이상이므로 부호를 바꾸지 않고 벗긴다.","확인":null,"스킬":"C2"},{"제목":"해를 합쳐 정수 세기","힌트":"세 구간의 해를 이은 범위 안의 정수는?","식":["$-\\frac{1}{3}<x<7$","정수는 $0,\\ 1,\\ 2,\\ 3,\\ 4,\\ 5,\\ 6$","개수는 $7$"],"설명":"가운데 구간과 오른쪽 구간의 해는 경계에서 이어진다. $-\\frac{1}{3}$ 보다 큰 가장 작은 정수는 $0$ 이고 $7$ 보다 작은 가장 큰 정수는 $6$ 이다.","확인":"7","스킬":"C2"}]},"tb-비상공수1-p048-1-1":{"길":"한쪽으로 모아 인수분해한 뒤 그래프가 x 축 위인 구간을 읽는다","단계":[{"제목":"전개하여 한쪽으로 모으기","고비":true,"힌트":"모든 항을 좌변으로 옮겨 정리하면?","식":["$2x^{2}-5x-3>2x-6$","$2x^{2}-7x+3>0$","$(2x-1)(x-3)>0$"],"설명":"$(2x+1)(x-3)=2x^{2}-5x-3$ 이다. 우변을 이항하면 $2x^{2}-7x+3>0$ 이고 두 일차식의 곱으로 인수분해된다.","확인":null,"스킬":"G6"},{"제목":"부등호에 맞는 구간 읽기","힌트":"$y=(2x-1)(x-3)$ 은 아래로 볼록하다. $y>0$ 인 곳은 두 근의 어느 쪽일까?","식":["두 근은 $x=\\frac{1}{2},\\ 3$","$x<\\frac{1}{2}$ 또는 $x>3$"],"설명":"이차항 계수가 양수이므로 그래프는 아래로 볼록하다. $>0$ 이면 두 근의 바깥쪽이 해이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p048-1-2":{"길":"부호를 바꾸어 완전제곱식으로 만들고 항상 양수인지 확인한다","단계":[{"제목":"양변에 음수를 곱해 계수 바꾸기","힌트":"양변에 $-1$ 을 곱하면 부등호는 어떻게 될까?","식":["$9x^{2}-12x+7\\ge0$"],"설명":"음수를 곱하면 부등호 방향이 바뀐다. 이차항 계수를 양수로 만들어 두면 이후 판단이 쉽다.","확인":null,"스킬":"G6"},{"제목":"완전제곱식으로 고치기","고비":true,"힌트":"$9x^{2}-12x$ 를 $(3x-2)^{2}$ 꼴로 묶고 남는 상수는?","식":["$9x^{2}-12x+7=(3x-2)^{2}+3$","$=9\\left(x-\\frac{2}{3}\\right)^{2}+3$"],"설명":"$(3x-2)^{2}=9x^{2}-12x+4$ 이므로 $7=4+3$ 으로 나누어 쓴다. 완전제곱식과 상수의 합이 된다.","확인":null,"스킬":"A6"},{"제목":"항상 성립함을 확인하기","힌트":"$(3x-2)^{2}+3$ 의 최솟값은 얼마일까?","식":["$(3x-2)^{2}\\ge0$ 이므로 $(3x-2)^{2}+3\\ge3>0$","$9x^{2}-12x+7\\ge0$ 은 모든 실수 $x$ 에서 성립"],"설명":"제곱식은 항상 $0$ 이상이므로 전체 식은 항상 양수이다. 따라서 해는 모든 실수이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p048-2":{"길":"좌변을 인수분해하여 두 근 사이를 해로 읽고 양 끝을 더한다","단계":[{"제목":"인수분해하여 해 구하기","고비":true,"힌트":"$2x^{2}+5x-7$ 을 두 일차식의 곱으로 나타내면?","식":["$2x^{2}+5x-7=(2x+7)(x-1)$","$(2x+7)(x-1)<0$ 에서 $-\\frac{7}{2}<x<1$"],"설명":"아래로 볼록한 이차식이 $<0$ 이면 두 근 사이가 해이다. 두 근은 $-\\frac{7}{2}$ 와 $1$ 이다.","확인":null,"스킬":"G6"},{"제목":"양 끝을 더하기","힌트":"해의 양 끝이 $\\alpha$, $\\beta$ 이다. 합은?","식":["$\\alpha=-\\frac{7}{2},\\ \\beta=1$","$\\alpha+\\beta=-\\frac{7}{2}+1=-\\frac{5}{2}$"],"설명":"해 $\\alpha<x<\\beta$ 와 구한 해를 비교하면 양 끝값이 $\\alpha$, $\\beta$ 이다.","확인":"-5/2","스킬":"G6"}]},"tb-비상공수1-p048-3":{"길":"항상 성립하도록 계수를 양수로 맞추고 판별식 조건을 세운다","단계":[{"제목":"x² 의 계수를 양수로 바꾸기","힌트":"양변에 $-1$ 을 곱하여 $x^{2}$ 의 계수를 양수로 만들면?","식":["$x^{2}-2(k-2)x-k+4\\ge0$"],"설명":"음수를 곱하면 부등호 방향이 바뀐다. 해가 모든 실수라는 것은 이 식이 모든 $x$ 에서 성립한다는 뜻이다.","확인":null,"스킬":"C1"},{"제목":"판별식 조건 세우기","고비":true,"힌트":"아래로 볼록한 이차식이 항상 $\\ge0$ 이려면 $\\frac{D}{4}$ 의 부호 조건은?","식":["$\\frac{D}{4}=(k-2)^{2}-(-k+4)=k^{2}-3k$","$\\frac{D}{4}\\le0$"],"설명":"그래프가 $x$ 축에 접하거나 $x$ 축 위에 있으려면 판별식이 $0$ 이하여야 한다. $x$ 의 계수가 $-2(k-2)$ 이므로 $\\frac{D}{4}$ 에는 $(k-2)^{2}$ 을 쓴다.","확인":null,"스킬":"C1"},{"제목":"k 의 범위 구하기","힌트":"$k^{2}-3k\\le0$ 을 인수분해하여 풀면?","식":["$k(k-3)\\le0$","$0\\le k\\le3$"],"설명":"아래로 볼록한 이차식이 $\\le0$ 이면 두 근 사이가 해이다.","확인":null,"스킬":"C1"}]},"tb-비상공수1-p048-4":{"길":"해가 없다는 조건을 항상 0 이상으로 바꾸어 판별식을 쓴다","단계":[{"제목":"해가 없다는 조건 바꾸기","고비":true,"힌트":"$<0$ 인 $x$ 가 하나도 없다면 모든 $x$ 에서 부등호는 어떻게 될까?","식":["모든 실수 $x$ 에 대하여 $x^{2}+4kx-4k+8\\ge0$"],"설명":"$<0$ 을 만족하는 $x$ 가 없다는 것은 모든 $x$ 에서 $\\ge0$ 이라는 뜻이다.","확인":null,"스킬":"C1"},{"제목":"판별식 조건 세우기","힌트":"아래로 볼록한 이차식이 항상 $\\ge0$ 이려면 $\\frac{D}{4}$ 는?","식":["$\\frac{D}{4}=(2k)^{2}-(-4k+8)=4k^{2}+4k-8$","$4k^{2}+4k-8\\le0$"],"설명":"그래프가 $x$ 축에 접하거나 위에 있으려면 판별식이 $0$ 이하이다.","확인":null,"스킬":"C1"},{"제목":"k 의 범위 구하기","힌트":"$k^{2}+k-2\\le0$ 을 인수분해하면?","식":["$k^{2}+k-2=(k+2)(k-1)\\le0$","$-2\\le k\\le1$"],"설명":"양변을 $4$ 로 나누어 $k^{2}+k-2\\le0$ 으로 쓴다. 아래로 볼록한 이차식이 $\\le0$ 이면 두 근 사이가 해이다.","확인":null,"스킬":"C1"}]},"tb-비상공수1-p048-5-1":{"길":"각 부등식을 따로 풀고 두 해의 공통부분을 읽는다","단계":[{"제목":"두 부등식을 각각 풀기","고비":true,"힌트":"$x^{2}-6x<0$ 과 $x^{2}-2x-3>0$ 을 각각 인수분해하면?","식":["$x(x-6)<0$ 에서 $0<x<6$","$(x+1)(x-3)>0$ 에서 $x<-1$ 또는 $x>3$"],"설명":"둘째 식은 우변 $3$ 을 이항하여 $x^{2}-2x-3>0$ 으로 정리한 것이다. 아래로 볼록한 그래프에서 $<0$ 은 두 근 사이, $>0$ 은 바깥쪽이 해이다.","확인":null,"스킬":"G6"},{"제목":"공통부분 찾기","힌트":"수직선에 두 해를 그리면 겹치는 곳은?","식":["$0<x<6$ 과 ($x<-1$ 또는 $x>3$) 의 공통부분은 $3<x<6$"],"설명":"연립부등식의 해는 두 해가 겹치는 부분이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p048-5-2":{"길":"각 부등식을 따로 풀고 두 해의 공통부분을 읽는다","단계":[{"제목":"두 부등식을 각각 풀기","고비":true,"힌트":"상수항을 좌변으로 옮겨 각각 인수분해하면?","식":["$x^{2}-4x-5<0$ 에서 $(x+1)(x-5)<0$, 즉 $-1<x<5$","$x^{2}-5x-14\\le0$ 에서 $(x+2)(x-7)\\le0$, 즉 $-2\\le x\\le7$"],"설명":"두 식 모두 아래로 볼록하므로 두 근 사이가 해이다. 등호가 없는 식은 끝점을 제외하고 등호가 있는 식은 끝점을 포함한다.","확인":null,"스킬":"G6"},{"제목":"공통부분 찾기","힌트":"수직선에 두 해를 그리면 겹치는 곳은?","식":["$-1<x<5$ 와 $-2\\le x\\le7$ 의 공통부분은 $-1<x<5$"],"설명":"$-1<x<5$ 는 $-2\\le x\\le7$ 안에 모두 들어 있으므로 공통부분은 $-1<x<5$ 이다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p048-6":{"길":"삼각형이 되는 조건과 둔각이 되는 조건을 세워 공통범위를 구한다","단계":[{"제목":"길이 조건과 가장 긴 변 정하기","힌트":"변의 길이가 양수이려면 $x$ 의 조건은? 가장 긴 변은 어느 것일까?","식":["$4x-1>0$ 에서 $x>\\frac{1}{4}$","가장 긴 변은 $4x+1$"],"설명":"변의 길이는 모두 양수여야 한다. $x>\\frac{1}{4}$ 이면 $4x+1>4x-1$ 이고 $4x+1>2x$ 이므로 $4x+1$ 이 가장 길다.","확인":null,"스킬":"C7"},{"제목":"삼각형이 되는 조건 세우기","힌트":"가장 긴 변은 나머지 두 변의 합보다 작아야 한다. 부등식으로 쓰면?","식":["$4x+1<(4x-1)+2x$","$x>1$"],"설명":"삼각형이 되려면 (가장 긴 변) < (나머지 두 변의 길이의 합) 이어야 한다. 정리하면 $2<2x$ 이다.","확인":null,"스킬":"C7"},{"제목":"둔각이 되는 조건 세우기","고비":true,"힌트":"가장 긴 변의 제곱이 나머지 두 변의 제곱의 합보다 크면 어떤 각이 둔각일까? 식으로 쓰면?","식":["$(4x+1)^{2}>(4x-1)^{2}+(2x)^{2}$","$16x>4x^{2}$ 에서 $x(x-4)<0$","$0<x<4$"],"설명":"가장 긴 변의 제곱이 나머지 두 변의 제곱의 합보다 크면 가장 큰 각이 둔각이다. $(4x+1)^{2}-(4x-1)^{2}=16x$ 이므로 정리하면 이차부등식이 된다.","확인":null,"스킬":"G6"},{"제목":"두 조건의 공통범위 구하기","힌트":"$x>1$ 과 $0<x<4$ 를 동시에 만족하는 범위는?","식":["$x>1$ 과 $0<x<4$ 의 공통부분은 $1<x<4$"],"설명":"삼각형이 되는 조건과 둔각이 되는 조건을 모두 만족해야 하므로 공통부분을 택한다.","확인":null,"스킬":"G6"}]},"tb-비상공수1-p049-1-1":{"길":"3 의 배수와 7 의 배수를 각각 세고 겹치는 수가 있는지 확인한다","단계":[{"제목":"배수의 개수를 각각 세기","힌트":"$20$ 이하의 $3$ 의 배수와 $7$ 의 배수는 각각 몇 개일까?","식":["$3$ 의 배수: $3,\\ 6,\\ 9,\\ 12,\\ 15,\\ 18$ 의 $6$ 개","$7$ 의 배수: $7,\\ 14$ 의 $2$ 개"],"설명":"각 배수를 빠짐없이 나열하여 센다.","확인":null,"스킬":"P4"},{"제목":"겹침을 확인하고 더하기","고비":true,"힌트":"두 경우에 동시에 속하는 수가 있는지 확인하면?","식":["$3$ 과 $7$ 의 공배수 $21$ 은 $20$ 보다 크므로 겹치는 수가 없다","$6+2=8$"],"설명":"동시에 일어나지 않는 두 경우이므로 합의 법칙으로 더한다.","확인":"8","스킬":"P4"}]},"tb-비상공수1-p049-1-2":{"길":"짝수와 15 의 약수를 각각 세고 겹치는 수가 있는지 확인한다","단계":[{"제목":"짝수와 약수의 개수를 각각 세기","힌트":"$20$ 이하의 짝수와 $15$ 의 약수는 각각 몇 개일까?","식":["짝수는 $2,\\ 4,\\ \\cdots,\\ 20$ 의 $10$ 개","$15$ 의 약수는 $1,\\ 3,\\ 5,\\ 15$ 의 $4$ 개"],"설명":"각 경우의 수를 빠짐없이 나열하여 센다.","확인":null,"스킬":"P4"},{"제목":"겹침을 확인하고 더하기","고비":true,"힌트":"$15$ 의 약수 중 짝수가 있는지 확인하면?","식":["$15$ 의 약수는 모두 홀수이므로 짝수와 겹치지 않는다","$10+4=14$"],"설명":"동시에 일어나지 않는 두 경우이므로 합의 법칙으로 더한다.","확인":"14","스킬":"P4"}]},"tb-비상공수1-p049-2":{"길":"x 가 최소일 때를 기준으로 y 를 정하고 가능한 x 를 나열한다","단계":[{"제목":"y 가 될 수 있는 값 좁히기","고비":true,"힌트":"$x$ 가 자연수이면 $4x$ 의 최솟값은 얼마이고, 그때 $5y$ 는 얼마 이하일까?","식":["$x\\ge1$ 이므로 $5y\\le17-4=13$","$y=1,\\ 2$"],"설명":"$x$ 의 최솟값이 $1$ 이므로 $5y$ 는 $13$ 이하여야 한다. 따라서 $y$ 가 될 수 있는 자연수는 두 개뿐이다.","확인":null,"스킬":"P4"},{"제목":"y 의 값마다 x 나열하기","힌트":"각 $y$ 에 대하여 $4x\\le17-5y$ 를 만족하는 자연수 $x$ 는?","식":["$y=1$: $4x\\le12$ 에서 $x=1,\\ 2,\\ 3$","$y=2$: $4x\\le7$ 에서 $x=1$"],"설명":"$y$ 를 고정하면 $x$ 에 대한 일차부등식이 된다. 만족하는 자연수 $x$ 를 모두 적는다.","확인":null,"스킬":"P4"},{"제목":"순서쌍의 개수 세기","힌트":"찾은 순서쌍은 모두 몇 개일까?","식":["$(1,\\ 1),\\ (2,\\ 1),\\ (3,\\ 1),\\ (1,\\ 2)$","$3+1=4$"],"설명":"$y$ 의 값마다 센 개수를 더한다.","확인":"4","스킬":"P4"}]},"tb-비상공수1-p049-3":{"길":"두 분야에서 동시에 한 개씩 택하므로 곱의 법칙을 쓴다","단계":[{"제목":"분야별 선택의 수 세기","힌트":"각 분야에서 한 개를 택하는 방법은 각각 몇 가지일까?","식":["인문 사회 프로그램: $3$ 가지","자연 과학 프로그램: $2$ 가지"],"설명":"분야마다 한 개를 택하므로 프로그램의 수가 곧 방법의 수이다.","확인":null,"스킬":"P4"},{"제목":"곱의 법칙 적용하기","고비":true,"힌트":"두 분야에서 각각 택하는 일이 모두 일어난다. 방법의 수는?","식":["$3\\times2=6$"],"설명":"한 분야의 선택마다 다른 분야의 선택이 이어지므로 두 수를 곱한다.","확인":"6","스킬":"P4"}]},"tb-비상공수1-p049-4":{"길":"A 에서 출발하는 지나는 지점의 순서를 모두 쓰고 구간별 길의 수를 곱해 더한다","단계":[{"제목":"그림에서 길의 수 읽기","힌트":"그림에서 두 지점 사이의 길이 두 개 이상인 곳은?","식":["$\\mathrm{B}$ 와 $\\mathrm{E}$ 사이의 길은 $2$ 개","나머지 연결은 길이 $1$ 개씩: $\\mathrm{AB},\\ \\mathrm{AC},\\ \\mathrm{AD},\\ \\mathrm{AE},\\ \\mathrm{CD},\\ \\mathrm{BD},\\ \\mathrm{DE}$"],"설명":"$\\mathrm{B}$ 와 $\\mathrm{E}$ 는 직선 길과 곡선 길이 모두 있다. $\\mathrm{A}$ 와 $\\mathrm{E}$ 는 위쪽 곡선으로 바로 이어진다.","확인":null,"스킬":"P4"},{"제목":"지나는 지점의 순서로 경우 나누기","고비":true,"힌트":"같은 지점을 두 번 지나지 않고 $\\mathrm{A}$ 에서 $\\mathrm{E}$ 에 닿는 지점의 순서를 모두 쓰면?","식":["$\\mathrm{A\\to E}$, $\\mathrm{A\\to B\\to E}$, $\\mathrm{A\\to D\\to E}$","$\\mathrm{A\\to B\\to D\\to E}$, $\\mathrm{A\\to C\\to D\\to E}$","$\\mathrm{A\\to D\\to B\\to E}$, $\\mathrm{A\\to C\\to D\\to B\\to E}$"],"설명":"$\\mathrm{A}$ 에서 처음 가는 곳을 기준으로 나누어 빠짐없이 쓴다. $\\mathrm{C}$ 에서는 $\\mathrm{D}$ 로만 갈 수 있고, 이미 지난 지점으로 되돌아가는 길은 제외한다.","확인":null,"스킬":"P4"},{"제목":"순서마다 길의 수 구하기","힌트":"각 순서에서 구간마다 길의 수를 곱하면?","식":["$\\mathrm{A\\to E}$: $1$, $\\mathrm{A\\to B\\to E}$: $1\\times2=2$, $\\mathrm{A\\to D\\to E}$: $1$","$\\mathrm{A\\to B\\to D\\to E}$: $1$, $\\mathrm{A\\to C\\to D\\to E}$: $1$","$\\mathrm{A\\to D\\to B\\to E}$: $2$, $\\mathrm{A\\to C\\to D\\to B\\to E}$: $2$"],"설명":"$\\mathrm{B}$ 에서 $\\mathrm{E}$ 로 가는 구간이 들어 있는 순서는 그 구간의 길이 $2$ 개이므로 $2$ 를 곱한다.","확인":null,"스킬":"P4"},{"제목":"합의 법칙으로 더하기","힌트":"일곱 가지 순서의 길의 수를 모두 더하면?","식":["$1+2+1+1+1+2+2=10$"],"설명":"순서가 다르면 서로 다른 방법이므로 합의 법칙으로 더한다.","확인":"10","스킬":"P4"}]},"tb-비상공수1-p049-5":{"길":"공약수는 최대공약수의 약수이므로 최대공약수를 구해 약수의 개수를 센다","단계":[{"제목":"소인수분해하여 최대공약수 구하기","고비":true,"힌트":"$280$ 과 $720$ 을 각각 소인수분해하면 공통인 소인수와 지수는?","식":["$280=2^{3}\\times5\\times7$","$720=2^{4}\\times3^{2}\\times5$","최대공약수 $=2^{3}\\times5=40$"],"설명":"공통인 소인수마다 작은 쪽 지수를 택한다. $2$ 는 지수 $3$, $5$ 는 지수 $1$ 이다.","확인":"40","스킬":"N2"},{"제목":"최대공약수의 약수 개수 세기","힌트":"$2^{3}\\times5$ 의 약수의 개수는 지수에 $1$ 을 더해 곱하면?","식":["$(3+1)\\times(1+1)=8$"],"설명":"공약수는 최대공약수의 약수와 같다. $p^{a}q^{b}$ 의 약수의 개수는 $(a+1)(b+1)$ 이다.","확인":"8","스킬":"N1"}]},"tb-비상공수1-p049-6":{"길":"동전마다 쓸 수 있는 개수를 세어 곱하고 0 원인 경우를 뺀다","단계":[{"제목":"동전 종류별 선택의 수 세기","고비":true,"힌트":"각 동전을 $0$ 개부터 가진 개수까지 쓸 수 있다. 종류별 가짓수는?","식":["$10$ 원: $0\\sim3$ 개로 $4$ 가지","$100$ 원: $0\\sim4$ 개로 $5$ 가지","$500$ 원: $0\\sim2$ 개로 $3$ 가지"],"설명":"$0$ 개를 쓰는 경우도 한 가지로 센다. 세 동전의 사용 개수는 서로 영향을 주지 않는다.","확인":null,"스킬":"P4"},{"제목":"금액이 겹치지 않음을 확인하고 곱하기","힌트":"서로 다른 조합이 같은 금액이 될 수 있을까?","식":["$10\\times3=30<100,\\ 100\\times4=400<500$","조합이 다르면 금액도 다르다","$4\\times5\\times3=60$"],"설명":"$10$ 원짜리의 합은 $100$ 원 미만이고 $100$ 원짜리의 합은 $500$ 원 미만이다. 따라서 조합의 수가 곧 지불 방법의 수이다.","확인":"60","스킬":"P4"},{"제목":"0 원인 경우 빼기","힌트":"모두 쓰지 않는 경우도 곱에 들어 있다. 이를 어떻게 처리할까?","식":["$60-1=59$"],"설명":"세 동전을 모두 $0$ 개 쓰는 경우는 $0$ 원을 내는 것이므로 한 가지를 뺀다.","확인":"59","스킬":"P4"}]},"tb-비상공수1-p050-1-1":{"길":"순열을 곱의 꼴로 쓰고 연속한 세 자연수의 곱을 찾는다","단계":[{"제목":"순열을 곱의 꼴로 나타내기","힌트":"${}_{n}\\mathrm{P}_{3}$ 은 $n$ 부터 몇 개를 곱한 것일까?","식":["${}_{n}\\mathrm{P}_{3}=n(n-1)(n-2)$","$n(n-1)(n-2)=60$"],"설명":"${}_{n}\\mathrm{P}_{r}$ 은 $n$ 부터 $1$ 씩 줄여 $r$ 개를 곱한 값이다.","확인":null,"스킬":"P4"},{"제목":"곱이 같은 연속한 세 수 찾기","고비":true,"힌트":"$60$ 을 연속한 세 자연수의 곱으로 나타내면?","식":["$60=5\\times4\\times3$","$n=5$"],"설명":"$n(n-1)(n-2)$ 는 연속한 세 자연수의 곱이고 $n$ 이 가장 큰 수이다. $60$ 을 이런 곱으로 쓰면 가장 큰 수가 $n$ 이다.","확인":"5","스킬":"P4"}]},"tb-비상공수1-p050-1-2":{"길":"순열을 곱으로 풀어 쓰고 공통인수로 양변을 나눈다","단계":[{"제목":"양변을 곱의 꼴로 쓰기","힌트":"${}_{2n}\\mathrm{P}_{3}$ 과 ${}_{n}\\mathrm{P}_{2}$ 를 각각 곱으로 쓰면?","식":["${}_{2n}\\mathrm{P}_{3}=2n(2n-1)(2n-2)$","${}_{n}\\mathrm{P}_{2}=n(n-1)$","$2n(2n-1)(2n-2)=100n(n-1)$"],"설명":"${}_{2n}\\mathrm{P}_{3}$ 은 $2n$ 부터 $1$ 씩 줄여 세 개를 곱한다. 순열이 정의되려면 $2n\\ge3$ 이므로 $n\\ge2$ 이다.","확인":null,"스킬":"P4"},{"제목":"공통인수로 나누기","고비":true,"힌트":"$2n-2=2(n-1)$ 임을 이용하면 양변에 공통으로 들어 있는 식은?","식":["$4n(n-1)(2n-1)=100n(n-1)$","$n\\ge2$ 이므로 양변을 $4n(n-1)$ 로 나누면 $2n-1=25$"],"설명":"$n\\ge2$ 이므로 $n$ 과 $n-1$ 은 $0$ 이 아니어서 나눌 수 있다.","확인":"25","스킬":"P4"},{"제목":"n 의 값 구하기","힌트":"$2n-1=25$ 를 풀면?","식":["$2n=26$","$n=13$"],"설명":"일차방정식을 풀어 $n$ 을 구한다. $n\\ge2$ 를 만족한다.","확인":"13","스킬":"P4"}]},"tb-비상공수1-p050-2":{"길":"일의 자리 숫자로 경우를 나누고 맨 앞에 0 이 오지 않게 센다","단계":[{"제목":"일의 자리로 경우 나누기","힌트":"짝수가 되려면 일의 자리에 올 수 있는 수는?","식":["일의 자리는 $0,\\ 2,\\ 4$ 중 하나","일의 자리가 $0$ 인 경우와 $2,\\ 4$ 인 경우로 나눈다"],"설명":"일의 자리가 $0$ 이면 천의 자리에 $0$ 이 오는 문제가 없다. $2$, $4$ 이면 천의 자리에 $0$ 이 올 수 없으므로 경우를 나눈다.","확인":null,"스킬":"P4"},{"제목":"일의 자리가 0 인 경우 세기","힌트":"나머지 세 자리에 $1,\\ 2,\\ 3,\\ 4,\\ 5$ 중 서로 다른 $3$ 개를 순서대로 놓는 경우의 수는?","식":["${}_{5}\\mathrm{P}_{3}=5\\times4\\times3=60$"],"설명":"일의 자리에 $0$ 을 쓰면 남은 수 $5$ 개 중에서 세 자리를 채운다.","확인":"60","스킬":"P4"},{"제목":"일의 자리가 2 또는 4 인 경우 세기","고비":true,"힌트":"천의 자리에 올 수 있는 수는 몇 개일까? 그다음 두 자리는?","식":["천의 자리: $0$ 과 일의 자리 수를 뺀 $4$ 가지","나머지 두 자리: ${}_{4}\\mathrm{P}_{2}=12$","일의 자리 $2$ 인 경우 $4\\times12=48$, $4$ 인 경우도 $48$"],"설명":"천의 자리에는 $0$ 이 올 수 없고 일의 자리 수도 쓸 수 없다. 천의 자리를 먼저 정하면 남은 수 $4$ 개 중에서 두 자리를 채운다.","확인":"48","스킬":"P4"},{"제목":"경우별 개수 더하기","힌트":"세 경우의 수를 모두 더하면?","식":["$60+48+48=156$"],"설명":"일의 자리가 다르면 서로 다른 수이므로 합의 법칙으로 더한다.","확인":"156","스킬":"P4"}]},"tb-비상공수1-p050-3-1":{"길":"양 끝을 먼저 정하고 이웃하는 여학생을 한 묶음으로 보아 배열한다","단계":[{"제목":"양 끝에 설 남학생 정하기","힌트":"남학생 $4$ 명 중 양 끝에 서는 $2$ 명을 순서까지 정하는 경우의 수는?","식":["${}_{4}\\mathrm{P}_{2}=4\\times3=12$"],"설명":"왼쪽 끝과 오른쪽 끝은 서로 다른 자리이므로 순열로 센다.","확인":"12","스킬":"P3"},{"제목":"묶음과 남은 남학생 배열하기","고비":true,"힌트":"여학생 $3$ 명을 한 묶음으로 보면 가운데 놓이는 대상은 모두 몇 개일까?","식":["가운데: 남은 남학생 $2$ 명과 여학생 묶음 $1$ 개의 $3$ 개","$3!=6$"],"설명":"이웃하는 여학생 $3$ 명을 하나로 묶으면 가운데 자리에 놓이는 대상은 남은 남학생 $2$ 명과 묶음 하나이다.","확인":"6","스킬":"P3"},{"제목":"묶음 안 배열과 곱하기","힌트":"묶음 안에서 여학생 $3$ 명의 순서까지 고려해 모두 곱하면?","식":["묶음 안 배열: $3!=6$","$12\\times6\\times6=432$"],"설명":"양 끝 선택, 가운데 배열, 묶음 안 배열이 모두 일어나므로 곱의 법칙을 쓴다.","확인":"432","스킬":"P3"}]},"tb-비상공수1-p050-3-2":{"길":"여학생을 먼저 세우고 남학생이 설 수 있는 자리를 정한다","단계":[{"제목":"여학생 먼저 세우기","힌트":"여학생 $3$ 명을 먼저 일렬로 세우는 경우의 수는?","식":["$3!=6$"],"설명":"여학생을 먼저 세우면 남학생이 들어갈 수 있는 자리는 사이사이와 양 끝이다.","확인":"6","스킬":"P3"},{"제목":"남학생이 설 자리 정하고 배열하기","고비":true,"힌트":"여학생 사이와 양 끝에 생기는 자리는 몇 곳일까? 남학생 $4$ 명은 몇 곳에 서야 할까?","식":["자리는 양 끝 $2$ 곳과 사이 $2$ 곳으로 $4$ 곳","남학생 $4$ 명이 한 곳에 한 명씩 선다","남학생의 배열: $4!=24$"],"설명":"한 곳에 남학생 둘이 서면 둘이 이웃하게 된다. 이웃하지 않으려면 네 곳에 한 명씩 서야 하고 남학생의 순서는 달라질 수 있다.","확인":"24","스킬":"P3"},{"제목":"곱의 법칙으로 구하기","힌트":"여학생 배열과 남학생 배열을 곱하면?","식":["$6\\times24=144$"],"설명":"여학생을 세우는 일과 남학생을 세우는 일이 모두 일어나므로 곱의 법칙을 쓴다.","확인":"144","스킬":"P3"}]},"tb-비상공수1-p050-5":{"길":"전체 경우에서 양 끝이 모두 모음인 경우를 뺀다","단계":[{"제목":"전체 경우의 수 구하기","힌트":"여섯 문자를 모두 일렬로 나열하는 경우의 수는?","식":["$6!=720$"],"설명":"여섯 문자가 모두 서로 다르므로 $6$ 개를 일렬로 나열하는 순열이다.","확인":"720","스킬":"P2"},{"제목":"여사건의 경우의 수 세기","고비":true,"힌트":"적어도 한쪽 끝에 자음이 오지 않는 경우는 양 끝이 어떨 때일까? 그 경우의 수는?","식":["양 끝이 모두 모음: 모음 $\\mathrm{o,\\ i,\\ e}$ 중 $2$ 개를 순서대로 놓아 ${}_{3}\\mathrm{P}_{2}=6$","나머지 네 자리: $4!=24$","$6\\times24=144$"],"설명":"적어도 한쪽 끝에 자음이 오는 경우의 여사건은 양 끝이 모두 모음인 경우이다. 양 끝을 먼저 채우고 나머지 네 문자를 배열한다.","확인":"144","스킬":"P2"},{"제목":"전체에서 빼기","힌트":"전체에서 여사건의 경우의 수를 빼면?","식":["$720-144=576$"],"설명":"전체 경우의 수에서 조건에 맞지 않는 경우의 수를 뺀다.","확인":"576","스킬":"P2"}]},"tb-비상공수1-p050-6":{"길":"백의 자리로 경우를 나누고 220 보다 작은 수를 빠짐없이 센다","단계":[{"제목":"백의 자리가 1 인 경우 세기","힌트":"백의 자리가 $1$ 이면 나머지 두 자리에 올 수 있는 수와 경우의 수는?","식":["나머지 두 자리는 $0,\\ 2,\\ 3,\\ 4$ 에서 서로 다른 $2$ 개","${}_{4}\\mathrm{P}_{2}=12$"],"설명":"백의 자리가 $1$ 이면 십의 자리와 일의 자리에 무엇이 와도 $220$ 보다 작다. 백의 자리가 $3$ 이상이면 $220$ 보다 크므로 제외한다.","확인":"12","스킬":"P4"},{"제목":"백의 자리가 2 인 경우 세기","고비":true,"힌트":"백의 자리가 $2$ 일 때 $220$ 보다 작으려면 십의 자리는 어떤 수여야 할까?","식":["십의 자리 $0$: $20\\square$ 의 일의 자리는 $1,\\ 3,\\ 4$ 로 $3$ 개","십의 자리 $1$: $21\\square$ 의 일의 자리는 $0,\\ 3,\\ 4$ 로 $3$ 개","$3+3=6$"],"설명":"십의 자리가 $2$ 이상이면 $220$ 이상이다. 십의 자리에 $2$ 는 백의 자리와 겹쳐 쓸 수 없으므로 $0$, $1$ 만 가능하다.","확인":"6","스킬":"P4"},{"제목":"경우별 개수 더하기","힌트":"두 경우의 수를 더하면?","식":["$12+6=18$"],"설명":"백의 자리가 다르면 서로 다른 수이므로 합의 법칙으로 더한다.","확인":"18","스킬":"P4"}]},"tb-비상공수1-p051-1-1":{"길":"조합을 곱의 꼴로 풀어 쓰고 연속한 세 자연수의 곱을 찾는다","단계":[{"제목":"조합을 식으로 풀어 쓰기","힌트":"${}_{n}\\mathrm{C}_{3}=\\frac{n(n-1)(n-2)}{3!}$ 임을 이용하면 $n(n-1)(n-2)$ 의 값은?","식":["$\\frac{n(n-1)(n-2)}{6}=20$","$n(n-1)(n-2)=120$"],"설명":"${}_{n}\\mathrm{C}_{3}$ 은 ${}_{n}\\mathrm{P}_{3}$ 을 $3!$ 로 나눈 값이다. 양변에 $6$ 을 곱한다.","확인":"120","스킬":"P4"},{"제목":"곱이 같은 연속한 세 수 찾기","고비":true,"힌트":"$120$ 을 연속한 세 자연수의 곱으로 나타내면?","식":["$120=6\\times5\\times4$","$n=6$"],"설명":"$n(n-1)(n-2)$ 는 연속한 세 자연수의 곱이고 $n$ 이 가장 큰 수이다.","확인":"6","스킬":"P4"}]},"tb-비상공수1-p051-1-2":{"길":"조합의 대칭 성질로 같은 값이 되는 다른 r 을 찾는다","단계":[{"제목":"조합의 대칭 성질 적용하기","고비":true,"힌트":"${}_{n}\\mathrm{C}_{r}={}_{n}\\mathrm{C}_{n-r}$ 를 ${}_{9}\\mathrm{C}_{4}$ 에 적용하면?","식":["${}_{9}\\mathrm{C}_{4}={}_{9}\\mathrm{C}_{9-4}={}_{9}\\mathrm{C}_{5}$"],"설명":"$9$ 개 중 $4$ 개를 뽑는 것은 뽑지 않을 $5$ 개를 정하는 것과 같다. 따라서 두 조합의 값이 같다.","확인":null,"스킬":"P4"},{"제목":"r 의 값 정하기","힌트":"$r\\ne4$ 이므로 ${}_{9}\\mathrm{C}_{r}={}_{9}\\mathrm{C}_{5}$ 에서 $r$ 은?","식":["$r\\ne4$ 이므로 $r=5$"],"설명":"${}_{9}\\mathrm{C}_{r}$ 의 값이 같아지는 $r$ 은 $4$ 와 $5$ 이다. 조건 $r\\ne4$ 에 맞는 값을 택한다.","확인":"5","스킬":"P4"}]},"tb-비상공수1-p051-2":{"길":"1 학년만 뽑는 경우와 2 학년만 뽑는 경우로 나누어 더한다","단계":[{"제목":"학년별 경우의 수 구하기","고비":true,"힌트":"세 명의 학년이 같으려면 어떤 경우가 있을까? 각 경우의 수는?","식":["$1$ 학년 $6$ 명 중 $3$ 명: ${}_{6}\\mathrm{C}_{3}=20$","$2$ 학년 $4$ 명 중 $3$ 명: ${}_{4}\\mathrm{C}_{3}=4$"],"설명":"뽑는 순서는 상관없으므로 조합이다. 학년이 모두 같으면 $1$ 학년만 뽑거나 $2$ 학년만 뽑는다.","확인":null,"스킬":"P4"},{"제목":"합의 법칙으로 더하기","힌트":"두 경우의 수를 더하면?","식":["$20+4=24$"],"설명":"두 경우는 동시에 일어나지 않으므로 합의 법칙으로 더한다.","확인":"24","스킬":"P4"}]},"tb-비상공수1-p051-3":{"길":"빵과 음료에서 각각 조합의 수를 구해 곱한다","단계":[{"제목":"빵과 음료의 조합의 수 구하기","고비":true,"힌트":"빵 $7$ 개 중 $3$ 개, 음료 $5$ 개 중 $2$ 개를 고르는 조합은 각각 몇 가지일까?","식":["빵: ${}_{7}\\mathrm{C}_{3}=\\frac{7\\times6\\times5}{3\\times2\\times1}=35$","음료: ${}_{5}\\mathrm{C}_{2}=\\frac{5\\times4}{2\\times1}=10$"],"설명":"고르는 순서는 상관없으므로 각각 조합으로 센다.","확인":null,"스킬":"P4"},{"제목":"곱의 법칙으로 구하기","힌트":"빵을 고르는 일과 음료를 고르는 일이 모두 일어난다. 경우의 수는?","식":["$35\\times10=350$"],"설명":"빵을 고르는 일과 음료를 고르는 일이 모두 일어나므로 곱의 법칙을 쓴다.","확인":"350","스킬":"P4"}]},"tb-비상공수1-p051-4":{"길":"경찰관 체험을 먼저 넣고 나머지에서 고르는 조합으로 식을 세운다","단계":[{"제목":"조합으로 식 세우기","고비":true,"힌트":"경찰관 체험은 이미 포함되었다. 나머지 몇 개 중 몇 개를 더 고르면 될까?","식":["경찰관 체험을 뺀 $n-1$ 개 중 $2$ 개를 고른다","${}_{n-1}\\mathrm{C}_{2}=55$"],"설명":"$3$ 개를 택하는데 경찰관 체험이 반드시 포함되므로 나머지 $2$ 개만 고르면 된다.","확인":null,"스킬":"P4"},{"제목":"조합을 곱의 꼴로 풀어 쓰기","힌트":"${}_{n-1}\\mathrm{C}_{2}=\\frac{(n-1)(n-2)}{2}$ 이므로 $(n-1)(n-2)$ 의 값은?","식":["$\\frac{(n-1)(n-2)}{2}=55$","$(n-1)(n-2)=110$"],"설명":"${}_{m}\\mathrm{C}_{2}=\\frac{m(m-1)}{2}$ 에서 $m=n-1$ 이다. 양변에 $2$ 를 곱한다.","확인":"110","스킬":"P4"},{"제목":"연속한 두 수의 곱에서 n 구하기","힌트":"$110$ 을 연속한 두 자연수의 곱으로 쓰면?","식":["$110=11\\times10$","$n-1=11$ 에서 $n=12$"],"설명":"$(n-1)(n-2)$ 는 연속한 두 자연수의 곱이고 $n-1$ 이 큰 수이다.","확인":"12","스킬":"P4"}]},"tb-비상공수1-p051-5":{"길":"A 를 포함하는 경우와 B 를 빼고 C 를 포함하는 경우를 각각 조합으로 센다","단계":[{"제목":"a 구하기","힌트":"$\\mathrm{A}$ 는 이미 꺼냈다. 나머지 몇 개 중 몇 개를 더 꺼낼까?","식":["$\\mathrm{A}$ 를 제외한 $6$ 개 중 $2$ 개를 꺼낸다","$a={}_{6}\\mathrm{C}_{2}=15$"],"설명":"$3$ 개를 꺼내는데 $\\mathrm{A}$ 가 반드시 포함되므로 나머지 $2$ 개만 고르면 된다.","확인":"15","스킬":"P4"},{"제목":"b 구하기","고비":true,"힌트":"$\\mathrm{B}$ 는 빼고 $\\mathrm{C}$ 는 넣으면 나머지 몇 개 중 몇 개를 꺼낼까?","식":["$\\mathrm{B}$, $\\mathrm{C}$ 를 제외한 $5$ 개 중 $2$ 개를 꺼낸다","$b={}_{5}\\mathrm{C}_{2}=10$"],"설명":"$\\mathrm{C}$ 는 포함하고 $\\mathrm{B}$ 는 포함하지 않는 것으로 정해졌다. 남은 공 $5$ 개 중에서 $2$ 개를 고른다.","확인":"10","스킬":"P4"},{"제목":"a+b 계산하기","힌트":"$a$ 와 $b$ 를 더하면?","식":["$a+b=15+10=25$"],"설명":"구한 두 값을 더한다.","확인":"25","스킬":"P4"}]},"tb-비상공수1-p051-6":{"길":"가로선과 세로선에서 두 개씩 골라 직사각형을 모두 센 뒤 정사각형을 뺀다","단계":[{"제목":"직사각형 전체의 개수 구하기","고비":true,"힌트":"그림에서 가로선은 $3$ 개, 세로선은 $5$ 개이다. 직사각형은 가로선 $2$ 개와 세로선 $2$ 개로 정해진다. 몇 가지일까?","식":["가로선 $3$ 개 중 $2$ 개: ${}_{3}\\mathrm{C}_{2}=3$","세로선 $5$ 개 중 $2$ 개: ${}_{5}\\mathrm{C}_{2}=10$","직사각형 전체: $3\\times10=30$"],"설명":"직사각형은 변이 되는 가로선 $2$ 개와 세로선 $2$ 개를 고르면 하나로 정해진다. 이 개수에는 정사각형도 포함되어 있다.","확인":"30","스킬":"P4"},{"제목":"정사각형의 개수 세기","힌트":"한 변이 $1$ 칸인 정사각형과 한 변이 $2$ 칸인 정사각형은 각각 몇 개일까?","식":["한 변이 $1$ 칸: $8$ 개","한 변이 $2$ 칸: $3$ 개","정사각형 전체: $8+3=11$"],"설명":"그림은 세로 $2$ 칸, 가로 $4$ 칸이다. 한 변이 $2$ 칸인 정사각형이 놓일 수 있는 위치는 가로로 $3$ 곳이다. 세로가 $2$ 칸뿐이므로 더 큰 정사각형은 없다.","확인":"11","스킬":"P4"},{"제목":"정사각형이 아닌 직사각형 구하기","힌트":"직사각형 전체에서 정사각형을 빼면?","식":["$30-11=19$"],"설명":"구하는 것은 정사각형이 아닌 직사각형이므로 전체에서 정사각형의 개수를 뺀다.","확인":"19","스킬":"P2"}]},"tb-비상공수1-p052-1-2":{"길":"행 번호와 열 번호가 만나는 자리의 수를 읽는다","단계":[{"제목":"(2, 1) 성분 읽기","힌트":"제2행과 제1열이 만나는 자리의 수는?","식":["$A$ 의 제2행: $3,\\ 4$","$(2,\\ 1)$ 성분: $3$"],"설명":"$(i,\\ j)$ 성분은 제 $i$ 행과 제 $j$ 열이 만나는 자리의 수이다. 제2행 $3,\\ 4$ 에서 제1열에 해당하는 수를 읽는다.","확인":"3","스킬":"C6"},{"제목":"(3, 2) 성분 읽기","고비":true,"힌트":"제3행과 제2열이 만나는 자리의 수는?","식":["$A$ 의 제3행: $-1,\\ 7$","$(3,\\ 2)$ 성분: $7$"],"설명":"행을 먼저, 열을 나중에 세므로 제3행에서 제2열의 수를 읽는다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p052-2":{"길":"팀을 행, 경기를 열로 두고 표의 수를 그대로 옮긴다","단계":[{"제목":"행과 열의 기준 정하기","고비":true,"힌트":"$2\\times3$ 행렬이면 행은 몇 개이고 열은 몇 개일까?","식":["$2\\times3$: $2$행 $3$열","팀 $2$개 $\\to$ 행, 경기 $3$회 $\\to$ 열"],"설명":"$m\\times n$ 행렬은 $m$행 $n$열이다. 팀이 둘, 경기가 셋이므로 팀을 행, 경기를 열로 둔다.","확인":null,"스킬":"C6"},{"제목":"표의 수를 행렬로 쓰기","힌트":"$\\mathrm{A}$팀의 득점을 첫째 행에 쓰면 둘째 행은?","식":["$\\begin{pmatrix}0&3&2\\\\1&2&1\\end{pmatrix}$"],"설명":"첫째 행에 $\\mathrm{A}$팀의 득점을, 둘째 행에 $\\mathrm{B}$팀의 득점을 경기 순서대로 쓴다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p052-3":{"길":"그림에서 세 점의 좌표를 읽고 x좌표와 y좌표를 행으로 모은다","단계":[{"제목":"그림에서 세 점의 좌표 읽기","고비":true,"힌트":"눈금을 따라 $\\mathrm{P}$, $\\mathrm{Q}$, $\\mathrm{R}$ 의 $x$좌표와 $y$좌표는?","식":["$\\mathrm{P}(4,\\ 2)$","$\\mathrm{Q}(-3,\\ 4)$","$\\mathrm{R}(1,\\ -3)$"],"설명":"각 점에서 축에 수선을 내려 눈금을 읽는다. $\\mathrm{Q}$ 는 $y$축 왼쪽, $\\mathrm{R}$ 은 $x$축 아래에 있으므로 음수가 붙는다.","확인":null,"스킬":"S4"},{"제목":"좌표를 행렬로 정리하기","힌트":"첫째 행에는 $x$좌표, 둘째 행에는 $y$좌표를 점 순서대로 쓰면?","식":["$A=\\begin{pmatrix}4&-3&1\\\\2&4&-3\\end{pmatrix}$"],"설명":"$A=\\begin{pmatrix}a&c&e\\\\b&d&f\\end{pmatrix}$ 이므로 $\\mathrm{P}$, $\\mathrm{Q}$, $\\mathrm{R}$ 의 $x$좌표가 첫째 행, $y$좌표가 둘째 행이다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p052-4":{"길":"조건식의 분기를 먼저 가르고 여섯 성분을 구해 더한다","단계":[{"제목":"어느 식을 쓸지 가르기","고비":true,"힌트":"$2\\times3$ 행렬에서 $i>j$ 인 성분은 어느 자리뿐일까?","식":["$i>j$: $(2,\\ 1)$ 성분만 해당","나머지 다섯 성분은 $i\\le j$"],"설명":"$i=j$ 인 $(1,\\ 1)$, $(2,\\ 2)$ 성분은 $i\\le j$ 쪽에 들어간다. 따라서 $2i+j$ 는 $a_{21}$ 에만 쓴다.","확인":null,"스킬":"C6"},{"제목":"여섯 성분 구하기","힌트":"각 성분을 해당 식에 대입하면?","식":["$a_{11}=-1,\\ a_{12}=-3,\\ a_{13}=-5$","$a_{21}=2\\times2+1=5$","$a_{22}=-2,\\ a_{23}=-4$"],"설명":"$i\\le j$ 인 성분은 $a_{ij}=i-2j$ 에, $a_{21}$ 은 $2i+j$ 에 대입한다.","확인":null,"스킬":"C6"},{"제목":"모든 성분의 합 구하기","힌트":"여섯 성분을 모두 더하면?","식":["$-1-3-5+5-2-4=-10$"],"설명":"양수 $5$ 하나와 음수 다섯 개를 모두 더한다.","확인":"-10","스킬":"C6"}]},"tb-비상공수1-p052-5":{"길":"같은 자리 성분끼리 같다고 놓아 연립방정식으로 푼다","단계":[{"제목":"대응하는 성분으로 연립방정식 세우기","힌트":"두 행렬이 같으면 (1, 1) 성분과 (2, 2) 성분 사이에는 어떤 관계가 있을까?","식":["$x+3=2y$","$-2x=y-4$"],"설명":"두 행렬이 같으려면 같은 자리의 성분이 서로 같아야 한다. 값이 문자인 두 자리에서 식이 나오고 나머지 자리는 이미 같다.","확인":null,"스킬":"C6"},{"제목":"연립방정식 풀기","고비":true,"힌트":"둘째 식에서 $y$ 를 $x$ 로 나타내 첫째 식에 넣으면?","식":["$y=-2x+4$","$x+3=2(-2x+4)$","$x=1,\\ y=2$"],"설명":"$y=-2x+4$ 를 $x+3=2y$ 에 대입하면 $5x=5$ 이므로 $x=1$ 이고, 이를 대입해 $y=2$ 를 얻는다.","확인":null,"스킬":"A10"}]},"tb-비상공수1-p052-6":{"길":"a, b 를 따로 구하지 않고 합과 곱으로 바로 계산한다","단계":[{"제목":"대응하는 성분으로 합과 곱 얻기","힌트":"$A=B$ 이면 (1, 1) 성분과 (2, 2) 성분은 각각 어떤 식이 될까?","식":["$a+b=-6$","$ab=2$"],"설명":"같은 자리의 성분이 같아야 하므로 $a+b=-6$, $2=ab$ 이다.","확인":null,"스킬":"C6"},{"제목":"제곱의 합을 합과 곱으로 나타내기","고비":true,"힌트":"$a^{2}+b^{2}$ 을 $a+b$ 와 $ab$ 로 나타내면?","식":["$a^{2}+b^{2}=(a+b)^{2}-2ab$","$a^{2}+b^{2}=(-6)^{2}-2\\times2=32$"],"설명":"$(a+b)^{2}=a^{2}+b^{2}+2ab$ 에서 $a^{2}+b^{2}=(a+b)^{2}-2ab$ 이다. 합과 곱의 값을 그대로 대입한다.","확인":"32","스킬":"A2"}]},"tb-비상공수1-p053-1-1":{"길":"같은 자리 성분끼리 더하고 뺀다","단계":[{"제목":"성분별 계산식 세우기","힌트":"(1, 1) 성분은 $A$, $B$, $C$ 의 어떤 수로 계산할까?","식":["$\\begin{pmatrix}2+1-2&-1+0-1\\\\3-1+1&1-2-0\\end{pmatrix}$"],"설명":"행렬의 덧셈과 뺄셈은 같은 자리 성분끼리 한다. 빼는 $C$ 의 성분 앞에는 $-$ 를 붙인다.","확인":null,"스킬":"C6"},{"제목":"각 성분 계산하기","고비":true,"힌트":"네 칸을 각각 계산하면?","식":["$\\begin{pmatrix}1&-2\\\\3&-1\\end{pmatrix}$"],"설명":"$-1+0-1=-2$ 처럼 부호에 주의해 계산한다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p053-1-2":{"길":"행렬을 문자처럼 먼저 정리해 A 를 지운 뒤 계산한다","단계":[{"제목":"식을 먼저 정리하기","고비":true,"힌트":"$A$ 를 포함한 항끼리 정리하면 어떤 식이 남을까?","식":["$A+2B-2C-A+C$","$=2B-C$"],"설명":"행렬도 문자처럼 괄호를 풀고 같은 문자끼리 모을 수 있다. $A$ 가 지워져 $2B-C$ 만 남는다.","확인":null,"스킬":"A1"},{"제목":"2B 구하기","힌트":"$B$ 의 모든 성분에 $2$ 를 곱하면?","식":["$2B=\\begin{pmatrix}2&0\\\\-2&-4\\end{pmatrix}$"],"설명":"실수배는 모든 성분에 같은 수를 곱한다.","확인":null,"스킬":"C6"},{"제목":"2B − C 계산하기","힌트":"같은 자리 성분끼리 빼면?","식":["$2B-C=\\begin{pmatrix}2-2&0-1\\\\-2+1&-4-0\\end{pmatrix}=\\begin{pmatrix}0&-1\\\\-1&-4\\end{pmatrix}$"],"설명":"$2B$ 와 $C$ 의 같은 자리 성분끼리 뺀다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p053-2":{"길":"X 에 대해 먼저 풀어 3A − B 로 만든 뒤 대입한다","단계":[{"제목":"X 에 대해 정리하기","고비":true,"힌트":"$X$ 항을 한쪽으로 모으면 $X$ 는 $A$, $B$ 의 어떤 식이 될까?","식":["$4X-B=2X+6A-3B$","$2X=6A-2B$","$X=3A-B$"],"설명":"$-3(-2A+B)$ 를 풀면 $6A-3B$ 이다. $X$ 항을 좌변으로 모으고 양변을 $2$ 로 나눈다.","확인":null,"스킬":"A1"},{"제목":"3A 구하기","힌트":"$A$ 의 모든 성분에 $3$ 을 곱하면?","식":["$3A=\\begin{pmatrix}-9&3\\\\6&15\\end{pmatrix}$"],"설명":"실수배는 모든 성분에 같은 수를 곱한다.","확인":null,"스킬":"C6"},{"제목":"3A − B 계산하기","힌트":"같은 자리 성분끼리 빼면?","식":["$X=\\begin{pmatrix}-9-0&3+4\\\\6-1&15-7\\end{pmatrix}=\\begin{pmatrix}-9&7\\\\5&8\\end{pmatrix}$"],"설명":"$B$ 의 성분 $-4$ 를 빼면 $+4$ 가 된다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p053-3-1":{"길":"행의 성분과 열의 성분을 짝지어 곱해 더한다","단계":[{"제목":"곱의 크기 확인하기","힌트":"$1\\times2$ 행렬과 $2\\times1$ 행렬을 곱하면 크기는?","식":["$(1\\times2)(2\\times1)\\to1\\times1$"],"설명":"앞 행렬의 열 수와 뒤 행렬의 행 수가 같으므로 곱할 수 있고, 결과는 앞의 행 수와 뒤의 열 수로 정해져 $1\\times1$ 행렬이다.","확인":null,"스킬":"C6"},{"제목":"성분끼리 곱해 더하기","고비":true,"힌트":"행의 첫째 수에 열의 첫째 수를, 둘째 수에 둘째 수를 곱해 더하면?","식":["$(-3)\\times2+2\\times1=-4$","$\\begin{pmatrix}-4\\end{pmatrix}$"],"설명":"행의 성분과 열의 성분을 차례로 짝지어 곱한 뒤 모두 더한다. 결과는 $1\\times1$ 행렬로 쓴다.","확인":"-4","스킬":"C6"}]},"tb-비상공수1-p053-3-2":{"길":"행 하나를 각 열에 차례로 곱해 성분을 구한다","단계":[{"제목":"첫째 열과 곱한 성분 구하기","힌트":"행 $(1\\ \\ -2)$ 와 첫째 열의 성분을 짝지어 곱해 더하면?","식":["$1\\times1+(-2)\\times0=1$"],"설명":"$1\\times2$ 행렬과 $2\\times2$ 행렬의 곱은 $1\\times2$ 행렬이다. 첫째 성분은 행과 첫째 열의 성분을 차례로 곱해 더한 값이다.","확인":"1","스킬":"C6"},{"제목":"둘째 열과 곱한 성분 구하기","고비":true,"힌트":"같은 행과 둘째 열로 계산하면?","식":["$1\\times1+(-2)\\times(-3)=7$","$\\begin{pmatrix}1&7\\end{pmatrix}$"],"설명":"둘째 열 $1,\\ -3$ 과 곱한다. $(-2)\\times(-3)=6$ 이므로 부호에 주의한다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p053-3-3":{"길":"(i, j) 성분은 앞 행렬의 i행과 뒤 행렬의 j열을 곱해 구한다","단계":[{"제목":"첫째 행의 두 성분 구하기","힌트":"앞 행렬의 첫째 행 $(2\\ \\ 0)$ 을 뒤 행렬의 각 열에 곱하면?","식":["$2\\times1+0\\times(-3)=2$","$2\\times2+0\\times4=4$"],"설명":"$(1,\\ 1)$ 성분은 첫째 행과 첫째 열, $(1,\\ 2)$ 성분은 첫째 행과 둘째 열의 성분을 곱해 더한다.","확인":null,"스킬":"C6"},{"제목":"둘째 행의 두 성분 구하기","고비":true,"힌트":"앞 행렬의 둘째 행 $(0\\ \\ -1)$ 을 각 열에 곱하면?","식":["$0\\times1+(-1)\\times(-3)=3$","$0\\times2+(-1)\\times4=-4$","$\\begin{pmatrix}2&4\\\\3&-4\\end{pmatrix}$"],"설명":"같은 방법으로 둘째 행과 첫째 열, 둘째 행과 둘째 열을 곱한다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p053-4":{"길":"A 로 묶어 B + C 를 먼저 더하면 곱셈이 한 번으로 준다","단계":[{"제목":"A 로 묶기","고비":true,"힌트":"$AB+AC$ 에서 공통인 $A$ 를 앞으로 묶으면?","식":["$AB+AC=A(B+C)$"],"설명":"행렬의 곱셈도 분배법칙이 성립하므로 앞에 곱해진 $A$ 로 묶을 수 있다. 곱셈을 두 번 하지 않아도 된다.","확인":null,"스킬":"A1"},{"제목":"B + C 구하기","힌트":"같은 자리 성분끼리 더하면?","식":["$B+C=\\begin{pmatrix}0+2&2+0\\\\3-1&-1+7\\end{pmatrix}=\\begin{pmatrix}2&2\\\\2&6\\end{pmatrix}$"],"설명":"덧셈은 같은 자리 성분끼리 한다.","확인":null,"스킬":"C6"},{"제목":"A(B + C) 계산하기","힌트":"$A$ 의 각 행을 $B+C$ 의 각 열에 곱하면?","식":["$A(B+C)=\\begin{pmatrix}1\\times2+3\\times2&1\\times2+3\\times6\\\\4\\times2+2\\times2&4\\times2+2\\times6\\end{pmatrix}$","$=\\begin{pmatrix}8&20\\\\12&20\\end{pmatrix}$"],"설명":"$(i,\\ j)$ 성분은 $A$ 의 $i$ 행과 $B+C$ 의 $j$ 열을 곱해 더한 값이다.","확인":null,"스킬":"C6"}]},"tb-비상공수1-p053-5":{"길":"곱을 성분으로 쓴 뒤 문자가 하나씩 든 칸부터 비교한다","단계":[{"제목":"좌변의 곱을 성분으로 쓰기","힌트":"좌변 행렬의 네 성분을 $x$, $y$ 로 나타내면?","식":["$\\begin{pmatrix}-2\\times4+3\\times2&-2y+3\\times(-3)\\\\4x+1\\times2&xy+1\\times(-3)\\end{pmatrix}$","$=\\begin{pmatrix}-2&-2y-9\\\\4x+2&xy-3\\end{pmatrix}$"],"설명":"$(i,\\ j)$ 성분은 앞 행렬의 $i$ 행과 뒤 행렬의 $j$ 열을 곱해 더한 값이다. $(1,\\ 1)$ 성분 $-2$ 는 우변과 이미 같다.","확인":null,"스킬":"C6"},{"제목":"x, y 의 값 구하기","고비":true,"힌트":"$y$ 만 든 칸과 $x$ 만 든 칸을 우변과 비교하면?","식":["$-2y-9=-13\\ \\to\\ y=2$","$4x+2=6\\ \\to\\ x=1$"],"설명":"같은 자리 성분이 같아야 하므로 문자가 하나만 든 칸에서 $y$, $x$ 를 먼저 구한다.","확인":null,"스킬":"A10"},{"제목":"a 의 값 구하기","힌트":"$(2,\\ 2)$ 성분 $xy-3$ 에 $x$, $y$ 를 넣으면?","식":["$a=xy-3=1\\times2-3=-1$"],"설명":"$(2,\\ 2)$ 성분이 $a$ 와 같으므로 구한 $x$, $y$ 를 대입한다.","확인":"-1","스킬":"C6"}]},"tb-비상공수1-p053-6":{"길":"A² 을 구하고 E 는 대각선에만 1 이 있는 행렬로 쓴다","단계":[{"제목":"A² 구하기","고비":true,"힌트":"$A$ 를 두 번 곱하면 네 성분은?","식":["$A^{2}=\\begin{pmatrix}3\\times3+2\\times(-2)&3\\times2+2\\times(-1)\\\\-2\\times3+(-1)\\times(-2)&-2\\times2+(-1)\\times(-1)\\end{pmatrix}$","$=\\begin{pmatrix}5&4\\\\-4&-3\\end{pmatrix}$"],"설명":"$A^{2}=AA$ 이므로 $(i,\\ j)$ 성분은 $A$ 의 $i$ 행과 $A$ 의 $j$ 열을 곱해 더한 값이다.","확인":null,"스킬":"C6"},{"제목":"단위행렬을 넣어 식 세우기","힌트":"$E$ 는 어떤 성분으로 이루어진 행렬일까?","식":["$E=\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix}$","$A^{2}-A+E=\\begin{pmatrix}5&4\\\\-4&-3\\end{pmatrix}-\\begin{pmatrix}3&2\\\\-2&-1\\end{pmatrix}+\\begin{pmatrix}1&0\\\\0&1\\end{pmatrix}$"],"설명":"단위행렬 $E$ 는 대각선 성분이 $1$, 나머지가 $0$ 인 행렬이다.","확인":null,"스킬":"C6"},{"제목":"성분별로 계산하기","힌트":"같은 자리 성분끼리 더하고 빼면?","식":["$\\begin{pmatrix}5-3+1&4-2+0\\\\-4+2+0&-3+1+1\\end{pmatrix}=\\begin{pmatrix}3&2\\\\-2&-1\\end{pmatrix}$"],"설명":"$(2,\\ 2)$ 성분은 $-3-(-1)+1=-1$ 이다. 빼는 행렬의 음수 성분 부호에 주의한다.","확인":null,"스킬":"C6"}]}});
